    # ---- dynamics.py: the stepper and the width-only control -------------
    dyn_pulse = mdl.RaisedCosinePulse(1.0, 4.0, 0.0)
    dyn_train = dyn.PulseTrain((dyn_pulse,))
    dyn_full = dyn.ClockPath(0.4, dyn_train, "full", 0.0)
    dyn_control = dyn.ClockPath(0.4, dyn_train, "width_only",
                                dyn.FIXED_CONTRACTION_RATE)
    dyn_entry, dyn_exit = dyn_full.schedule.windows[0]
    dyn_state = dyn_full.initial_state(dyn_entry, 0.3)
    dyn_live = dyn_control.entry_handoff(
        dyn_control.initial_state(dyn_entry, 0.3))
    # The handoffs are directed, so an exit control has to sit on an exit
    # crossing carrying the pair an eligible segment ending there would
    # have reconstructed.
    _leaving = dyn.nearest_lift(float(mdl.boundary_phase(0.4)), 0.3)
    dyn_leaving = dyn.PathState(dyn_exit, 0.3, _leaving, 0.3 - _leaving)
    dyn_hold = stoch.TreeLeaf(dyn_entry, 0.0, 0.0, "root", 0)
    stationary_drive = dyn.StationaryDrive(1.0)

    def _stale_state(field, value):
        """A PathState edited past its own constructor."""
        state = dyn.PathState(0.0, 0.3)
        object.__setattr__(state, field, value)
        return state

    def _stale_leaf(field, value):
        """A TreeLeaf edited past Ticket 02's own constructor."""
        leaf = stoch.TreeLeaf(dyn_entry, 0.0, 0.0, "root", 0)
        object.__setattr__(leaf, field, value)
        return leaf

