    def race_call(fn, *, population=_KEEP, criterion=_KEEP, stream=_KEEP,
                  trial=0, start_index=0, steps=_KEEP, clock_block=2,
                  step_window=4, extra=()):
        return fn(race["population"] if population is _KEEP else population,
                  race["criterion"] if criterion is _KEEP else criterion,
                  race["stream"] if stream is _KEEP else stream,
                  trial, start_index,
                  race["steps"] if steps is _KEEP else steps, *extra,
                  clock_block, step_window)

    def race_probes(fn, extra=()):
        """The eight arguments every race door shares, probed once each."""
        return [
            T("population", "a bare tuple of paths rather than a population",
              lambda: race_call(fn, population=race["paths"], extra=extra)),
            T("criterion", "not a lock criterion",
              lambda: race_call(fn, criterion=None, extra=extra)),
            T("stream", "not a noise stream",
              lambda: race_call(fn, stream=None, extra=extra)),
            V("trial", "negative",
              lambda: race_call(fn, trial=-1, extra=extra)),
            V("start_index", "negative",
              lambda: race_call(fn, start_index=-1, extra=extra)),
            V("steps", "zero", lambda: race_call(fn, steps=0, extra=extra)),
            V("clock_block", "zero",
              lambda: race_call(fn, clock_block=0, extra=extra)),
            V("step_window", "zero",
              lambda: race_call(fn, step_window=0, extra=extra)),
        ]

