def _refuser(problems):
    """Return a ``refused(label, call)`` helper appending to ``problems``."""
    def refused(label, call):
        try:
            call()
        except (ValueError, TypeError):
            return
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"{label}: raised {type(exc).__name__}")
        else:
            problems.append(f"{label}: ACCEPTED")
    return refused


@check("every binned row carries its risk, events, censoring and width, and "
       "the rate is the probability divided by that width", covers=[96])
def check_risk_table_display():
    """The one omission that lets a probability be read as a rate.

    ``events / at_risk`` is a discrete conditional failure probability.  It is
    dimensionless and it depends on how wide the bin is.  ``events / (at_risk *
    width)`` has units of inverse time and is the only one of the two that may
    be compared against a relaxation rate, a flux or a constant hazard.  A
    table that printed the first without the width would let the two be
    confused, and the confusion is invisible: both are small positive numbers
    that rise and fall together.

    So the check is that the omission is impossible.  Every row emitted carries
    exactly :data:`~.observables.DISPLAY_COLUMNS`; the rate is exactly the
    probability divided by exactly the row's own width; and the two are
    *demonstrably different numbers*, so the identity is not being satisfied by
    a width of one.

    The rest is conservation, checked against the run rather than against the
    table's own arithmetic: the bucketing is re-derived here by an independent
    loop over the ledger's commit times, including the half-open convention at
    an exact edge, and the totals must equal the run's committed and unresolved
    counts.  Refusals cover a gap between rows, a risk count asserted beside
    the exits that determine it, an entry after the table opens, and a table
    that does not span the run's whole observation window.
    """
    fixture = _ticket06_fixture()
    ledger, manifest = fixture["ledger"], fixture["manifest"]
    opened, closed = fixture["opened"], fixture["closed"]
    problems = []
    refused = _refuser(problems)

    table = fixture["table"]
    rows = table.rows()
    for index, row in enumerate(rows):
        if tuple(row) != obsv.DISPLAY_COLUMNS:
            problems.append(f"row {index} has keys {tuple(row)}, not "
                            f"{obsv.DISPLAY_COLUMNS}")

    # A hand-built half-width table sits beside the run's own, so the
    # discrimination below does not depend on this fixture having committed.
    demo = _hand_table(((2, 0), (1, 1), (3, 3)))
    rows = rows + demo.rows()
    intervals = table.intervals + demo.intervals

    worst_rate = 0.0
    differing = 0
    for index, (row, interval) in enumerate(zip(rows, intervals)):
        if row["at_risk"] == 0:
            continue
        expected = row["events"] / (row["at_risk"] * row["width"])
        worst_rate = max(worst_rate, abs(row["hazard_rate"] - expected))
        if row["hazard_rate"] != row["conditional_failure"] / row["width"]:
            problems.append(f"row {index}: the rate is not the probability "
                            f"divided by the width")
        if row["events"] and row["hazard_rate"] != row["conditional_failure"]:
            differing += 1
        if row["width"] != interval.right - interval.left:
            problems.append(f"row {index}: width is not right - left")
    if not differing:
        problems.append("no row has a rate that differs from its conditional "
                        "probability, so this run cannot discriminate between "
                        "them (the bins are one time unit wide)")

    # An independent bucketing of the same commit times, including the
    # half-open rule at an exact edge.
    edges = fixture["edges"]
    events = [row["commit_time"] for row in ledger.rows("ledger")
              if row["category"] == "committed"]
    unresolved = sum(1 for row in ledger.rows("ledger")
                     if row["category"] != "committed")
    for index in range(len(edges) - 1):
        left, right = edges[index], edges[index + 1]
        independent = sum(1 for t in events if left < t <= right)
        if rows[index]["events"] != independent:
            problems.append(f"bin {index} holds {rows[index]['events']} "
                            f"events; an independent count over "
                            f"({left}, {right}] gives {independent}")
    if table.events != len(events):
        problems.append(f"the table holds {table.events} events and the "
                        f"ledger records {len(events)} commitments")
    if table.censored != unresolved:
        problems.append(f"the table censors {table.censored} trials and the "
                        f"ledger holds {unresolved} unresolved ones")
    if table.events + table.censored != manifest.trials:
        problems.append("events and censorings do not conserve the trials")
    survival = [value for _, _, value in table.survival()]
    if any(b > a for a, b in zip(survival, survival[1:])):
        problems.append(f"survival is not non-increasing: {survival}")

    edge = obsv.RiskInterval(0.0, 1.0, 4, 1, 0)
    if edge.conditional_failure != 0.25 or edge.hazard_rate != 0.25:
        problems.append("a unit-width interval disagrees with its own "
                        "definition")

    refused("a table with a gap between two rows",
            lambda: obsv.RiskTable((obsv.RiskInterval(0.0, 1.0, 4, 1, 0),
                                    obsv.RiskInterval(2.0, 3.0, 3, 3, 0)),
                                   4, 0.0))
    refused("a table whose risk count disagrees with its exits",
            lambda: obsv.RiskTable((obsv.RiskInterval(0.0, 1.0, 4, 1, 0),
                                    obsv.RiskInterval(1.0, 2.0, 4, 3, 0)),
                                   4, 0.0))
    refused("a table leaving survivors at its close",
            lambda: obsv.RiskTable((obsv.RiskInterval(0.0, 1.0, 4, 1, 0),),
                                   4, 0.0))
    refused("an interval losing more trials than it had",
            lambda: obsv.RiskInterval(0.0, 1.0, 2, 3, 0))
    refused("a zero-width interval",
            lambda: obsv.RiskInterval(1.0, 1.0, 4, 0, 4))
    refused("a table starting after the run's window opens",
            lambda: obsv.risk_table(ledger, (0.5 * (opened + closed), closed)))
    refused("a table ending before the run's window closes",
            lambda: obsv.risk_table(ledger, (opened,
                                             0.5 * (opened + closed))))
    refused("non-increasing edges",
            lambda: obsv.risk_table(ledger, (opened, closed, closed)))

    full = obsv.uniform_edges(opened, closed, 3)
    if full[0] != opened or full[-1] != closed:
        problems.append("uniform_edges does not reproduce the window's "
                        "endpoints exactly")

    return Result("every binned row carries its risk, events, censoring and "
                  "width, and the rate is the probability divided by that "
                  "width", not problems, worst_rate, 1e-15,
                  (f"all {len(rows)} rows carry exactly the "
                   f"{len(obsv.DISPLAY_COLUMNS)} display fields; the time rate "
                   f"equals events/(risk*width) to {worst_rate:.1e} and "
                   f"differs from the conditional probability in {differing} "
                   f"rows, so the division is doing work; an independent "
                   f"bucketing of the ledger's own commit times under the "
                   f"half-open rule reproduces every bin; {table.events} "
                   f"events and {table.censored} censorings conserve "
                   f"{manifest.trials} trials; survival is non-increasing; and "
                   f"a gap, an asserted risk count, a leftover survivor, an "
                   f"over-drawn interval, a zero-width interval, a late start, "
                   f"an early end and non-increasing edges are all refused")
                  if not problems else "; ".join(problems[:6]), covers=(96,))


@check("survival and cumulative hazard reproduce known censored synthetic "
       "truth", covers=[97])
def check_survival_truth():
    """Product-limit survival and Nelson-Aalen, against arithmetic on paper.

    Three separate statements:

    1. **A hand-built table matches hand-computed truth.**  Ten trials, four
       intervals, events and censorings declared: the product-limit survival is
       ``0.8, 0.7, 0.7, 0.35`` and the cumulative hazard is
       ``0.2, 0.325, 0.325, 0.825``.  Both are written out here, so the check
       compares the implementation against a number rather than against a
       second copy of itself.

    2. **Censoring is not an event.**  The same events with the censorings
       moved earlier give a *different* survival, because a trial censored out
       of the risk set was never at risk for the later intervals.

    3. **The binning is visible in the probability and not in the rate.**  An
       exponential truth with rate ``lambda`` binned at width ``w`` has a
       conditional failure probability of ``1 - exp(-lambda w)`` and a time
       rate of ``(1 - exp(-lambda w)) / w``.  Sixty thousand synthetic trials
       are binned at two widths; each estimate must match its own known value,
       and the *probability* must change by nearly a factor of two between the
       two binnings while the *rate* changes by about ten percent.
    """
    problems = []

    table = _hand_table(((2, 0), (1, 1), (0, 0), (3, 3)))
    survival = [value for _, _, value in table.survival()][1:]
    hazard = [value for _, value in table.cumulative_hazard()][1:]
    expected_s = [0.8, 0.8 * 7.0 / 8.0, 0.8 * 7.0 / 8.0,
                  0.8 * 7.0 / 8.0 * 0.5]
    expected_h = [0.2, 0.2 + 1.0 / 8.0, 0.2 + 1.0 / 8.0,
                  0.2 + 1.0 / 8.0 + 0.5]
    worst = max(max(abs(a - b) for a, b in zip(survival, expected_s)),
                max(abs(a - b) for a, b in zip(hazard, expected_h)))
    if worst > 1e-15:
        problems.append(f"the hand-built table's survival {survival} and "
                        f"hazard {hazard} differ from {expected_s} and "
                        f"{expected_h}")
    risks = [interval.at_risk for interval in table.intervals]
    if risks != [10, 8, 6, 6]:
        problems.append(f"the risk sets are {risks}, expected [10, 8, 6, 6]")

    moved = _hand_table(((2, 3), (1, 1), (0, 0), (3, 0)))
    moved_survival = [value for _, _, value in moved.survival()][1:]
    if abs(moved_survival[-1] - survival[-1]) < 1e-9:
        problems.append("moving the censorings earlier did not change the "
                        "survival, so censoring is being treated as an event")

    rate, horizon, trials = 2.0, 1.0, 60000
    rng = np.random.default_rng(20260828)
    times = rng.exponential(1.0 / rate, trials)
    measured = {}
    for bins in (10, 5):
        width = horizon / bins
        edges = np.linspace(0.0, horizon, bins + 1)
        intervals, at_risk = [], trials
        for index in range(bins):
            left, right = float(edges[index]), float(edges[index + 1])
            events = int(np.count_nonzero((times > left) & (times <= right)))
            censored = (int(np.count_nonzero(times > horizon))
                        if index == bins - 1 else 0)
            intervals.append(obsv.RiskInterval(left, right, at_risk, events,
                                               censored))
            at_risk -= events + censored
        built = obsv.RiskTable(tuple(intervals), trials, 0.0)
        interior = [row for row in built.rows()[:-1] if row["at_risk"] > 200]
        measured[bins] = (
            float(np.mean([row["conditional_failure"] for row in interior])),
            float(np.mean([row["hazard_rate"] for row in interior])), width)

    truth = {bins: 1.0 - math.exp(-rate * w)
             for bins, (_, _, w) in measured.items()}
    worst_truth = 0.0
    for bins, (probability, hazard_rate, width) in measured.items():
        worst_truth = max(worst_truth, abs(probability - truth[bins]),
                          abs(hazard_rate - truth[bins] / width) * width)
    if worst_truth > 0.01:
        problems.append(f"the exponential truth is not recovered: "
                        f"{measured} against {truth}")
    probability_ratio = measured[5][0] / measured[10][0]
    rate_ratio = measured[5][1] / measured[10][1]
    if not 1.7 < probability_ratio < 1.95:
        problems.append(f"doubling the bin width changed the conditional "
                        f"probability by {probability_ratio:.3f}, expected "
                        f"about 1.8")
    if not 0.85 < rate_ratio < 0.98:
        problems.append(f"doubling the bin width changed the time rate by "
                        f"{rate_ratio:.3f}, expected about 0.9")

    return Result("survival and cumulative hazard reproduce known censored "
                  "synthetic truth", not problems, max(worst, worst_truth),
                  0.01,
                  (f"a hand-built ten-trial table with censoring in two of "
                   f"four intervals reproduces the product-limit survival "
                   f"{[round(v, 6) for v in expected_s]} and the Nelson-Aalen "
                   f"cumulative hazard {[round(v, 6) for v in expected_h]} to "
                   f"{worst:.1e}, with risk sets {risks}; moving the "
                   f"censorings earlier changes the answer, so censoring is "
                   f"not being counted as an event; and {trials} exponential "
                   f"trials at rate {rate} binned ten ways and five ways each "
                   f"recover their own known conditional probability and time "
                   f"rate to {worst_truth:.3f} — the probability changes by "
                   f"{probability_ratio:.2f}x between the two binnings while "
                   f"the rate changes by {rate_ratio:.2f}x, which is the "
                   f"80-percent error reporting one as the other would make")
                  if not problems else "; ".join(problems[:6]), covers=(97,))


@check("the unresolved fraction keeps its three causes and every co-completer "
       "is retained", covers=[98])
def check_unresolved_and_winners():
    """A zero can be three different things, and a tie is not an error.

    The unresolved fraction is a result, and pooling its three causes throws
    away the only diagnostic that separates a tongue that never opened from a
    band that was never reached from a dwell that was never completed.  So the
    four categories are counted separately, reconciled against an independent
    tally of the ledger's own rows, and a tally that does not add up is
    refused.

    The winner side is the mirror image.  Several clocks can complete on one
    endpoint; all of them are retained and none is chosen, so the per-clock win
    counts sum to the number of **co-completers** rather than to the number of
    committed trials.  Those two totals are reported side by side and the
    multiplicity histogram has to reconcile with both.
    """
    fixture = _ticket06_fixture()
    ledger = fixture["ledger"]
    counts, winners = fixture["counts"], fixture["winners"]
    manifest = fixture["manifest"]
    problems = []
    refused = _refuser(problems)

    independent = {name: 0 for name in rawled.TRIAL_CATEGORIES}
    for row in ledger.rows("ledger"):
        independent[row["category"]] += 1
    for name in rawled.TRIAL_CATEGORIES:
        if getattr(counts, name) != independent[name]:
            problems.append(f"{name}: the tally says {getattr(counts, name)} "
                            f"and an independent count gives "
                            f"{independent[name]}")
    if counts.unresolved != sum(independent[n]
                                for n in obsv.UNRESOLVED_CATEGORIES):
        problems.append("the unresolved total does not equal its three causes")
    if counts.committed + counts.unresolved != manifest.trials:
        problems.append("the categories are not exhaustive")

    q = counts.commitment_probability
    expected_h = (float("inf") if q >= 1.0 else -math.log1p(-q))
    if obsv.endpoint_cumulative_hazard(counts) != expected_h:
        problems.append("the endpoint cumulative hazard is not -log(1-q)")
    if obsv.endpoint_cumulative_hazard(
            obsv.CommitmentCounts(5, 5, 0, 0, 0)) != float("inf"):
        problems.append("an all-committed run does not report an infinite "
                        "endpoint cumulative hazard")

    if len(winners.wins) != manifest.clocks:
        problems.append(f"the winner table covers {len(winners.wins)} of "
                        f"{manifest.clocks} clocks")
    if winners.detunings != tuple(manifest.value("detunings")):
        problems.append("the winner table's detunings are not the manifest's")
    ledger_winners = [row["winners"] for row in ledger.rows("ledger")
                      if row["winners"]]
    if winners.committed_trials != len(ledger_winners):
        problems.append(f"{winners.committed_trials} committed trials against "
                        f"{len(ledger_winners)} rows naming a winner")
    if winners.co_completers != sum(len(w) for w in ledger_winners):
        problems.append("the win counts do not sum to the co-completers")
    if winners.committed_trials != counts.committed:
        problems.append("the winner table and the category tally disagree "
                        "about how many trials committed")

    # Four committed trials: two with one winner, one with two, one with
    # three.  Seven co-completers, and the per-clock wins must sum to seven.
    tied = obsv.WinnerMismatch((0, 1, 2), (-1.0, 0.0, 1.0), (2, 3, 2), 4,
                               ((1, 2), (2, 1), (3, 1)))
    if tied.co_completers != 7 or tied.tied_trials != 2:
        problems.append(f"a hand-built tie reports {tied.co_completers} "
                        f"co-completers in {tied.tied_trials} tied trials, "
                        f"expected 7 in 2")
    if tied.co_completers <= tied.committed_trials:
        problems.append("a tie did not make the co-completer count exceed the "
                        "committed-trial count, so the two are not distinct")

    refused("a tally whose categories overcount the trials",
            lambda: obsv.CommitmentCounts(10, 5, 3, 3, 1))
    refused("a tally whose categories undercount the trials",
            lambda: obsv.CommitmentCounts(10, 1, 1, 1, 1))
    refused("a winner table whose wins contradict its histogram",
            lambda: obsv.WinnerMismatch((0, 1), (-0.5, 0.5), (2, 2), 3,
                                        ((1, 3),)))
    refused("a winner table with a zero-winner committed trial",
            lambda: obsv.WinnerMismatch((0, 1), (-0.5, 0.5), (2, 1), 3,
                                        ((0, 1), (1, 2))))
    refused("a winner table missing a clock's detuning",
            lambda: obsv.WinnerMismatch((0, 1), (-0.5,), (2, 1), 3, ((1, 3),)))

    return Result("the unresolved fraction keeps its three causes and every "
                  "co-completer is retained", not problems,
                  float(len(problems)), 0.0,
                  (f"the four categories — {independent} — are counted "
                   f"separately, reconcile with an independent tally of the "
                   f"ledger's own rows, are exhaustive over "
                   f"{manifest.trials} trials, and keep the three unresolved "
                   f"causes apart; the endpoint cumulative hazard is "
                   f"-log(1-q) and is infinite when every trial commits; the "
                   f"winner table covers all {manifest.clocks} clocks "
                   f"including the ones that never won, its wins sum to "
                   f"{winners.co_completers} co-completers over "
                   f"{winners.committed_trials} committed trials, and a "
                   f"hand-built three-way tie reports 7 co-completers in 2 "
                   f"tied trials; a tally that does not add up, a winner "
                   f"table that contradicts its own histogram, a zero-winner "
                   f"commitment and a missing detuning are all refused")
                  if not problems else "; ".join(problems[:6]), covers=(98,))


@check("the complementary-log-log estimator recovers declared exponents from "
       "counts alone and keeps every cell", covers=[99])
def check_cloglog_recovery():
    """Known exponents in, known exponents out — with the hard cells kept.

    Four statements:

    1. **Recovery.**  Counts taken from the model itself at ``p = 1, 2, 3`` are
       recovered to better than 0.02, and three independent draws at each
       exponent land within four of their own reported standard errors.

    2. **The boundary cells are kept.**  A steep sweep produces cells with zero
       events at the weak end and every event at the strong end.  Both are
       retained, the fit still succeeds, and ``cells_fitted`` equals
       ``cells_declared``.

    3. **Dropping them would change the answer.**  The same data refitted with
       the boundary cells deleted gives a *different* exponent.

    4. **The naive route is not available.**  The package's unweighted log-log
       fitter refuses a zero-event cell outright rather than dropping it.

    The likelihood itself is checked against an independently written one: the
    fitted parameters must maximize a log-likelihood transcribed here from the
    model formula, verified by a central-difference gradient at the optimum and
    by the fact that no point on a small grid around it scores higher.
    """
    problems = []
    recovered = []
    worst_exact = 0.0
    for exponent in (1.0, 2.0, 3.0):
        exact = sta.fit_exponent(_counted_design(_SWEEP_COUPLINGS, exponent,
                                                 4000))
        worst_exact = max(worst_exact, abs(exact.exponent - exponent))
        recovered.append((exponent, exact.exponent, exact.exponent_stderr))
        if exact.cells_fitted != len(_SWEEP_COUPLINGS):
            problems.append(f"p={exponent}: {exact.cells_fitted} of "
                            f"{len(_SWEEP_COUPLINGS)} cells entered the fit")
        for seed in range(3):
            design = _synthetic_design(exponent, trials=4000,
                                       seed=900 + 10 * int(exponent) + seed)
            report = sta.fit_exponent(design)
            if report.cells_fitted != len(design.cells):
                problems.append(f"p={exponent} seed {seed}: "
                                f"{report.cells_fitted} of "
                                f"{len(design.cells)} cells entered the fit")
            if abs(report.exponent - exponent) > 4.0 * report.exponent_stderr:
                problems.append(
                    f"p={exponent} seed {seed}: recovered "
                    f"{report.exponent:.4f}, which is more than four of its "
                    f"own standard errors ({report.exponent_stderr:.4f}) from "
                    f"the declared truth")
    if worst_exact > 0.02:
        problems.append(f"the estimator misses a declared exponent by "
                        f"{worst_exact:.4f} on counts drawn from the model "
                        f"itself")

    steep_couplings = (0.2, 0.3, 0.45, 0.6, 0.7, 0.85, 1.0, 1.5)
    steep = _counted_design(steep_couplings, 6.0, 500)
    steep_report = sta.fit_exponent(steep)
    if not (steep_report.zero_event_cells and steep_report.all_event_cells):
        problems.append(f"the steep sweep produced "
                        f"{steep_report.zero_event_cells} zero-event and "
                        f"{steep_report.all_event_cells} all-event cells; this "
                        f"fixture is supposed to have both")
    if steep_report.cells_fitted != len(steep.cells):
        problems.append("the steep sweep did not fit every cell")
    interior = tuple(cell for cell in steep.cells
                     if not (cell.is_zero_event or cell.is_all_event))
    trimmed_gap = float("nan")
    if len(interior) >= sta.MIN_CELLS:
        trimmed = sta.fit_exponent(sta.ScalingDesign(interior,
                                                     "master_trial"))
        trimmed_gap = abs(trimmed.exponent - steep_report.exponent)
        if trimmed_gap < 1e-6:
            problems.append("deleting the boundary cells did not change the "
                            "exponent, so retaining them proves nothing here")
    else:
        problems.append(f"only {len(interior)} interior cells remain, so the "
                        f"deletion control cannot be run")

    zero_cell = next(cell for cell in steep.cells if cell.is_zero_event)
    try:
        ana.fit_log_log_exponent(
            [cell.coupling for cell in steep.cells],
            [cell.committed / cell.trials for cell in steep.cells])
    except ValueError:
        pass
    else:
        problems.append("the unweighted log-log fitter accepted a zero "
                        "proportion, so the naive route silently drops cells")

    design = _synthetic_design(2.0, trials=2000, seed=940)
    report = sta.fit_exponent(design)

    def independent_loglik(amplitude, exponent):
        total = 0.0
        for cell in design.cells:
            H = math.exp(amplitude + exponent * math.log(cell.coupling))
            q = -math.expm1(-H)
            y, n = cell.committed, cell.trials
            if y:
                total += y * math.log(q)
            total -= (n - y) * H
        return total

    best = independent_loglik(report.amplitude, report.exponent)
    higher = 0
    for da in (-1e-3, 0.0, 1e-3):
        for dp in (-1e-3, 0.0, 1e-3):
            if da == dp == 0.0:
                continue
            if independent_loglik(report.amplitude + da,
                                  report.exponent + dp) > best + 1e-9:
                higher += 1
    if higher:
        problems.append(f"{higher} of 8 neighbouring parameter pairs score "
                        f"higher on an independently written likelihood, so "
                        f"the reported fit is not its maximum")
    step = 1e-6
    gradient = max(
        abs(independent_loglik(report.amplitude + step, report.exponent)
            - independent_loglik(report.amplitude - step, report.exponent))
        / (2 * step),
        abs(independent_loglik(report.amplitude, report.exponent + step)
            - independent_loglik(report.amplitude, report.exponent - step))
        / (2 * step))
    scale = max(1.0, abs(best))
    if gradient / scale > 1e-6:
        problems.append(f"the independent gradient at the reported optimum is "
                        f"{gradient:.3e} against a likelihood of {best:.3e}")

    return Result("the complementary-log-log estimator recovers declared "
                  "exponents from counts alone and keeps every cell",
                  not problems, gradient / scale, 1e-6,
                  ("declared exponents recovered from model counts as "
                   + ", ".join(f"{t:.0f} -> {v:.4f}+-{s:.4f}"
                               for t, v, s in recovered)
                   + f" (worst miss {worst_exact:.4f}), and three independent "
                     f"draws at each exponent all landing within four of their "
                     f"own reported standard errors; a steep sweep with "
                     f"{steep_report.zero_event_cells} zero-event and "
                     f"{steep_report.all_event_cells} all-event cells fits all "
                     f"{steep_report.cells_fitted} of them and returns "
                     f"{steep_report.exponent:.3f}, while deleting the "
                     f"boundary cells moves it by {trimmed_gap:.3f} — so "
                     f"retention is load-bearing; the unweighted log-log "
                     f"fitter refuses the zero proportion at K="
                     f"{zero_cell.coupling} rather than dropping it; and the "
                     f"reported parameters maximize an independently "
                     f"transcribed likelihood, with a central-difference "
                     f"gradient of {gradient:.2e} and no higher neighbour on a "
                     f"3x3 grid")
                  if not problems else "; ".join(problems[:6]), covers=(99,))


@check("curved, saturated, separated, unidentifiable and uninformative data "
       "return no valid exponent with a named reason", covers=[100])
def check_no_valid_exponent():
    """A refusal is a result, and it has to be the *right* refusal.

    "No valid exponent" is the plan's alternative to choosing a friendlier
    window, so the failure modes are exercised one at a time and each must
    produce a reason from :data:`~.analysis.NO_EXPONENT_REASONS` — not an
    exception, not a silently narrowed sweep, and not a number somebody could
    quote.  ``every cell retained`` is asserted on every one of them.

    The last case is the one an independent review found.  A six-point grid
    spanning ``1.000`` to ``1.010`` with two hundred thousand trials per cell
    and exactly half events has an adequately informed power exponent and a
    *singular* curvature information matrix: the likelihood ratio is zero, its
    p-value is one, and the earlier implementation read that as the curvature
    test passing.  A test that cannot fail is not a test that passed, so the
    curvature extension must now be identifiable before the power model it
    tests can be valid — with a nearby identifiable grid beside it that still
    is.
    """
    problems = []
    seen = set()
    refused = _refuser(problems)

    def outcome(label, design, expected):
        report = sta.fit_exponent(design)
        seen.update(report.reasons)
        if report.cells_fitted != len(design.cells):
            problems.append(f"{label}: fitted {report.cells_fitted} of "
                            f"{len(design.cells)} cells")
        if report.verdict != "no_valid_exponent":
            problems.append(f"{label}: returned {report.verdict} with "
                            f"exponent {report.exponent:.3f}")
        elif expected not in report.reasons:
            problems.append(f"{label}: refused for {list(report.reasons)}, "
                            f"expected {expected!r}")
        return report

    def declared(probabilities, trials=400, seed=950, namespace="declared"):
        rng = np.random.default_rng(seed)
        ids = _identities(namespace, trials)
        cells = []
        for coupling, probability in zip(_SWEEP_COUPLINGS, probabilities):
            if probability <= 0.0:
                flags = (False,) * trials
            elif probability >= 1.0:
                flags = (True,) * trials
            else:
                flags = tuple(bool(v) for v in rng.random(trials)
                              < probability)
            cells.append(sta.CouplingCell(coupling, ids, flags))
        return sta.ScalingDesign(tuple(cells), "master_trial")

    control = sta.fit_exponent(_counted_design(_SWEEP_COUPLINGS, 2.0, 4000))
    if not control.is_valid:
        problems.append(f"the ordinary power-law control was refused for "
                        f"{list(control.reasons)}, so these refusals carry no "
                        f"information")

    outcome("every cell zero-event", declared([0.0] * 6), "saturated")
    outcome("every cell all-event", declared([1.0] * 6), "saturated")
    outcome("perfectly separated cells", declared([0.0, 0.0, 0.0, 1.0, 1.0,
                                                   1.0]), "separation")
    outcome("a non-power (logistic) response",
            declared([1.0 / (1.0 + math.exp(-8.0 * (K - 0.6)))
                      for K in _SWEEP_COUPLINGS], trials=4000),
            "lack_of_fit")
    mean_log = float(np.mean(np.log(_SWEEP_COUPLINGS)))
    curved = declared([1.0 - math.exp(-math.exp(
        2.0 * math.log(K) + 1.2 * (math.log(K) - mean_log) ** 2))
        for K in _SWEEP_COUPLINGS], trials=8000, seed=952)
    curved_report = sta.fit_exponent(curved)
    seen.update(curved_report.reasons)
    if curved_report.verdict != "no_valid_exponent":
        problems.append(f"a deliberately curved response returned "
                        f"{curved_report.verdict}")
    elif not {"curvature", "lack_of_fit"} & set(curved_report.reasons):
        problems.append(f"the curved response was refused for "
                        f"{list(curved_report.reasons)} rather than for "
                        f"curvature or lack of fit")
    if curved_report.cells_fitted != len(curved.cells):
        problems.append("the curved response did not fit every cell")

    outcome("four trials per cell", declared(
        [1.0 - math.exp(-K ** 2) for K in _SWEEP_COUPLINGS], trials=4,
        seed=953), "uninformative")

    nearly = sta.ScalingDesign(
        tuple(sta.CouplingCell(1.0 + index * 1e-15,
                               _identities("nearly", 400),
                               tuple(bool(v) for v in
                                     np.random.default_rng(954 + index)
                                     .random(400) < 0.5))
              for index in range(6)), "master_trial")
    nearly_report = sta.fit_exponent(nearly)
    seen.update(nearly_report.reasons)
    if nearly_report.verdict != "no_valid_exponent":
        problems.append("a sweep whose couplings are identical to fifteen "
                        "digits returned a valid exponent")

    # The independent review's exact reproduction: a narrow grid whose power
    # exponent is informed and whose curvature extension is not.
    narrow_couplings = tuple(1.0 + 0.002 * index for index in range(6))
    half = 100000
    narrow_ids = _identities("narrow", 2 * half)
    narrow = sta.ScalingDesign(
        tuple(sta.CouplingCell(coupling, narrow_ids,
                               (True,) * half + (False,) * half)
              for coupling in narrow_couplings), "master_trial")
    narrow_report = sta.fit_exponent(narrow)
    seen.update(narrow_report.reasons)
    if narrow_report.verdict != "no_valid_exponent":
        problems.append(
            f"the review's narrow-grid reproduction returned "
            f"{narrow_report.verdict} with curvature stderr "
            f"{narrow_report.curvature_stderr} and curvature p "
            f"{narrow_report.curvature_p}")
    elif "curvature_unidentified" not in narrow_report.reasons:
        problems.append(f"the narrow grid was refused for "
                        f"{list(narrow_report.reasons)} rather than for an "
                        f"unidentifiable curvature extension")
    if not math.isinf(narrow_report.curvature_stderr):
        problems.append("the narrow grid's curvature stderr is finite, so "
                        "this fixture no longer reproduces the defect")

    # The positive control beside it: a grid wide enough to identify the
    # curvature extension must still return a valid exponent.
    identifiable = sta.fit_exponent(_counted_design(_SWEEP_COUPLINGS, 2.0,
                                                    20000))
    if not identifiable.is_valid:
        problems.append(f"an identifiable curvature design was refused for "
                        f"{list(identifiable.reasons)}, so the new gate "
                        f"refuses everything")

    unknown = sorted(seen - set(sta.NO_EXPONENT_REASONS))
    if unknown:
        problems.append(f"reasons outside the closed vocabulary: {unknown}")

    refused("a report claiming a valid exponent with a refusal reason",
            _exponent_report(reasons=("curvature",)))
    refused("a report claiming a refusal with no reason",
            _exponent_report(verdict="no_valid_exponent"))
    refused("a report that fitted fewer cells than it declared",
            _exponent_report(cells_fitted=4))
    refused("a design with a repeated coupling",
            lambda: sta.ScalingDesign(
                tuple(sta.CouplingCell(1.0, _identities("repeat", 400),
                                       (True,) * 400)
                      for _ in range(6)), "master_trial"))
    refused("a design with fewer cells than the curvature test needs",
            lambda: sta.ScalingDesign(
                _synthetic_design(2.0, trials=40).cells[:3], "master_trial"))

    return Result("curved, saturated, separated, unidentifiable and "
                  "uninformative data return no valid exponent with a named "
                  "reason", not problems, float(len(problems)), 0.0,
                  (f"an ordinary power-law sweep of the same size returns a "
                   f"valid exponent, and beside it every-cell-zero, "
                   f"every-cell-all, perfect separation, a logistic response, "
                   f"a response curved in log-coupling, four trials per cell, "
                   f"a coupling grid identical to fifteen digits and the "
                   f"review's narrow 1.000-1.010 grid with 200000 trials per "
                   f"cell each return no valid exponent — reasons observed "
                   f"{sorted(seen)}, all inside the closed vocabulary, and "
                   f"every one of them fitted every declared cell.  The narrow "
                   f"grid is refused for curvature_unidentified with a "
                   f"curvature stderr of {narrow_report.curvature_stderr}, "
                   f"while an identifiable design of the same size still "
                   f"returns {identifiable.exponent:.3f}.  A report claiming a "
                   f"valid exponent with a reason, a refusal with no reason, a "
                   f"report that fitted fewer cells than it declared, a "
                   f"repeated coupling and a three-cell design are refused")
                  if not problems else "; ".join(problems[:6]), covers=(100,))


@check("paired master-trial resampling is authoritative, and the wrong "
       "independent-cell procedure is measurably different", covers=[101])
def check_paired_resampling():
    """Common random numbers, the mistake of ignoring them, and who decides.

    A coupling sweep on one keyed noise hierarchy shares master trials: trial 7
    at ``K = 0.4`` and trial 7 at ``K = 0.8`` are the same Brownian path at two
    couplings.  Those cells are correlated, and a bootstrap that resamples
    inside each cell independently treats them as though they were not.

    That mistake is implemented here, deliberately and under a name that says
    so.  Over eight independent paired sweeps built from one shared latent
    uniform per trial, the wrong procedure must return a **smaller** spread
    every time.

    An independent review then found two further defects on the same path, and
    both are checked here:

    * the marginal expected-information Wald interval — which
      :func:`~.analysis.fit_exponent` reports — *tracks the wrong procedure*
      rather than the paired one, so it cannot be the authority.  The measured
      ordering ``wald ≈ wrong < paired`` is asserted; and
    * ``resample_exponent`` counted any replicate with a finite exponent as
      valid, so a four-trial-per-cell design whose every replicate was refused
      reported ``50 / 50`` valid with a percentile interval beside it.  That
      exact reproduction must now report zero valid replicates, an inadequate
      record, and a calibrated verdict of ``no_valid_exponent`` under
      ``inadequate_resampling``.

    :func:`~.analysis.calibrate_exponent` is what the decision path consumes,
    and its interval is the paired one — asserted here by comparing it against
    the resampling record it carries rather than against the marginal fit.
    """
    problems = []
    refused = _refuser(problems)
    ratios, wald_ratios = [], []
    replicates = 250
    for seed in range(6):
        latent = np.random.default_rng(960 + seed).random(400)
        design = _synthetic_design(2.0, trials=400, latent=latent,
                                   seed=970 + seed,
                                   namespace=f"verify-crn-{seed}")
        marginal = sta.fit_exponent(design)
        paired = sta.resample_exponent(design, replicates, 1 + seed)
        wrong = sta.resample_exponent(design, replicates, 1 + seed,
                                      unit=sta.CONTROL_RESAMPLING_UNIT)
        if not wrong.is_control or not wrong.wrong_because:
            problems.append("the control report is not flagged as a control")
        if paired.is_control or paired.wrong_because:
            problems.append("the paired report is flagged as a control")
        if wrong.is_adequate:
            problems.append("the wrong-procedure control reports itself as an "
                            "adequate uncertainty record")
        if not (paired.exponent_stderr > 0.0 and wrong.exponent_stderr > 0.0):
            problems.append(f"seed {seed}: a bootstrap returned a zero spread")
            continue
        ratios.append(wrong.exponent_stderr / paired.exponent_stderr)
        wald_ratios.append(marginal.exponent_stderr / paired.exponent_stderr)
    if ratios and max(ratios) >= 0.95:
        problems.append(f"the independent-cell control did not understate the "
                        f"spread on every sweep: ratios "
                        f"{[round(r, 3) for r in ratios]}")
    if wald_ratios and max(wald_ratios) >= 0.98:
        problems.append(
            f"the marginal Wald interval did not understate the paired spread "
            f"on every sweep: ratios {[round(r, 3) for r in wald_ratios]}.  "
            f"That ordering is why the Wald interval may be displayed and may "
            f"not decide anything")

    # The review's exact reproduction: every replicate refused.
    tiny = _synthetic_design(2.0, trials=4, seed=975, namespace="verify-tiny")
    tiny_fit = sta.fit_exponent(tiny)
    tiny_resample = sta.resample_exponent(tiny, 50, 2)
    tiny_calibrated = sta.calibrate_exponent(tiny)
    if tiny_fit.is_valid:
        problems.append("the four-trial reproduction fixture is itself valid, "
                        "so it no longer reproduces the defect")
    if tiny_resample.estimable_replicates != 0:
        problems.append(
            f"the four-trial design reports "
            f"{tiny_resample.estimable_replicates} of "
            f"{tiny_resample.replicates} replicates valid; every one of them "
            f"is refused, and counting a finite exponent as a success is the "
            f"defect this closes")
    if tiny_resample.is_adequate:
        problems.append("a record with no valid replicate calls itself "
                        "adequate")
    if not tiny_resample.refusals:
        problems.append("the refusals were not carried by reason")
    if "inadequate_resampling" not in tiny_calibrated.reasons:
        problems.append(f"the calibrated verdict on an all-refused record is "
                        f"{list(tiny_calibrated.reasons)}, without "
                        f"inadequate_resampling")

    # Adequacy has a floor, and it is this module's floor rather than the
    # caller's: the same design resampled below MIN_RESAMPLE_REPLICATES is
    # inadequate however clean its replicates are.
    good = _synthetic_design(2.0, trials=400, seed=976,
                             namespace="verify-adequate")
    small = sta.resample_exponent(good, sta.MIN_RESAMPLE_REPLICATES - 1, 4)
    if small.is_adequate:
        problems.append(f"a record of "
                        f"{sta.MIN_RESAMPLE_REPLICATES - 1} replicates was "
                        f"accepted as adequate")
    large = sta.calibrate_exponent(good)
    if large.resampling.replicates != sta.RESAMPLE_REPLICATES:
        problems.append(f"an authoritative calibration drew "
                        f"{large.resampling.replicates} replicates, not the "
                        f"frozen {sta.RESAMPLE_REPLICATES}")
    if not large.resampling.is_adequate:
        problems.append(f"the frozen authoritative record is inadequate: "
                        f"{large.resampling.refusals}")
    if not large.is_valid:
        problems.append(f"a record at the frozen count was refused for "
                        f"{list(large.reasons)}, so the floor refuses "
                        f"everything")
    # No seed and no replicate count on the authoritative door.
    strays = sorted(set(inspect.signature(sta.calibrate_exponent).parameters)
                    - {"design"})
    if strays:
        problems.append(f"calibrate_exponent takes {strays}, through which an "
                        f"authoritative interval could be rerolled")
    if sta.calibrate_exponent(good).interval != large.interval:
        problems.append("two authoritative calibrations of one design "
                        "disagree")
    if large.interval != large.resampling.interval:
        problems.append("the calibrated interval is not the paired resampling "
                        "interval")
    if large.interval == large.report.exponent_interval:
        problems.append("the calibrated interval is the marginal Wald "
                        "interval, which is the thing it exists to replace")

    first = sta.resample_exponent(good, 40, 5)
    second = sta.resample_exponent(good, 40, 5)
    if (first.exponent_mean, first.exponent_stderr, first.interval) != (
            second.exponent_mean, second.exponent_stderr, second.interval):
        problems.append("two bootstraps with the same seed disagree")

    independent = _synthetic_design(2.0, trials=200, seed=981,
                                    unit="independent_namespace",
                                    namespace="verify-ns")
    namespace_report = sta.resample_exponent(independent, 40, 2)
    if namespace_report.unit != "independent_namespace":
        problems.append("an independent-namespace design did not resample "
                        "within its cells")

    unpaired_cells = tuple(
        sta.CouplingCell(cell.coupling,
                         _identities(f"other-{position}", cell.trials),
                         cell.outcomes)
        for position, cell in enumerate(good.cells))
    refused("a master_trial design whose cells hold different identities",
            lambda: sta.ScalingDesign(unpaired_cells, "master_trial"))
    refused("an independent_namespace design whose cells share identities",
            lambda: sta.ScalingDesign(good.cells, "independent_namespace"))
    refused("resampling shared master trials over a namespace design",
            lambda: sta.resample_exponent(independent, 10, 0,
                                          unit="master_trial"))
    refused("resampling within cells of a paired design under a legitimate "
            "name",
            lambda: sta.resample_exponent(good, 10, 0,
                                          unit="independent_namespace"))
    refused("a calibrated exponent built on the wrong-procedure control",
            lambda: sta.CalibratedExponent(
                "master_trial", large.report,
                sta.resample_exponent(good, 10, 0,
                                      unit=sta.CONTROL_RESAMPLING_UNIT),
                "valid_exponent", (), 2.0, 0.1, (1.8, 2.2), (-0.1, 0.1)))

    return Result("paired master-trial resampling is authoritative, and the "
                  "wrong independent-cell procedure is measurably different",
                  not problems, max(ratios + wald_ratios) if ratios else 1.0,
                  0.95,
                  (f"over {len(ratios)} paired sweeps of {replicates} "
                   f"replicates each, built from one shared latent uniform "
                   f"per trial, both the independent-cell control and the "
                   f"marginal expected-information Wald interval returned a "
                   f"smaller spread than the paired bootstrap every time — "
                   f"control ratios {[round(r, 3) for r in ratios]}, Wald "
                   f"ratios {[round(r, 3) for r in wald_ratios]} — which is "
                   f"why the Wald interval may be displayed and may not "
                   f"decide.  The review's four-trial reproduction now reports "
                   f"{tiny_resample.estimable_replicates}/"
                   f"{tiny_resample.replicates} valid replicates with "
                   f"refusals {tiny_resample.refusals} and calibrates to "
                   f"{list(tiny_calibrated.reasons)}; a record one replicate "
                   f"below the frozen floor of "
                   f"{sta.MIN_RESAMPLE_REPLICATES} is inadequate while one at "
                   f"the floor is valid; the calibrated interval is the paired "
                   f"one and not the Wald one; the same seed gives the same "
                   f"numbers; and unshared identities, shared namespaces, each "
                   f"legitimate unit applied to the other's design, and a "
                   f"calibration built on the control record are all refused")
                  if not problems else "; ".join(problems[:6]), covers=(101,))


@check("the four comparators keep separate names, units and population "
       "status", covers=[102])
def check_comparator_labels():
    """Three of the four are numerically similar and mean different things.

    The eligible-clock count, the bare relaxation-rate sum and the
    spacing-weighted continuum flux rise and fall together over a pulse.  Two
    of them are statements about the finite population that actually ran; the
    third is a midpoint quadrature that answers a different question the moment
    the clock count changes.  Substituting it for the bare sum is the
    conflation the plan forbids, and at a call site the substitution is
    invisible — so it is refused by construction.

    The arithmetic is checked against independently written expressions over
    the manifest's exact production detunings, and the flux is required to be
    the sum times the grid spacing and to *differ* from it.
    """
    fixture = _ticket06_fixture()
    manifest, curves = fixture["manifest"], fixture["curves"]
    problems = []
    refused = _refuser(problems)

    if sorted(cmpr.COMPARATOR_KINDS) != sorted(set(cmpr.COMPARATOR_KINDS)):
        problems.append("two comparators share a name")
    units = [cmpr.COMPARATOR_UNITS[k] for k in cmpr.COMPARATOR_KINDS]
    if len(set(units)) != len(units):
        problems.append("two comparators share a unit string")
    if cmpr.PRIMARY_COMPARATOR != "bare_rate_sum":
        problems.append(f"the primary comparator is "
                        f"{cmpr.PRIMARY_COMPARATOR!r}, not the exact-grid bare "
                        f"relaxation-rate sum")
    if cmpr.COMPARATOR_FINITE_POPULATION["continuum_flux"]:
        problems.append("the continuum flux is declared a finite-population "
                        "quantity")
    if not cmpr.COMPARATOR_FINITE_POPULATION["bare_rate_sum"]:
        problems.append("the bare sum is not declared a finite-population "
                        "quantity")
    primary = [k for k in cmpr.COMPARATOR_KINDS
               if curves.curve(k).is_primary]
    if primary != [cmpr.PRIMARY_COMPARATOR]:
        problems.append(f"{primary} claim to be primary")

    detunings = np.array(manifest.value("detunings"), dtype=float)
    spacing = manifest.value("grid_spacing")
    pulse = mdl.RaisedCosinePulse(manifest.value("peak_coupling"),
                                  manifest.value("pulse_duration"),
                                  manifest.value("pulse_centre"))
    dwell = manifest.value("dwell_time")
    worst = 0.0
    flux_gap = 0.0
    for index, t in enumerate(curves.curve("bare_rate_sum").times):
        K = float(np.atleast_1d(pulse.coupling(np.array([t - dwell])))[0])
        eligible = [d for d in detunings if abs(d) < K]
        count = float(len(eligible))
        total = math.fsum(math.sqrt(K * K - d * d) for d in eligible)
        worst = max(
            worst,
            abs(curves.curve("eligible_count").values[index] - count),
            abs(curves.curve("bare_rate_sum").values[index] - total),
            abs(curves.curve("continuum_flux").values[index]
                - spacing * total))
        flux_gap = max(flux_gap,
                       abs(curves.curve("continuum_flux").values[index]
                           - curves.curve("bare_rate_sum").values[index]))
    if worst > 1e-12:
        problems.append(f"an independently written comparator differs by "
                        f"{worst:.3e}")
    if flux_gap <= 0.0:
        problems.append("the continuum flux and the bare sum are the same "
                        "numbers on this grid, so this run cannot discriminate "
                        "between them")

    unshifted = cmpr.comparator_curves(
        manifest, np.array(curves.curve("bare_rate_sum").times), 0.5,
        dwell_shifted=False)
    if unshifted.curve("bare_rate_sum").values == curves.curve(
            "bare_rate_sum").values:
        problems.append("the declared dwell shift changes nothing, so it is "
                        "not being applied")
    signature = inspect.signature(cmpr.comparator_curves)
    strays = sorted(set(signature.parameters)
                    - {"manifest", "times", "constant_hazard",
                       "dwell_shifted"})
    if strays:
        problems.append(f"comparator_curves takes {strays}, which could carry "
                        f"a fitted time offset")

    axis, values = (0.0, 1.0), (1.0, 2.0)
    refused("continuum flux built as a finite-population prediction",
            lambda: cmpr.ComparatorCurve("continuum_flux", axis, values,
                                         cmpr.COMPARATOR_UNITS[
                                             "continuum_flux"], True))
    refused("the bare sum built with the continuum control's unit",
            lambda: cmpr.ComparatorCurve("bare_rate_sum", axis, values,
                                         cmpr.COMPARATOR_UNITS[
                                             "continuum_flux"], True))
    refused("the bare sum built as a continuum quantity",
            lambda: cmpr.ComparatorCurve("bare_rate_sum", axis, values,
                                         cmpr.COMPARATOR_UNITS[
                                             "bare_rate_sum"], False))
    refused("a comparator named for the prediction it is compared against",
            lambda: cmpr.ComparatorCurve("tongue_rate_flux", axis, values,
                                         cmpr.COMPARATOR_UNITS[
                                             "bare_rate_sum"], True))
    refused("a set holding two bare sums and no continuum control",
            lambda: cmpr.ComparatorSet(
                (curves.curve("eligible_count"), curves.curve("bare_rate_sum"),
                 curves.curve("bare_rate_sum"),
                 curves.curve("constant_hazard"))))
    refused("a set missing the constant-hazard control",
            lambda: cmpr.ComparatorSet(curves.curves[:3]))
    refused("a curve asked for by a name that is not one of the four",
            lambda: curves.curve("flux"))

    return Result("the four comparators keep separate names, units and "
                  "population status", not problems, worst, 1e-12,
                  (f"the four kinds {list(cmpr.COMPARATOR_KINDS)} have "
                   f"distinct names and distinct unit strings; "
                   f"{cmpr.PRIMARY_COMPARATOR!r} is the single declared "
                   f"primary and the only curve that reports itself as one; "
                   f"the continuum flux is the only kind declared "
                   f"non-finite-population; every value agrees with an "
                   f"independently written expression over the manifest's own "
                   f"detunings to {worst:.1e}, with the flux differing from "
                   f"the bare sum by up to {flux_gap:.3f}; the dwell shift is "
                   f"the manifest's and comparator_curves has no parameter "
                   f"through which a fitted offset could arrive; and flux "
                   f"built as a finite-population prediction, a swapped unit, "
                   f"a swapped population flag, an invented kind, a duplicated "
                   f"kind, a missing control and an unknown lookup are all "
                   f"refused")
                  if not problems else "; ".join(problems[:6]), covers=(102,))


@check("refused controls, an inadequate contrast and missing holdout evidence "
       "each block a false quadratic attribution", covers=[103])
def check_causal_controls():
    """The negative controls have to be *able* to win, or they are decoration.

    A quadratic population result supports the width-times-rate mechanism only
    if the two controls do not also look quadratic.  That is a decision rule,
    and a decision rule nobody has watched fire is an assumption.

    Each defeater is fired in turn against a full model that would otherwise
    pass, and each must block on its own.  Three of them are new, and all three
    close a reproduction an independent review supplied:

    * a control reporting ``no_valid_exponent`` now blocks.  The premise that
      an inadequate control has an unbounded interval and therefore blocks
      anyway is false for ``lack_of_fit`` and ``curvature``, which keep a
      finite and often narrow interval — and the review produced
      ``not_blocked`` with *both* controls refused;
    * an inadequate paired contrast blocks, rather than supplying a lower
      endpoint from replicates that were themselves refused; and
    * incomplete holdout evidence blocks.  It used to be a bare boolean, so
      "no holdout was computed" and "the control was worse" were the same
      argument.

    Beside them is the control that makes the block informative: the same full
    model with valid controls at exponent one, an adequate contrast that clears
    the minimum, and a holdout in which the control is worse, which must come
    back ``not_blocked``.
    """
    problems = []
    refused = _refuser(problems)
    fixture = _ticket06_fixture()
    holdout = fixture["holdout"]

    latent = np.random.default_rng(990).random(400)
    full = _synthetic_design(2.0, trials=400, latent=latent, seed=991,
                             namespace="verify-causal")
    linear = _synthetic_design(1.0, trials=400, latent=latent, seed=992,
                               namespace="verify-causal")
    # A *different* dataset, so that a control's digest can never coincide
    # with the full model's: a contrast between one design and itself is
    # identically zero and ``ContrastReport`` refuses it.
    quadratic = _synthetic_design(
        2.0, trials=400, latent=np.random.default_rng(995).random(400),
        seed=993, namespace="verify-causal-quad")
    # A second linear design, so that "full" and "width-only" are never the
    # same observations: a contrast between one design and itself is
    # identically zero and ``ContrastReport`` refuses it.
    width_linear = _synthetic_design(1.0, trials=400, latent=latent, seed=994,
                                     namespace="verify-causal-width")

    full_cal = sta.calibrate_exponent(full)
    linear_cal = sta.calibrate_exponent(linear)
    quadratic_cal = sta.calibrate_exponent(quadratic)
    width_cal = sta.calibrate_exponent(width_linear)
    # A control refused for lack of fit that nevertheless keeps a *finite,
    # narrow* interval excluding two: the review's exact counterexample, in
    # which the interval test cannot fire and only the verdict can.  It is a
    # real calibration now — a logistic-in-coupling response, which the
    # cluster-calibrated test rejects — because ``CalibratedExponent`` is
    # factory-only and a hand-built one is no longer constructible.
    logistic = sta.ScalingDesign(
        tuple(sta.CouplingCell(
            coupling, _identities("verify-causal-logistic", 4000),
            tuple(index < int(round(4000 / (1.0 + math.exp(
                -8.0 * (coupling - 0.6))))) for index in range(4000)))
              for coupling in _SWEEP_COUPLINGS), "master_trial")
    refused_cal = sta.calibrate_exponent(logistic)

    if not full_cal.is_valid:
        problems.append(f"the full-model fixture is itself refused: "
                        f"{list(full_cal.reasons)}")
    if not quadratic_cal.interval_contains(cmpr.QUADRATIC_EXPONENT):
        problems.append("the quadratic control fixture's interval excludes "
                        "two, so it cannot fire the defeat rule")
    for label, control in (("linear", linear_cal), ("width", width_cal)):
        if control.interval_contains(cmpr.QUADRATIC_EXPONENT):
            problems.append(f"the {label} control fixture's interval contains "
                            f"two, so it cannot serve as the passing control")
        if not control.is_valid:
            problems.append(f"the {label} control fixture is refused for "
                            f"{list(control.reasons)}")
    if refused_cal.is_valid:
        problems.append("the refused-control fixture is valid, so it cannot "
                        "reproduce the review's counterexample")
    if refused_cal.interval_contains(cmpr.QUADRATIC_EXPONENT):
        problems.append(
            f"the refused control's interval {refused_cal.interval} contains "
            f"two, so the verdict-based blocker below cannot be shown to be "
            f"doing the work the interval test was not")

    full_prints, width_prints = fixture["full_prints"], fixture["width_prints"]
    prints = (full_prints[-1], full_prints[-2], width_prints[-2])
    absent = cmpr.missing_holdout("no reference run was declared")
    matching = _hand_holdout(cmpr.ComparisonScore(0.4, 0.4, 0.4),
                             cmpr.ComparisonScore(0.1, 0.1, 0.1), prints)
    worse = _hand_holdout(cmpr.ComparisonScore(0.1, 0.1, 0.1),
                          cmpr.ComparisonScore(0.4, 0.4, 0.4), prints)

    def decide(full_c, central_c, width_c, contrast_kind, evidence,
               blockers=()):
        full_ev = _hand_control("full", full_c, fingerprints=full_prints,
                                blockers=blockers)
        width_ev = _hand_control("width_only", width_c,
                                 fingerprints=width_prints)
        contrasts = {
            "strong": _hand_contrast(full_c, width_c, interval=(0.8, 1.2),
                                     full_prints=full_prints,
                                     control_prints=width_prints),
            "weak": _hand_contrast(full_c, width_c, interval=(-0.05, 0.09),
                                   full_prints=full_prints,
                                   control_prints=width_prints),
            "thin": _hand_contrast(full_c, width_c, estimable=3,
                                   full_prints=full_prints,
                                   control_prints=width_prints),
        }
        return cmpr.causal_decision(
            full_ev, _hand_control("central", central_c), width_ev,
            contrasts[contrast_kind], 0.25, evidence)

    strong = _hand_contrast(full_cal, width_cal,
                            full_prints=full_prints,
                            control_prints=width_prints)

    cases = {
        "central control looks quadratic":
            (decide(full_cal, quadratic_cal, width_cal, "strong", worse),
             "central_control_compatible_with_quadratic"),
        "width-only control looks quadratic":
            (decide(full_cal, linear_cal, quadratic_cal, "strong", worse),
             "width_control_compatible_with_quadratic"),
        "the central control has no valid exponent":
            (decide(full_cal, refused_cal, width_cal, "strong", worse),
             "central_control_no_valid_exponent"),
        "the width-only control has no valid exponent":
            (decide(full_cal, linear_cal, refused_cal, "strong", worse),
             "width_control_no_valid_exponent"),
        "the paired contrast is underpowered":
            (decide(full_cal, linear_cal, width_cal, "weak", worse),
             "contrast_underpowered"),
        "the paired contrast is inadequate":
            (decide(full_cal, linear_cal, width_cal, "thin", worse),
             "contrast_inadequate"),
        "the holdout evidence is missing":
            (decide(full_cal, linear_cal, width_cal, "strong", absent),
             "holdout_evidence_missing"),
        "the control matches out of sample":
            (decide(full_cal, linear_cal, width_cal, "strong", matching),
             "control_matches_out_of_sample"),
        "the full model has no valid exponent":
            (decide(refused_cal, linear_cal, width_cal, "strong", worse),
             "full_model_no_valid_exponent"),
        "a control's own manifests forbid a physical reading":
            (decide(full_cal, linear_cal, width_cal, "strong", worse,
                    blockers=("numerical_gate is 'diagnostic_only'",)),
             "numerical_status_not_cleared"),
    }
    for label, (decision, expected) in cases.items():
        if decision.attribution != "blocked":
            problems.append(f"{label}: attribution {decision.attribution!r}")
        elif expected not in decision.reasons:
            problems.append(f"{label}: blocked for {list(decision.reasons)}, "
                            f"expected {expected!r}")

    passing = decide(full_cal, linear_cal, width_cal, "strong", worse)
    if passing.attribution != "not_blocked":
        problems.append(f"the passing control was blocked for "
                        f"{list(passing.reasons)}, so every case above blocks "
                        f"for free")
    if "supported" in cmpr.ATTRIBUTION_VERDICTS:
        problems.append("a verdict spelled 'supported' exists, which is "
                        "exactly the reading not_blocked must not carry")

    split, winners = fixture["split"], fixture["winners"]
    identical = cmpr.discrepancy_score(split, split, winners, winners)
    if identical.total != 0.0:
        problems.append(f"a run scored against itself gives "
                        f"{identical.total}, expected zero")
    if not cmpr.control_defeats(identical, identical):
        problems.append("a tied control does not defeat, so an exact tie would "
                        "certify the mechanism")
    if cmpr.control_defeats(cmpr.ComparisonScore(0.1, 0.1, 0.1),
                            cmpr.ComparisonScore(0.4, 0.4, 0.4)):
        problems.append("a worse control defeats a better full model")

    left_heavy = obsv.WinnerMismatch((0, 1, 2), (-1.0, 0.0, 1.0), (3, 1, 0), 4,
                                     ((1, 4),))
    right_heavy = obsv.WinnerMismatch((0, 1, 2), (-1.0, 0.0, 1.0), (0, 1, 3),
                                      4, ((1, 4),))
    shifted_score = cmpr.discrepancy_score(split, split, left_heavy,
                                           right_heavy)
    expected_tv = 0.5 * (abs(0.75 - 0.0) + abs(0.25 - 0.25)
                         + abs(0.0 - 0.75))
    if abs(shifted_score.winner - expected_tv) > 1e-12:
        problems.append(f"the winner discrepancy between a left-heavy and a "
                        f"right-heavy distribution is {shifted_score.winner} "
                        f"and the total-variation distance is {expected_tv}")

    def decide_raw(full_ev, central_ev, width_ev, contrast, minimum,
                   evidence):
        return cmpr.causal_decision(full_ev, central_ev, width_ev, contrast,
                                    minimum, evidence)

    full_ev = _hand_control("full", full_cal, fingerprints=full_prints)
    width_ev = _hand_control("width_only", width_cal,
                             fingerprints=width_prints)
    central_ev = _hand_control("central", linear_cal)
    joined = _hand_contrast(full_cal, width_cal,
                            full_prints=full_prints,
                            control_prints=width_prints)

    refused("a decision with a non-positive minimum mechanistic difference",
            lambda: decide_raw(full_ev, central_ev, width_ev, joined, 0.0,
                               worse))
    refused("a decision handed a bare boolean where the holdout belongs",
            lambda: decide_raw(full_ev, central_ev, width_ev, joined, 0.25,
                               False))
    refused("an unblocked decision constructed directly",
            lambda: cmpr.CausalDecision("not_blocked", (), 1.0, 0.25, "a",
                                        "b", "c", "computed"))
    refused("a blocked decision naming none",
            lambda: cmpr.CausalDecision("blocked", (), 1.0, 0.25, "a", "b",
                                        "c", "computed",
                                        seal=_ANALYSIS_SEAL))
    refused("a decision whose controls come from different hierarchies",
            lambda: decide_raw(
                full_ev, central_ev,
                _hand_control("width_only", width_cal, identity="elsewhere",
                              fingerprints=width_prints),
                joined, 0.25, worse))
    refused("a decision whose control was swept over another grid",
            lambda: decide_raw(
                full_ev,
                _hand_control("central", linear_cal,
                              couplings=(0.25, 0.35, 0.5, 0.8)),
                width_ev, joined, 0.25, worse))
    refused("a decision whose contrast is about other observations",
            lambda: decide_raw(full_ev, central_ev, width_ev,
                               _hand_contrast(quadratic_cal, refused_cal,
                                              full_prints=full_prints,
                                              control_prints=width_prints),
                               0.25, worse))
    refused("a decision whose holdout names runs the controls do not hold",
            lambda: decide_raw(
                full_ev, central_ev, width_ev, joined, 0.25,
                _hand_holdout(cmpr.ComparisonScore(0.1, 0.1, 0.1),
                              cmpr.ComparisonScore(0.4, 0.4, 0.4),
                              (width_prints[0], width_prints[0],
                               full_prints[0]))))
    refused("a paired contrast over two sweeps of the same model",
            lambda: cmpr.paired_exponent_contrast(fixture["sweeps"]["full"], fixture["sweeps"]["full"]))
    refused("a paired contrast between two different experiments",
            lambda: cmpr.paired_exponent_contrast(fixture["sweeps"]["central"], fixture["sweeps"]["width"]))

    return Result("refused controls, an inadequate contrast and missing "
                  "holdout evidence each block a false quadratic attribution",
                  not problems, float(len(problems)), 0.0,
                  (f"a full model calibrated at {full_cal.exponent:.3f} is "
                   f"blocked in turn by all {len(cases)} named defeaters — a "
                   f"central control whose paired interval contains two, a "
                   f"width-only control that does, EITHER control reporting no "
                   f"valid exponent while keeping the narrow interval "
                   f"{tuple(round(v, 3) for v in refused_cal.interval)}, an "
                   f"underpowered contrast, an inadequate one, missing holdout "
                   f"evidence, a control that matches out of sample, and the "
                   f"full model's own refusal.  With valid controls at "
                   f"{linear_cal.exponent:.3f}, an adequate paired contrast "
                   f"whose lower endpoint is {strong.lower:.3f} against a "
                   f"frozen minimum of 0.25, and a holdout in which the "
                   f"control is worse, the same rule returns not_blocked.  The "
                   f"out-of-sample score is zero against itself, a tie "
                   f"defeats, no verdict is spelled 'supported', and a bare "
                   f"boolean where the holdout belongs, mismatched "
                   f"hierarchies and mismatched coupling grids are refused")
                  if not problems else "; ".join(problems[:6]), covers=(103,))


#: Names that would give the analysis layer a way to write.  Scanned for at
#: every binding and call position, in all three modules.
_ANALYSIS_WRITE_NAMES = frozenset({
    "open", "write", "write_text", "write_bytes", "writelines", "mkdir",
    "makedirs", "remove", "unlink", "rmtree", "rename", "replace", "truncate",
    "chmod", "O_WRONLY", "O_CREAT", "O_TRUNC", "O_APPEND", "os", "shutil",
    "tempfile", "pathlib", "Path", "subprocess", "importlib", "eval", "exec",
})


@check("the analysis layer opens only a closed hash-matching run, holds no "
       "write path, and leaves the bytes unchanged", covers=[104])
def check_analysis_read_only():
    """Read-only stated, read-only scanned, and read-only measured.

    Three kinds of evidence, because each is weak alone:

    1. **Structural.**  The three modules' syntax trees are scanned for any
       name that could write.  Nothing in this layer names one; ``compare.py``
       reaches the filesystem only through
       :func:`~.raw_runner.open_raw_run`, which reads.

    2. **Behavioural.**  A run is written, opened for comparison, and a full
       analysis is performed over it.  The five files' bytes are hashed
       directly before and after, and every digest must be identical.

    3. **Refusals.**  A run with its close marker removed is *open*, and an
       open run is refused rather than read.  A run with one byte of its trial
       ledger changed is refused after every hash is recomputed.  A
       ``ReadOnlyRun`` built with a fingerprint from a different read is
       refused.
    """
    problems = []
    refused = _refuser(problems)

    banned_found = []
    for name in ("observables.py", "analysis.py", "compare.py"):
        tree = ast.parse((PACKAGE_DIR / name).read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            found = None
            if isinstance(node, ast.Name):
                found = node.id
            elif isinstance(node, ast.Attribute):
                found = node.attr
            elif isinstance(node, ast.Import):
                found = node.names[0].name.split(".")[0]
            elif isinstance(node, ast.ImportFrom) and not node.level:
                found = (node.module or "").split(".")[0]
            if found in _ANALYSIS_WRITE_NAMES:
                banned_found.append(f"{name} names {found!r}")
    if banned_found:
        problems.append(f"the analysis layer can write: {banned_found[:4]}")

    config = rawcfg.raw_event_config(dict(_RACE_RUN_INPUTS))
    with _scoped_run("readonly") as name:
        rawrun.write_raw_run(config, name, "full", 4, 16)
        directory = rawrun.raw_results_directory(name)

        def digests():
            return {role: rawled.digest_bytes(
                (directory / filename).read_bytes())
                for role, filename in rawrun.RUN_FILENAMES.items()}

        before = digests()
        run = cmpr.open_for_comparison(name)
        manifest = run.manifest
        opened = manifest.value("window_open")
        closed = manifest.value("window_close")
        edges = obsv.uniform_edges(opened, closed, 6)
        table = obsv.risk_table(run.ledger, edges)
        counts = obsv.commitment_counts(run.ledger)
        winners = obsv.winner_mismatch(run.ledger)
        frozen = cmpr.frozen_edges(manifest, 3)
        split = cmpr.rising_falling_split(manifest,
                                          obsv.risk_table(run.ledger, frozen))
        curves = cmpr.comparator_curves(manifest, np.array(edges[1:]), 0.5)
        cmpr.discrepancy_score(split, split, winners, winners)
        calibrated = sta.calibrate_exponent(
            _synthetic_design(2.0, trials=200, seed=1001))
        cmpr.synthetic_machinery_verdict(calibrated, "read-only probe")
        cmpr.scaling_verdict(_ticket06_fixture()["sweep"])
        table.rows()
        table.survival()
        table.cumulative_hazard()
        obsv.endpoint_cumulative_hazard(counts)
        curves.curve(cmpr.PRIMARY_COMPARATOR)
        after = digests()
        if before != after:
            changed = sorted(k for k in before if before[k] != after[k])
            problems.append(f"a full comparison changed the bytes of "
                            f"{changed}")
        try:
            reverified = run.reverify()
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"reverify raised {type(exc).__name__}: {exc}")
            reverified = None
        if reverified is not None and reverified != run.fingerprint:
            problems.append("reverify returned a different fingerprint")
        if run.fingerprint.manifest_digest != before["manifest"]:
            problems.append("the fingerprint's manifest digest is not the "
                            "digest of the manifest on disk")
        for role in ("ledger", "clocks", "shadow"):
            if dict(run.fingerprint.table_digests)[role] != before[role]:
                problems.append(f"the fingerprint's {role} digest is not the "
                                f"digest of the file on disk")

    with _scoped_run("openrun") as name:
        rawrun.write_raw_run(config, name, "full", 4, 16)
        directory = rawrun.raw_results_directory(name)
        marker = directory / rawrun.RUN_FILENAMES["marker"]
        keep = marker.read_bytes()
        marker.unlink()
        refused("a run whose close marker is absent",
                lambda: cmpr.open_for_comparison(name))
        marker.write_bytes(keep)
        if cmpr.open_for_comparison(name).fingerprint != _ticket06_digest(
                directory):
            problems.append("restoring the marker did not restore the run, so "
                            "the refusal above proves nothing")
        table_path = directory / rawrun.RUN_FILENAMES["ledger"]
        original = table_path.read_bytes()
        edited = bytearray(original)
        position = original.rindex(b"\n", 0, len(original) - 1) + 1
        edited[position] = original[position] ^ 0x01
        table_path.write_bytes(bytes(edited))
        refused("a run whose trial ledger has one byte changed",
                lambda: cmpr.open_for_comparison(name))
        table_path.write_bytes(original)

    refused("a ReadOnlyRun carrying a fingerprint from a different read",
            lambda: cmpr.ReadOnlyRun(
                "elsewhere", _ticket06_fixture()["ledger"],
                cmpr.LedgerFingerprint("a" * 64,
                                       tuple((n, "b" * 64)
                                             for n in rawled.TABLE_NAMES))))
    refused("a fingerprint naming the tables out of order",
            lambda: cmpr.LedgerFingerprint(
                "a" * 64, tuple((n, "b" * 64)
                                for n in reversed(rawled.TABLE_NAMES))))

    return Result("the analysis layer opens only a closed hash-matching run, "
                  "holds no write path, and leaves the bytes unchanged",
                  not problems, float(len(problems)), 0.0,
                  (f"none of observables.py, analysis.py and compare.py names "
                   f"any of the {len(_ANALYSIS_WRITE_NAMES)} write-capable "
                   f"names at any binding or call position; a full comparison "
                   f"— counts, risk table, survival, cumulative hazard, winner "
                   f"mismatch, all four comparators, the frozen split, a "
                   f"discrepancy score, a calibrated fit, a synthetic verdict "
                   f"and a manifest-bound scaling verdict — leaves all five "
                   f"files hashing to exactly what they hashed before, checked "
                   f"on the bytes rather than through the object; reverify "
                   f"agrees; and an open run, a run with one flipped byte, a "
                   f"fingerprint from a different read and a misordered "
                   f"fingerprint are all refused, with the restored run "
                   f"reading normally beside them")
                  if not problems else "; ".join(problems[:6]), covers=(104,))


def _ticket06_digest(directory):
    """The fingerprint the files in ``directory`` currently spell."""
    return cmpr.LedgerFingerprint(
        rawled.digest_bytes(
            (directory / rawrun.RUN_FILENAMES["manifest"]).read_bytes()),
        tuple((name, rawled.digest_bytes(
            (directory / rawrun.RUN_FILENAMES[name]).read_bytes()))
            for name in rawled.TABLE_NAMES))


_TICKET06_PROBE = '''
import json, sys

PKG = "adler_born_two_channel"
import adler_born_two_channel.raw_runner            # noqa: F401
print(json.dumps(sorted(m for m in sys.modules
                        if m == PKG or m.startswith(PKG + "."))))
'''


@check("no analysis module is reachable from the raw graph, and no physical "
       "permission is constructible under this schema", covers=[105])
def check_analysis_isolation_and_gate():
    """The two boundaries this whole ticket sits between.

    **Isolation.**  A generator that could see the analysis could be influenced
    by it.  The three modules are named in the raw graph's forbidden list, all
    three exist, and a fresh interpreter that imports ``raw_runner`` must load
    none of them, nor the prediction, nor the oracle, nor the audit.

    **The permission.**  Three independent reviews have now attacked this door,
    and each attack is replayed here as a must-refuse:

    1. ``scaling_verdict(good_fit, ("production_cleared",))`` — a caller-supplied
       gate string.  The second argument is a :class:`~.compare.RunSweep`, so
       this is a ``TypeError``.
    2. A ``CalibratedExponent`` whose published verdict and interval agreed with
       neither record it carried, handed to the gate.  The calibration is no
       longer an argument at all: :func:`~.compare.scaling_verdict` recomputes it
       from the re-opened sweep's own ledgers.
    3. ``ScalingVerdict("physical_verdict_permitted", ..., ("not-a-fingerprint",))``
       constructed directly.  The record is sealed, its fingerprints must be
       fingerprints, and — decisively — **manifest schema v3 cannot hold a
       permission at all.**

    That last one is the substantive change.  A review observed that this
    suite's own positive control rewrote ``numerical_gate`` to
    ``production_cleared`` and re-hashed, while the *same hashed manifest* still
    said ``moving_band_status: numerical_no_result`` and
    ``validation_note: ... no scaling claim may be drawn from these tables``.
    A free-text field rewritten is not a production budget.  So the boundary
    fails closed on the schema: a permission needs
    :data:`~.compare.PRODUCTION_STATUS_SCHEMA`, which does not exist, and every
    load-bearing status is read jointly rather than one of four.

    The gate is still shown to *read its input*, which is what stops it being a
    constant function: rewriting the gate on a real closed run removes exactly
    the ``numerical_gate`` blocker from the sweep's status list and leaves the
    schema, moving-band and validation-note blockers standing.
    """
    problems = []
    refused = _refuser(problems)
    fixture = _ticket06_fixture()
    sweeps = fixture["sweeps"]

    for name in ("observables", "analysis", "compare"):
        if name not in _RAW_FORBIDDEN_MODULES:
            problems.append(f"{name} is not in the raw graph's forbidden list")
        if not (PACKAGE_DIR / f"{name}.py").exists():
            problems.append(f"{name}.py does not exist, so forbidding it "
                            f"forbids nothing")

    root = str(PACKAGE_DIR.parent)
    env = dict(os.environ)
    existing = env.get("PYTHONPATH", "")
    env["PYTHONPATH"] = root + (os.pathsep + existing if existing else "")
    loaded = []
    try:
        finished = subprocess.run([sys.executable, "-c", _TICKET06_PROBE],
                                  cwd=root, env=env, capture_output=True,
                                  text=True, timeout=300)
    except (OSError, subprocess.SubprocessError) as error:
        problems.append(f"the raw import probe did not run: "
                        f"{type(error).__name__}: {error}")
    else:
        if finished.returncode != 0:
            problems.append(f"the raw import probe exited "
                            f"{finished.returncode}: "
                            f"{finished.stderr.strip()[-300:]}")
        else:
            loaded = json.loads(finished.stdout.splitlines()[-1])
            leaked = [m for m in loaded
                      if m.split(".")[-1] in ("observables", "analysis",
                                              "compare", "analytic",
                                              "killed_diffusion",
                                              "moving_band_audit")]
            if leaked:
                problems.append(f"importing raw_runner loaded {leaked}")

    compare_tree = ast.parse((PACKAGE_DIR / "compare.py")
                             .read_text(encoding="utf-8"))
    relative = set()
    for node in ast.walk(compare_tree):
        if not (isinstance(node, ast.ImportFrom) and node.level):
            continue
        if node.module:
            relative.add(node.module.split(".")[0])
        else:
            relative.update(alias.name.split(".")[0] for alias in node.names)
    if "analytic" not in relative:
        problems.append("compare.py does not import the prediction, so it is "
                        "not the comparison process this boundary exists for")

    good = sta.calibrate_exponent(
        _synthetic_design(2.0, trials=400, seed=1010,
                          namespace="verify-gate"))
    if not good.is_valid:
        problems.append(f"the synthetic fit used to probe the gate is itself "
                        f"refused: {list(good.reasons)}")

    # The three replayed reproductions.
    refused("scaling_verdict handed a caller-supplied gate string, which is "
            "the first review's exact reproduction",
            lambda: cmpr.scaling_verdict(("production_cleared",)))
    refused("scaling_verdict handed a calibration, which is the second "
            "review's exact reproduction",
            lambda: cmpr.scaling_verdict(good))
    refused("a physical permission constructed directly",
            lambda: cmpr.ScalingVerdict(
                "physical_verdict_permitted", (), ("production_cleared",),
                (fixture["fingerprint"],), "d", (), seal=_ANALYSIS_SEAL))
    refused("a verdict whose fingerprints are strings",
            lambda: cmpr.ScalingVerdict(
                "machinery_only", (), ("x",), ("not-a-fingerprint",), "d", (),
                seal=_ANALYSIS_SEAL))
    refused("a verdict constructed without the factory's token",
            lambda: cmpr.ScalingVerdict(
                "machinery_only", (), ("x",), (fixture["fingerprint"],), "d",
                ()))
    refused("a sweep assembled from bare closed ledgers",
            lambda: cmpr.RunSweep((fixture["ledger"],)))
    refused("a sweep whose runs disagree about a frozen field",
            lambda: cmpr.RunSweep(sweeps["full"].runs[:2]
                                  + sweeps["cleared"].runs[2:]))
    refused("a sweep listing one run twice",
            lambda: cmpr.RunSweep((sweeps["full"].runs[0],
                                   sweeps["full"].runs[0])))
    refused("a sweep alternating the full and width-only models",
            lambda: cmpr.RunSweep((sweeps["full"].runs[0],
                                   sweeps["width"].runs[1],
                                   sweeps["full"].runs[2],
                                   sweeps["width"].runs[3])))

    # The gate reads its input: only the numerical_gate blocker moves.
    blockers = {label: set(sweeps[label].status_blockers)
                for label in ("full", "cleared")}
    moved = blockers["full"] - blockers["cleared"]
    stayed = blockers["full"] & blockers["cleared"]
    if not all("numerical_gate" in reason for reason in moved) or not moved:
        problems.append(f"rewriting the gate moved {sorted(moved)}, which is "
                        f"not exactly the numerical_gate blocker")
    if not stayed:
        problems.append("rewriting the gate removed every blocker, so the "
                        "other statuses are not load-bearing")
    for marker in ("schema v3", "numerical_no_result"):
        if not any(marker in reason for reason in stayed):
            problems.append(f"no surviving blocker mentions {marker!r}")

    verdicts = {}
    for label in ("full", "cleared"):
        sweep = sweeps[label]
        verdict = cmpr.scaling_verdict(sweep)
        verdicts[label] = verdict
        if verdict.verdict != "machinery_only":
            problems.append(f"{label}: a schema-v3 sweep returned "
                            f"{verdict.verdict!r}")
        if verdict.fingerprints != tuple(run.fingerprint
                                         for run in sweep.runs):
            problems.append(f"{label}: the verdict does not name the runs it "
                            f"was made from")
        if verdict.gates != sweep.numerical_gates:
            problems.append(f"{label}: the verdict's gates are not the "
                            f"manifests'")
        if verdict.design_digest != cmpr.design_from_sweep(sweep).digest:
            problems.append(f"{label}: the verdict is not bound to the "
                            f"design it was computed from")
        if verdict.status_blockers != sweep.status_blockers:
            problems.append(f"{label}: the verdict does not carry the sweep's "
                            f"own status blockers")

    # The synthetic door is a different type entirely.
    machinery = cmpr.synthetic_machinery_verdict(good, "gate probe")
    if not isinstance(machinery, cmpr.MachineryReport):
        problems.append("the synthetic door does not return a MachineryReport")
    if isinstance(machinery, cmpr.ScalingVerdict):
        problems.append("the synthetic door returns the same type a closed "
                        "run does, which is what the separate type prevents")
    if machinery.is_physical:
        problems.append("a machinery report claims to be physical")
    if "not a physical coupling exponent" not in machinery.summary:
        problems.append("a machinery report can be quoted without its "
                        "disclaimer")

    gate = fixture["manifest"].value("numerical_gate")
    if gate != rawrun.NUMERICAL_GATE or gate != "diagnostic_only":
        problems.append(f"a run written by this package records "
                        f"numerical_gate={gate!r}")
    if "passed" not in rawrun.STATIONARY_ORACLE_STATUS:
        problems.append(f"the stationary oracle status no longer records a "
                        f"pass: {rawrun.STATIONARY_ORACLE_STATUS!r}")
    if "numerical_no_result" not in rawrun.MOVING_BAND_STATUS:
        problems.append(f"the moving-band status no longer records a "
                        f"numerical_no_result: {rawrun.MOVING_BAND_STATUS!r}")

    for label, claims in (("observables", obsv.OBSERVABLE_NON_CLAIMS),
                          ("analysis", sta.ANALYSIS_NON_CLAIMS),
                          ("compare", cmpr.COMPARISON_NON_CLAIMS)):
        if len(claims) < 4:
            problems.append(f"{label} carries only {len(claims)} non-claims")

    return Result("no analysis module is reachable from the raw graph, and no "
                  "physical permission is constructible under this schema",
                  not problems, float(len(problems)), 0.0,
                  (f"observables, analysis and compare are all named in the "
                   f"raw graph's forbidden list and all three exist; a fresh "
                   f"interpreter importing raw_runner loaded {len(loaded)} "
                   f"package modules and none of the three, nor the "
                   f"prediction, the oracle or the audit; compare.py does "
                   f"import the prediction.  All three reviews' permission "
                   f"reproductions refuse: a caller-supplied gate string, a "
                   f"forged calibration handed to the gate, and a directly "
                   f"constructed permission — the last because manifest "
                   f"schema v3 cannot express a production budget and a "
                   f"permission needs v{cmpr.PRODUCTION_STATUS_SCHEMA}.  A "
                   f"bare-ledger sweep, a sweep disagreeing about a frozen "
                   f"field, a duplicated run and a sweep alternating the two "
                   f"models are refused.  Rewriting one run's numerical_gate "
                   f"removes exactly that blocker and leaves "
                   f"{len(sweeps['cleared'].status_blockers)} standing, "
                   f"including the schema and the moving-band "
                   f"numerical_no_result; every verdict names its runs, gates, "
                   f"design digest and status blockers; and the synthetic door "
                   f"returns a MachineryReport, a different type, that says so "
                   f"in its own summary")
                  if not problems else "; ".join(problems[:6]), covers=(105,))


@check("master-trial identity binds stream provenance, so two datasets "
       "numbered alike cannot be paired", covers=[106])
def check_master_trial_identity():
    """A trial number is not an identity.

    An independent review pointed at :class:`~.analysis.CouplingCell` and
    observed that it identified a master trial by a non-negative integer alone.
    Two physically unrelated datasets both number their rows ``0 .. n-1``, so
    ``paired_exponent_contrast`` accepted them as a paired
    common-random-number experiment and returned a contrast.  There was no
    argument through which the two namespaces could have been supplied, so the
    substitution was not merely unchecked — it was unrepresentable.

    Now an identity is a namespace *and* a number, its
    :attr:`~.analysis.MasterTrial.key` is length-prefixed and therefore
    injective, and the namespace of a real design comes from
    :func:`~.compare.crn_identity` — the digest of the manifest fields that
    decide which Brownian path trial ``i`` is.

    Checked here: the encoding is injective on colliding-looking inputs; the
    provenance token is stable across a sweep and across the paired
    full/width-only pair (which *must* pair, since they share one tree by
    construction) and differs for a different stream namespace; and reordered,
    duplicated, mixed and substituted identities are each refused, with a valid
    control beside every refusal.
    """
    problems = []
    refused = _refuser(problems)
    sweeps = _ticket06_runs()

    # Injectivity on inputs that would collide under a naive join.
    collisions = [(("a/1", 2), ("a", 12)), (("a", 1), ("a", 11)),
                  (("ab", 1), ("a", 21)), (("", 0), ("", 0))]
    keys = {}
    for namespace, trial in [pair for pairs in collisions for pair in pairs]:
        if not namespace:
            continue
        key = sta.MasterTrial(namespace, trial).key
        if key in keys and keys[key] != (namespace, trial):
            problems.append(f"{(namespace, trial)} and {keys[key]} share the "
                            f"key {key!r}")
        keys[key] = (namespace, trial)

    # The provenance token: stable where the path is, different where it is not.
    full_identity = sweeps["full"].crn_identity
    if sweeps["width"].crn_identity != full_identity:
        problems.append("the width-only sweep has a different "
                        "common-random-number identity from the full sweep, "
                        "so the paired contrast they exist for could never be "
                        "formed")
    for run in sweeps["full"].runs:
        if cmpr.crn_identity(run.manifest) != full_identity:
            problems.append("two runs of one sweep have different provenance "
                            "tokens")
    if sweeps["central"].crn_identity == full_identity:
        problems.append("a one-clock population shares its provenance token "
                        "with the eight-clock one, so a different experiment "
                        "would pair with it")
    if "model" in cmpr.CRN_IDENTITY_FIELDS:
        problems.append("the model label is inside the provenance token, so "
                        "the full model and its width-only control could "
                        "never be paired")
    if "peak_coupling" in cmpr.CRN_IDENTITY_FIELDS:
        problems.append("the peak coupling is inside the provenance token, so "
                        "no two cells of one sweep could ever be paired")

    # The review's reproduction: two unrelated datasets, both numbered 0..n-1.
    left = _synthetic_design(2.0, trials=100, seed=1100,
                             namespace="dataset-A")
    right = _synthetic_design(1.0, trials=100, seed=1101,
                              namespace="dataset-B")
    same = _synthetic_design(1.0, trials=100, seed=1102,
                             namespace="dataset-A")
    refused("a design assembled from two datasets numbered alike, which is "
            "the review's exact reproduction",
            lambda: sta.ScalingDesign(
                (left.cells[0],) + right.cells[1:], "master_trial"))
    refused("a paired contrast between two different experiments",
            lambda: cmpr.paired_exponent_contrast(sweeps["central"], sweeps["width"]))
    try:
        cmpr.paired_exponent_contrast(sweeps["full"], sweeps["width"])
    except Exception as exc:                                  # noqa: BLE001
        problems.append(f"the genuinely paired full/width-only contrast was "
                        f"refused: {type(exc).__name__}: {exc}")
    if same.cells[0].namespace != left.cells[0].namespace:
        problems.append("the same-namespace control fixture is not the same "
                        "namespace")

    refused("a design mixing two datasets across its cells",
            lambda: sta.ScalingDesign(
                (left.cells[0], right.cells[1]) + left.cells[2:],
                "master_trial"))
    refused("a cell whose own identities come from two datasets",
            lambda: sta.CouplingCell(
                1.0,
                (sta.MasterTrial("dataset-A", 0),
                 sta.MasterTrial("dataset-B", 1)), (True, False)))
    refused("a cell holding one identity twice",
            lambda: sta.CouplingCell(
                1.0,
                (sta.MasterTrial("dataset-A", 0),
                 sta.MasterTrial("dataset-A", 0)), (True, False)))
    refused("a paired design whose cells reorder the same identities",
            lambda: sta.ScalingDesign(
                (left.cells[0],)
                + tuple(sta.CouplingCell(cell.coupling,
                                         tuple(reversed(cell.trial_ids)),
                                         cell.outcomes)
                        for cell in left.cells[1:]), "master_trial"))
    refused("bare integers where identities belong",
            lambda: sta.CouplingCell(1.0, (0, 1), (True, False)))
    refused("an independent-namespace design whose cells reuse one namespace",
            lambda: sta.ScalingDesign(
                tuple(sta.CouplingCell(
                    cell.coupling,
                    _identities("one-namespace",
                                cell.trials * (position + 1))[
                        position * cell.trials:],
                    cell.outcomes)
                    for position, cell in enumerate(left.cells)),
                "independent_namespace"))

    # A design built from a sweep carries the sweep's own provenance.
    ledger_design = cmpr.design_from_sweep(sweeps["full"])
    if set(ledger_design.namespaces) != {full_identity}:
        problems.append("a design built from a sweep does not carry the "
                        "sweep's provenance token")
    if ledger_design.paired_keys != cmpr.sweep_master_trials(sweeps["full"]):
        problems.append("the design's identities are not the sweep's master "
                        "trials")

    return Result("master-trial identity binds stream provenance, so two "
                  "datasets numbered alike cannot be paired", not problems,
                  float(len(problems)), 0.0,
                  (f"the length-prefixed key is injective on inputs that would "
                   f"collide under a naive join; the provenance token is one "
                   f"digest of {len(cmpr.CRN_IDENTITY_FIELDS)} frozen manifest "
                   f"fields, is identical across every run of a sweep and "
                   f"across the paired full and width-only sweeps — which "
                   f"share one Brownian tree and must pair — and differs for a "
                   f"one-clock population; the model label and the peak "
                   f"coupling are outside it by construction.  The review's "
                   f"reproduction, a paired contrast between two datasets both "
                   f"numbered 0..99, is refused, while the genuinely paired "
                   f"contrast beside it succeeds; and a mixed design, a mixed "
                   f"cell, a repeated identity, a reordered pairing, bare "
                   f"integers and a reused namespace are all refused.  A "
                   f"design built from a sweep carries that sweep's token and "
                   f"its master trials")
                  if not problems else "; ".join(problems[:6]), covers=(106,))


def _binomial_tail(count, trials, probability, upper: bool) -> float:
    """One exact binomial tail, computed without a statistics dependency."""
    total = 0.0
    span = (range(count, trials + 1) if upper else range(0, count + 1))
    for k in span:
        total += (math.comb(trials, k) * probability ** k
                  * (1.0 - probability) ** (trials - k))
    return total


def _binomial_acceptance(trials, probability, alpha):
    """The two-sided exact-binomial acceptance region for a rejection count.

    Returns ``(low, high)`` counts such that a nominal-size test lands inside
    with probability at least ``1 - alpha``.  Used instead of a hand-chosen
    percentage band: an independent review pointed out that the previous
    0.5-13 percent guard would have passed ``19/150 = 12.67%``, whose
    one-sided probability under a five-percent null is about ``1.9e-4`` — a
    band that wide protects nothing.

    ``alpha`` is deliberately small (one in a thousand): this is a guard on a
    Monte Carlo estimate that must not flake, not a hypothesis test, and the
    method it guards sits comfortably inside.
    """
    low = 0
    while _binomial_tail(low, trials, probability, False) < alpha / 2.0:
        low += 1
    high = trials
    while _binomial_tail(high, trials, probability, True) < alpha / 2.0:
        high -= 1
    return low, high


#: Two-sided level of the exact-binomial acceptance region above.
_CALIBRATION_ALPHA = 1e-3

#: The frozen calibration ensembles for the cluster lack-of-fit test.
#:
#: Each entry is ``(label, grid, bend, amplitude, trials, rho, unit, datasets,
#: floor, ceiling)``.  ``rho`` is the equicorrelation of a Gaussian copula over
#: the cells, which is how a common-random-number design is generated here
#: *without* assuming the monotone shared-uniform structure — an independent
#: review made exactly that point: "the master-trial contract imposes no
#: monotonicity assumption".
#:
#: The **method** was frozen before this table was evaluated: nuisance-adjusted
#: cluster score, Rademacher multiplier bootstrap, degenerate-cell refusal,
#: singular-meat refusal, digest-derived seed, 499 replicates.  The bands are
#: wide because these are 60-to-150-dataset estimates whose own binomial
#: standard error is one to two percent.
#:
#: The saturated row is the review's exact fixture, and its band is
#: ``(0.0, 0.0)`` over an *adequate* count that must be zero: a design with no
#: within-cell variation has no calibration, and the honest answer is
#: ``uncalibrated_fit`` rather than a p-value.
_LACK_OF_FIT_ENSEMBLES = (
    ("null interior, independent cells", "interior", 0.0, 0.0, 400, 0.0,
     "independent_namespace", 300, None),
    ("null interior, copula rho=0.0", "interior", 0.0, 0.0, 400, 0.0,
     "master_trial", 300, None),
    ("null interior, copula rho=0.4", "interior", 0.0, 0.0, 400, 0.4,
     "master_trial", 300, None),
    ("null interior, copula rho=0.8", "interior", 0.0, 0.0, 400, 0.8,
     "master_trial", 300, None),
    ("curved bend 0.5, copula rho=0.8", "interior", 0.5, 0.0, 400, 0.8,
     "master_trial", 100, 0.60),
    ("curved bend 1.2, copula rho=0.8", "interior", 1.2, -0.8, 300, 0.8,
     "master_trial", 60, 0.90),
)

#: The review's exact saturated null: ``log H = 0.7 + 1.6 log K`` over
#: ``K = (0.4, 0.7, 1.2, 2.0, 3.5, 6.0)`` at 500 trials with copula
#: correlation 0.8.  Three cells saturate, and the old test rejected 43 of 120.
_SATURATED_GRID = (0.4, 0.7, 1.2, 2.0, 3.5, 6.0)
_SATURATED_DATASETS = 120

_INTERIOR_GRID = _SWEEP_COUPLINGS


def _lack_of_fit_probabilities(grid, bend, amplitude):
    """The declared marginal commitment probabilities of one ensemble."""
    if grid == "saturated":
        return [1.0 - math.exp(-math.exp(0.7 + 1.6 * math.log(coupling)))
                for coupling in _SATURATED_GRID]
    mean_log = float(np.mean(np.log(_INTERIOR_GRID)))
    return [1.0 - math.exp(-math.exp(amplitude + 2.0 * math.log(coupling)
                                     + bend * (math.log(coupling)
                                               - mean_log) ** 2))
            for coupling in _INTERIOR_GRID]


def _copula_design(seed, grid, probabilities, trials, rho, unit):
    """A design whose cells share a Gaussian copula of correlation ``rho``.

    A *general* common-random-number structure, not the monotone shared-uniform
    one: every marginal is exactly the declared probability, and the
    within-master dependence is whatever ``rho`` says.  ``rho = 0`` with
    ``master_trial`` is the independence special case *under the paired unit*,
    which is worth having because the test must be calibrated there too.
    """
    couplings = (_SATURATED_GRID if grid == "saturated" else _INTERIOR_GRID)
    rng = np.random.default_rng(seed)
    if unit == "master_trial":
        common = rng.standard_normal(trials)[:, None]
        idiosyncratic = rng.standard_normal((trials, len(couplings)))
        latent = (math.sqrt(rho) * common
                  + math.sqrt(1.0 - rho) * idiosyncratic)
        uniform = 0.5 * (1.0 + special_erf(latent / math.sqrt(2.0)))
        identities = _identities(f"lof-{seed}-{rho}", trials)
        cells = tuple(
            sta.CouplingCell(coupling, identities,
                             tuple(bool(value)
                                   for value in uniform[:, index]
                                   < probabilities[index]))
            for index, coupling in enumerate(couplings))
    else:
        cells = tuple(
            sta.CouplingCell(coupling,
                             _identities(f"lof-{seed}-ns{index}", trials),
                             tuple(bool(value)
                                   for value in rng.random(trials)
                                   < probabilities[index]))
            for index, coupling in enumerate(couplings))
    return sta.ScalingDesign(cells, unit)


def special_erf(values):
    """``erf`` over an array, without adding a dependency to reach it."""
    return np.vectorize(math.erf)(values)


def _naive_projection(design, report):
    """The **unadjusted** contrast basis, kept only as the mutation.

    The Euclidean complement of ``[1, log K]``, projected into directly — which
    is what the implementation did before an independent review pointed out
    that the two nuisance parameters have been *estimated*, so a cluster's
    contribution is not orthogonal to the design even though the total is.
    """
    x = np.array(design.log_couplings, dtype=float)
    matrix = np.column_stack([np.ones_like(x), x])
    return np.linalg.svd(matrix, full_matrices=True)[0][:, matrix.shape[1]:]


def _reclosed_ledger(ledger, ledger_rows=None, clock_rows=None,
                     shadow_rows=None, manifest=None, declared=None):
    """A caller-built, **internally rehashed** ``ClosedLedger``.

    Everything a public caller can do: copy the parsed rows, edit them,
    re-encode all three tables with :func:`~.raw_ledger.encode_table`, rebuild
    a :class:`~.raw_ledger.CloseMarker` over the new digests, and construct a
    new ledger.  No file is touched and no private name is used.

    This is the shape an independent review used to defeat the earlier local
    guard: such an object agrees with *its own* marker perfectly, so a
    digest-only check accepts it.  ``declared`` overrides the row counts the
    marker states, which is one of the four variants.
    """
    rows = {
        "ledger": (ledger.rows("ledger") if ledger_rows is None
                   else ledger_rows),
        "clocks": ledger.rows("clocks") if clock_rows is None else clock_rows,
        "shadow": (ledger.rows("shadow") if shadow_rows is None
                   else shadow_rows)}
    columns = {"ledger": rawled.LEDGER_COLUMNS, "clocks": rawled.CLOCK_COLUMNS,
               "shadow": rawled.SHADOW_COLUMNS}
    payloads = {name: rawled.encode_table(columns[name], rows[name])
                for name in rawled.TABLE_NAMES}
    frozen = ledger.manifest if manifest is None else manifest
    manifest_bytes = rawled.canonical_manifest_bytes(frozen)
    counts = {name: (declared or {}).get(name, len(rows[name]))
              for name in rawled.TABLE_NAMES}
    marker = rawled.CloseMarker(
        rawled.LEDGER_SCHEMA_VERSION,
        tuple((name, counts[name], rawled.digest_bytes(payloads[name]))
              for name in rawled.TABLE_NAMES),
        rawled.digest_bytes(manifest_bytes))
    return rawled.ClosedLedger(marker, frozen, rows["ledger"], rows["clocks"],
                               rows["shadow"])


@check("the decision path fits the bytes on disk, not the handle it was "
       "given", covers=[109])
def check_authoritative_read():
    """The reopened run has to be the run that is *used*.

    An independent review found the gap between re-hashing and re-reading.
    ``ReadOnlyRun.reverify`` opened the named run, compared fingerprints and
    returned the fingerprint — and the caller then went on computing from the
    in-memory ledger it already held.  Because the fingerprint is derived from
    the close *marker*, a public ``ClosedLedger`` carrying the genuine marker
    beside forged rows and a forged manifest passed the comparison intact:

    ```text
    forged_sweep.reverify()   True
    genuine disk counts       (2/6, 4/6, 5/6, 6/6)
    fitted counts             (6/6, 6/6, 6/6, 6/6)
    verdict gates             production_cleared x 4
    ```

    The disk was never touched.  That replay is reproduced here exactly, and it
    must now fail in two independent ways:

    1. ``ReadOnlyRun`` is sealed, so the forged handle cannot be built through
       any public path at all; and
    2. even built *with* the seal — which this file may do, and does below —
       every authoritative factory calls ``reopen()`` and computes from what it
       returns, so the fitted counts, the gates, the model and the status all
       come from the bytes on disk.

    The second is the one that matters, because it does not depend on the seal:
    the supplied handle is a locator, its fingerprint is compared, and its data
    are discarded.
    """
    problems = []
    refused = _refuser(problems)
    fixture = _ticket06_fixture()
    sweep = fixture["sweeps"]["full"]

    # (1) the public path cannot build one.
    genuine = sweep.runs[0]
    refused("a ReadOnlyRun built through the public constructor",
            lambda: cmpr.ReadOnlyRun(genuine.run_name, genuine.ledger,
                                     genuine.fingerprint))

    # (2) the review's split-brain replay, built *with* the seal so that the
    # reopen contract is what is being tested rather than the seal.
    forged_runs = []
    for run in sweep.runs:
        ledger = run.ledger
        rows = tuple({**row, "category": "committed"}
                     for row in ledger.rows("ledger"))
        fields = dict(ledger.manifest.as_dict())
        for field in cmpr.STATUS_FIELDS:
            fields[field] = cmpr.PRODUCTION_GATE
        forged = rawled.ClosedLedger(ledger.marker,
                                     rawled.RawManifest(fields), rows,
                                     ledger.rows("clocks"),
                                     ledger.rows("shadow"))
        forged_runs.append(cmpr.ReadOnlyRun(run.run_name, forged,
                                            run.fingerprint,
                                            seal=_ANALYSIS_SEAL))
    forged_sweep = cmpr.RunSweep(tuple(forged_runs))

    disk_counts = cmpr._sweep_counts(sweep)
    forged_counts = tuple(
        (sum(1 for row in run.ledger.rows("ledger")
             if row["category"] == "committed"), run.manifest.trials)
        for run in forged_sweep.runs)
    if disk_counts == forged_counts:
        problems.append("the forged sweep holds the same counts as the disk, "
                        "so this replay cannot show which one is used")
    if forged_sweep.numerical_gates == sweep.numerical_gates:
        problems.append("the forged sweep holds the same gates as the disk")
    # The re-encode guard already refuses this snapshot outright, before any
    # reopen: its manifest no longer spells the bytes its own marker declares.
    refused("the sweep's own counts over the forged snapshot",
            lambda: cmpr._sweep_counts(forged_sweep))

    reopened = forged_sweep.reopen()
    if cmpr._sweep_counts(reopened) != disk_counts:
        problems.append(f"reopen() returned counts "
                        f"{list(cmpr._sweep_counts(reopened))}, not the disk's "
                        f"{list(disk_counts)}")
    if reopened.numerical_gates != sweep.numerical_gates:
        problems.append("reopen() returned the forged gates")
    if cmpr.design_from_sweep(reopened).digest != \
            cmpr.design_from_sweep(sweep).digest:
        problems.append("the reopened design is not the disk's design")

    verdict = cmpr.scaling_verdict(forged_sweep)
    if verdict.gates != sweep.numerical_gates:
        problems.append(f"the verdict reports gates {list(verdict.gates)}; the "
                        f"disk says {list(sweep.numerical_gates)}")
    if verdict.design_digest != cmpr.design_from_sweep(sweep).digest:
        problems.append("the verdict's design digest is not the disk's")
    if verdict.status_blockers != sweep.status_blockers:
        problems.append("the verdict carries the forged status blockers")

    evidence = cmpr.control_evidence("full", forged_sweep)
    if evidence.design_digest != cmpr.design_from_sweep(sweep).digest:
        problems.append("control_evidence fitted the forged in-memory rows")
    if evidence.status_blockers != sweep.status_blockers:
        problems.append("control_evidence carries the forged status")

    contrast = cmpr.paired_exponent_contrast(forged_sweep, fixture["sweeps"]["width"])
    if contrast.full_digest != cmpr.design_from_sweep(sweep).digest:
        problems.append("the paired contrast fitted the forged rows")
    if contrast.full_fingerprints != tuple(run.fingerprint
                                           for run in sweep.runs):
        problems.append("the paired contrast names the forged runs")

    forged_holdout = cmpr.holdout_evidence(forged_sweep.runs[-1],
                                           forged_sweep.runs[-2],
                                           fixture["sweeps"]["width"]
                                           .runs[-2], 2)
    if forged_holdout.full_fingerprint != sweep.runs[-2].fingerprint:
        problems.append("the holdout names a run other than the disk's")

    # (3) the review's post-open row mutation.  ``ClosedLedger`` is a frozen
    # dataclass whose rows are ordinary dictionaries, so "frozen" freezes the
    # reference: a caller can edit a verified snapshot without touching a file
    # and without naming a private symbol.  Both the public design route and
    # the observable routes must now either refuse or return the disk result.
    victim = sweep.runs[0]
    disk_digest = cmpr.design_from_sweep(sweep).digest
    disk_committed = obsv.commitment_counts(victim.ledger).committed
    rows = victim.ledger.rows("ledger")
    target = next((row for row in rows if row["category"] != "committed"),
                  None)
    if target is None:
        problems.append("every trial in the mutation fixture already "
                        "committed, so the row edit below changes nothing")
    else:
        original_category = target["category"]
        target["category"] = "committed"
        try:
            if cmpr.design_from_sweep(sweep).digest != disk_digest:
                problems.append(
                    "the public design factory returned a design built from a "
                    "mutated in-memory row rather than the disk's")
            refused("a risk table over a mutated ledger snapshot",
                    lambda: obsv.risk_table(victim.ledger, fixture["edges"]))
            refused("a commitment tally over a mutated ledger snapshot",
                    lambda: obsv.commitment_counts(victim.ledger))
            refused("a winner table over a mutated ledger snapshot",
                    lambda: obsv.winner_mismatch(victim.ledger))
            refused("the sweep's own counts over a mutated snapshot",
                    lambda: cmpr._sweep_counts(sweep))
            # The verdict reopens, so a mutated handle does not reach it at
            # all: this door *returns the disk result* rather than refusing,
            # which is the other half of the contract.
            if cmpr.scaling_verdict(sweep).design_digest != disk_digest:
                problems.append("a verdict over a handle carrying a mutated "
                                "row did not return the disk's design")
            refused("a ledger whose manifest was replaced in memory",
                    lambda: rawled.require_unmutated_ledger(
                        rawled.ClosedLedger(
                            victim.ledger.marker,
                            rawled.RawManifest(
                                {**victim.ledger.manifest.as_dict(),
                                 "numerical_gate": cmpr.PRODUCTION_GATE}),
                            victim.ledger.rows("ledger"),
                            victim.ledger.rows("clocks"),
                            victim.ledger.rows("shadow"))))
        finally:
            target["category"] = original_category
        if obsv.commitment_counts(victim.ledger).committed != disk_committed:
            problems.append("restoring the row did not restore the ledger, so "
                            "the refusals above prove nothing")
        if cmpr.design_from_sweep(sweep).digest != disk_digest:
            problems.append("restoring the row did not restore the design")

    # (4) the four rehashed forgeries.  Each is built entirely from public
    # names, is internally consistent with its own marker, and is refused only
    # because the guard now runs the *authoritative* gate over reconstructed
    # bytes and hands back what that gate parsed.
    genuine_committed = obsv.commitment_counts(victim.ledger).committed
    genuine_winners = obsv.winner_mismatch(victim.ledger).committed_trials
    edited = [dict(row) for row in victim.ledger.rows("ledger")]
    flip = next((row for row in edited if row["category"] != "committed"),
                None)
    forgeries = {}
    if flip is not None:
        flip["category"], flip["censored"] = "committed", True
        forgeries["a category rewritten to committed and rehashed"] = (
            lambda: _reclosed_ledger(victim.ledger,
                                     ledger_rows=tuple(edited)))
    forgeries["a marker declaring one ledger row too many"] = (
        lambda: _reclosed_ledger(victim.ledger,
                                 declared={"ledger":
                                           len(victim.ledger.rows("ledger"))
                                           + 1}))
    shifted = dict(victim.ledger.manifest.as_dict())
    shifted["detunings"] = tuple(value + 0.125
                                 for value in shifted["detunings"])
    forgeries["a manifest grid shifted beside unchanged clock rows"] = (
        lambda: _reclosed_ledger(victim.ledger,
                                 manifest=rawled.RawManifest(shifted)))
    forgeries["ledger rows reversed and rehashed"] = (
        lambda: _reclosed_ledger(
            victim.ledger,
            ledger_rows=tuple(reversed(victim.ledger.rows("ledger")))))

    for label, build in forgeries.items():
        forged = build()
        refused(f"the guard over {label}",
                lambda f=forged: rawled.require_unmutated_ledger(f))
        for door, call in (("a commitment tally", obsv.commitment_counts),
                           ("a winner table", obsv.winner_mismatch)):
            refused(f"{door} over {label}", lambda f=forged, c=call: c(f))
        refused(f"a risk table over {label}",
                lambda f=forged: obsv.risk_table(f, fixture["edges"]))

    # The control beside them: an untouched snapshot, rebuilt the same way,
    # passes and yields the same numbers.  Without this the four refusals
    # above could be a guard that refuses everything.
    untouched = _reclosed_ledger(victim.ledger)
    try:
        reconciled = rawled.require_unmutated_ledger(untouched)
    except Exception as exc:                                  # noqa: BLE001
        problems.append(f"an untouched re-encoded snapshot was refused: "
                        f"{type(exc).__name__}: {exc}")
    else:
        if obsv.commitment_counts(reconciled).committed != genuine_committed:
            problems.append("a re-encoded untouched snapshot gives a "
                            "different commitment count")
        if obsv.winner_mismatch(reconciled).committed_trials != \
                genuine_winners:
            problems.append("a re-encoded untouched snapshot gives a "
                            "different winner count")
    # And the byte-level control the review also ran: re-encoding a parsed
    # table reproduces the writer's bytes exactly.
    directory = rawrun.raw_results_directory(victim.run_name)
    for name, filename in (("ledger", "ledger"), ("clocks", "clocks"),
                           ("shadow", "shadow")):
        written = (directory / rawrun.RUN_FILENAMES[filename]).read_bytes()
        rebuilt = rawled.encode_table(
            {"ledger": rawled.LEDGER_COLUMNS, "clocks": rawled.CLOCK_COLUMNS,
             "shadow": rawled.SHADOW_COLUMNS}[name],
            victim.ledger.rows(name))
        if rebuilt != written:
            problems.append(f"re-encoding the parsed {name} table does not "
                            f"reproduce the bytes the writer wrote")

    # (5) a handle whose disk bytes have changed is refused, not silently
    # reopened onto different data.
    config = rawcfg.raw_event_config(dict(_RACE_RUN_INPUTS))
    with _scoped_run("reopen") as name:
        rawrun.write_raw_run(config, name, "full", 4, 16)
        handle = cmpr.open_for_comparison(name)
        if handle.reopen().fingerprint != handle.fingerprint:
            problems.append("reopening an unchanged run changed its "
                            "fingerprint")
        directory = rawrun.raw_results_directory(name)
        table_path = directory / rawrun.RUN_FILENAMES["ledger"]
        original = table_path.read_bytes()
        edited = bytearray(original)
        position = original.rindex(b"\n", 0, len(original) - 1) + 1
        edited[position] = original[position] ^ 0x01
        table_path.write_bytes(bytes(edited))
        refused("reopening a run whose bytes have changed since it was opened",
                handle.reopen)
        refused("a verdict over a sweep whose bytes have changed",
                lambda: cmpr.scaling_verdict(cmpr.RunSweep((handle,))))
        table_path.write_bytes(original)
        if handle.reopen().fingerprint != handle.fingerprint:
            problems.append("restoring the bytes did not restore the run, so "
                            "the refusals above prove nothing")

    # (6) the review's public subclass.  ``RunSweep`` is public and unsealed,
    # so seven ordinary lines used to turn every authoritative read into an
    # assertion: an ``isinstance`` boundary accepted the subclass and then
    # dispatched to the ``reopen`` the subclass supplied.
    class StaleSweep(cmpr.RunSweep):
        def reopen(self):
            return self

    width = fixture["sweeps"]["width"]
    stale = StaleSweep(sweep.runs)
    stale_control = StaleSweep(width.runs)
    if not isinstance(stale, cmpr.RunSweep):
        problems.append("the subclass replay does not subclass RunSweep, so "
                        "it cannot show what an isinstance boundary admits")
    if stale.reopen() is not stale:
        problems.append("the subclass replay's reopen does not return the "
                        "stale object, so it is not the review's reproduction")

    manifest_path = (rawrun.raw_results_directory(sweep.runs[0].run_name)
                     / rawrun.RUN_FILENAMES["manifest"])
    manifest_bytes = manifest_path.read_bytes()
    manifest_path.write_bytes(manifest_bytes + b" ")
    try:
        # The changed byte has to be visible to the genuine sweep, or the
        # refusals below would prove only that nothing was being read.
        refused("the genuine sweep over a contributing manifest that changed",
                lambda: cmpr.design_from_sweep(sweep))
        for label, call in (
                ("design_from_sweep", lambda: cmpr.design_from_sweep(stale)),
                ("scaling_verdict", lambda: cmpr.scaling_verdict(stale)),
                ("control_evidence",
                 lambda: cmpr.control_evidence("full", stale)),
                ("sweep_master_trials",
                 lambda: cmpr.sweep_master_trials(stale)),
                ("paired_exponent_contrast",
                 lambda: cmpr.paired_exponent_contrast(stale, stale_control))):
            refused(f"{label} over a RunSweep subclass whose reopen returns "
                    f"itself", call)
    finally:
        manifest_path.write_bytes(manifest_bytes)
    if cmpr.design_from_sweep(sweep).digest != disk_digest:
        problems.append("restoring the manifest byte did not restore the "
                        "sweep, so the subclass refusals prove nothing")
    # Exact even with the bytes intact: the type is refused before the data
    # are consumed, not after a read that happened to agree.  Both arguments
    # of the contrast are separately typed.
    refused("a RunSweep subclass over unchanged bytes",
            lambda: cmpr.design_from_sweep(StaleSweep(sweep.runs)))
    refused("a subclass in the contrast's full argument",
            lambda: cmpr.paired_exponent_contrast(StaleSweep(sweep.runs),
                                                  width))
    refused("a subclass in the contrast's control argument",
            lambda: cmpr.paired_exponent_contrast(sweep,
                                                  StaleSweep(width.runs)))

    # The same hole, audited on the other authoritative handles.  A
    # ``LedgerFingerprint`` subclass whose ``__eq__`` is ``True`` is every
    # reopen comparison in the module answered by the object being compared.
    class AlwaysEqual(cmpr.LedgerFingerprint):
        def __eq__(self, other):
            return True

        def __hash__(self):
            return 0

    class OpenLedger(rawled.ClosedLedger):
        pass

    good = sweep.runs[0]
    refused("a ReadOnlyRun carrying a LedgerFingerprint subclass",
            lambda: cmpr.ReadOnlyRun(
                good.run_name, good.ledger,
                AlwaysEqual(good.fingerprint.manifest_digest,
                            good.fingerprint.table_digests),
                seal=_ANALYSIS_SEAL))
    refused("a ReadOnlyRun carrying a ClosedLedger subclass",
            lambda: cmpr.ReadOnlyRun(
                good.run_name,
                OpenLedger(good.ledger.marker, good.ledger.manifest,
                           good.ledger.rows("ledger"),
                           good.ledger.rows("clocks"),
                           good.ledger.rows("shadow")),
                good.fingerprint, seal=_ANALYSIS_SEAL))

    # (7) the review's returned-object interception.  The guard hands back the
    # genuine reconciled ledger and the caller's own manifest alias is changed
    # behind it; every number a design or a count reports must follow the
    # returned object.  This used to move `_sweep_counts` from (n, 6) to
    # (n, 7) — a fresh numerator beside a caller-owned denominator.
    genuine_guard = cmpr.require_unmutated_ledger
    intercepted = []
    disk_identities = cmpr.sweep_master_trials(sweep)
    originals = [(run.ledger, run.ledger.manifest) for run in sweep.runs]
    pristine = {id(ledger): manifest for ledger, manifest in originals}

    def _stale_alias(ledger):
        # The genuine guard sees the genuine manifest and returns the genuine
        # reconciled object; the caller's alias is replaced immediately after,
        # which is the review's interception exactly.  Restoring first makes it
        # idempotent, so several doors can be probed in one bracket.
        object.__setattr__(ledger, "manifest", pristine[id(ledger)])
        fresh = genuine_guard(ledger)            # the real, reconciled object
        fields = dict(pristine[id(ledger)].as_dict())
        fields["trials"] = fields["trials"] + 1
        fields["stream_namespace"] = "a-foreign-hierarchy"
        object.__setattr__(ledger, "manifest", rawled.RawManifest(fields))
        intercepted.append(ledger)
        return fresh

    cmpr.require_unmutated_ledger = _stale_alias
    try:
        if cmpr._sweep_counts(sweep) != disk_counts:
            problems.append(
                f"with the caller's manifest alias changed behind the guard "
                f"the sweep's counts became "
                f"{list(cmpr._sweep_counts(sweep))} rather than the disk's "
                f"{list(disk_counts)}; the denominator is not coming from the "
                f"reconciled ledger")
        mixed = cmpr._design_from_fresh_sweep(sweep)
        if mixed.cells[0].trial_ids != disk_identities:
            problems.append("the design's master-trial identities followed "
                            "the caller's manifest rather than the reconciled "
                            "ledgers, so one namespace's identities can sit "
                            "beside another snapshot's cells")
        if mixed.digest != disk_digest:
            problems.append("the design built while the caller's alias was "
                            "changed is not the disk's design")
    finally:
        cmpr.require_unmutated_ledger = genuine_guard
        for ledger, manifest in originals:
            object.__setattr__(ledger, "manifest", manifest)
    if not intercepted:
        problems.append("the returned-object interception was never reached, "
                        "so it establishes nothing")
    if cmpr._sweep_counts(sweep) != disk_counts or \
            cmpr.design_from_sweep(sweep).digest != disk_digest:
        problems.append("restoring the caller's manifests did not restore the "
                        "sweep, so the interception above proves nothing")

    return Result("the decision path fits the bytes on disk, not the handle "
                  "it was given", not problems, float(len(problems)), 0.0,
                  (f"the review's split-brain replay is built here with the "
                   f"factory token — the public constructor refuses it "
                   f"outright — and every authoritative factory still reads "
                   f"past it: over a forged sweep whose in-memory counts are "
                   f"{list(forged_counts)} and whose in-memory gates are all "
                   f"{cmpr.PRODUCTION_GATE!r}, reopen(), scaling_verdict, "
                   f"control_evidence, paired_exponent_contrast and "
                   f"holdout_evidence all return the disk's counts "
                   f"{list(disk_counts)}, the disk's gates "
                   f"{list(sweep.numerical_gates)}, the disk's design digest, "
                   f"the disk's status blockers and the disk's fingerprints.  "
                   f"A handle whose bytes have since changed is refused by "
                   f"reopen and by the verdict, and reads normally again once "
                   f"they are restored.  The review's post-open row mutation "
                   f"is replayed too: editing one parsed row of a verified "
                   f"ledger leaves the public design factory returning the "
                   f"disk's digest, and makes every observable door, the "
                   f"sweep's own counts and the verdict refuse — because a "
                   f"parsed ledger is re-encoded and checked against the "
                   f"close marker it came with, so a snapshot that has been "
                   f"edited in memory is no longer the run it was opened from. "
                   f"And the four all-public *rehashed* forgeries a further "
                   f"review built — a category rewritten to committed, a "
                   f"marker declaring one row too many, a manifest grid "
                   f"shifted beside unchanged clock rows, and reversed rows — "
                   f"are each refused at the guard and at all three "
                   f"observables, because the guard now puts reconstructed "
                   f"canonical bytes through the whole authoritative gate and "
                   f"returns what *that* parsed.  An untouched snapshot "
                   f"rebuilt the same way passes and gives the same "
                   f"{genuine_committed} commitments, and re-encoding each "
                   f"parsed table reproduces the writer's bytes exactly.  A "
                   f"further review's seven-line public subclass — a RunSweep "
                   f"whose reopen returns itself — is replayed here with one "
                   f"byte appended to a contributing manifest: the genuine "
                   f"sweep refuses, and design_from_sweep, scaling_verdict, "
                   f"control_evidence, sweep_master_trials and both arguments "
                   f"of paired_exponent_contrast refuse the subclass on type "
                   f"before consuming anything, with the bytes changed and "
                   f"with them intact.  A LedgerFingerprint subclass whose "
                   f"__eq__ is always True and a ClosedLedger subclass are "
                   f"refused at ReadOnlyRun for the same reason.  And with the "
                   f"guard intercepted so that it returns the genuine "
                   f"reconciled ledger while the caller's own manifest alias "
                   f"gains a trial and a foreign stream namespace, the sweep's "
                   f"counts stay {list(disk_counts)}, the design keeps the "
                   f"disk's identities and the disk's digest")
                  if not problems else "; ".join(problems[:6]), covers=(109,))


@check("general lack of fit is a nuisance-adjusted cluster score, calibrated "
       "across dependence strengths and honest at the boundary", covers=[108])
def check_cluster_lack_of_fit():
    """The last marginal statistic gets a *correct* paired replacement.

    Round three replaced the marginal deviance with a cluster score test and a
    multiplier bootstrap.  A cold re-review found the construction incomplete
    and produced the counterexample:

    > The total score is orthogonal to the nuisance design at the restricted
    > MLE, but each *cluster contribution* is not. … Re-signing raw ``C' s_t``
    > therefore does not reproduce the score's distribution after fitting the
    > two nuisance parameters.

    and measured the consequence on exact power-law marginals with Gaussian
    copula dependence and three saturated cells: **43 of 120 rejected at the
    nominal 5 percent**, seed ``103002`` at ``p = 0.002`` with counts
    ``(187, 337, 466, 500, 500, 500)``.

    Two things were wrong and both are fixed.

    **The score.**  ``_nuisance_orthogonal_basis`` now forms
    ``B = C - X (X'WX)^-1 X'W C``, so ``X' W B = 0`` exactly — the contrast
    basis is W-orthogonal to the estimated nuisance directions.  That identity
    is checked here to machine precision, and the *unadjusted* basis is checked
    to violate it, so the adjustment is demonstrably doing work.  The numerator
    is unchanged: ``sum_t e_t = C'S`` because ``X'S = 0`` at the maximum.

    **The boundary.**  A cell in which every trial did the same thing
    contributes a constant cluster score: a systematic offset with no sampling
    variation. The sandwich divides that offset by a variance the bootstrap
    invents, and the ratio grows with the cluster count. Such a design is now
    ``adequate=False`` with the reason stated, and ``calibrate_exponent``
    returns ``uncalibrated_fit`` — **every cell still enters the likelihood and
    the report**; a calibration refusal is not cell deletion.

    Calibration is then measured over ensembles frozen *after* the method and
    *before* this table was evaluated, across four dependence strengths
    including a general Gaussian copula rather than the monotone
    shared-uniform special case.
    """
    problems = []
    refused = _refuser(problems)
    measured = {}

    for (label, grid, bend, amplitude, trials, rho, unit, datasets,
         power_floor) in _LACK_OF_FIT_ENSEMBLES:
        probabilities = _lack_of_fit_probabilities(grid, bend, amplitude)
        hits = bends = marginal_hits = usable = 0
        for index in range(datasets):
            design = _copula_design(500000 + index, grid, probabilities,
                                    trials, rho, unit)
            report = sta.fit_exponent(design)
            test = sta.cluster_lack_of_fit(design, report)
            curvature = sta.cluster_curvature(design, report)
            if not (test.adequate and curvature.adequate):
                continue
            usable += 1
            hits += test.rejects
            bends += curvature.rejects
            marginal_hits += (math.isfinite(report.deviance_p)
                              and report.deviance_p < sta.LACK_OF_FIT_ALPHA)
        if not usable:
            problems.append(f"{label}: no dataset produced an adequate test")
            continue
        rate, bend_rate = hits / usable, bends / usable
        measured[label] = (rate, bend_rate, marginal_hits / usable, usable,
                           datasets)
        if power_floor is None:
            # A null ensemble: the rejection count must land inside the exact
            # two-sided binomial acceptance region for a nominal-size test.
            low, high = _binomial_acceptance(usable, sta.LACK_OF_FIT_ALPHA,
                                             _CALIBRATION_ALPHA)
            for name, count in (("lack of fit", hits), ("curvature", bends)):
                if not low <= count <= high:
                    problems.append(
                        f"{label}: the {name} test rejected {count} of "
                        f"{usable}, outside the exact binomial acceptance "
                        f"region [{low}, {high}] at a nominal "
                        f"{sta.LACK_OF_FIT_ALPHA:.0%} and a guard level of "
                        f"{_CALIBRATION_ALPHA:g}")
        else:
            for name, value in (("lack of fit", rate), ("curvature",
                                                        bend_rate)):
                if value < power_floor:
                    problems.append(f"{label}: the {name} test rejected "
                                    f"{value:.1%}, below the frozen power "
                                    f"floor {power_floor:.0%}")

    # The guard is a real guard: an independent review observed that the
    # previous 0.5-to-13-percent band would have accepted 19/150, whose
    # one-sided probability under a five-percent null is about 1.9e-4.
    mutant_low, mutant_high = _binomial_acceptance(150, sta.LACK_OF_FIT_ALPHA,
                                                   _CALIBRATION_ALPHA)
    if mutant_low <= 19 <= mutant_high:
        problems.append(f"the acceptance region for 150 datasets is "
                        f"[{mutant_low}, {mutant_high}], which still admits "
                        f"the review's 19/150 mutant")
    if not mutant_low <= 8 <= mutant_high:
        problems.append(f"the acceptance region [{mutant_low}, "
                        f"{mutant_high}] excludes 8/150, which is an ordinary "
                        f"nominal outcome and would make the guard flake")

    # The review's exact saturated fixture: every one of them must decline to
    # calibrate, and none may reject.
    saturated_probabilities = _lack_of_fit_probabilities("saturated", 0.0, 0.0)
    saturated_adequate = saturated_rejects = saturated_curvature_adequate = 0
    saturated_reasons = set()
    example = None
    for index in range(_SATURATED_DATASETS):
        design = _copula_design(103000 + index, "saturated",
                                saturated_probabilities, 500, 0.8,
                                "master_trial")
        report = sta.fit_exponent(design)
        test = sta.cluster_lack_of_fit(design, report)
        if test.adequate:
            saturated_adequate += 1
            saturated_rejects += test.rejects
        else:
            saturated_reasons.add(test.inadequate_reason.split(",")[0])
        if index == 2:
            example = (tuple(cell.committed for cell in design.cells),
                       test.adequate, report.cells_fitted, len(design.cells))
        curvature = sta.cluster_curvature(design, report)
        if curvature.adequate:
            saturated_curvature_adequate += 1
    if saturated_adequate or saturated_rejects:
        problems.append(
            f"the review's saturated null produced {saturated_adequate} "
            f"adequate tests and {saturated_rejects} rejections; a design "
            f"whose cells have no within-cell variation has no calibration")
    if example is None or example[2] != example[3]:
        problems.append("the saturated fixture lost a cell from the "
                        "likelihood, which a calibration refusal must never do")
    saturated_calibrated = sta.calibrate_exponent(
        _copula_design(103002, "saturated", saturated_probabilities, 500, 0.8,
                       "master_trial"))
    if saturated_curvature_adequate:
        problems.append(f"{saturated_curvature_adequate} of the saturated "
                        f"nulls produced an adequate curvature calibration")
    for reason in ("lack_of_fit", "curvature"):
        if reason in saturated_calibrated.reasons:
            problems.append(f"seed 103002 still makes a positive {reason!r} "
                            f"claim: {list(saturated_calibrated.reasons)}")
    for reason in ("uncalibrated_fit", "uncalibrated_curvature"):
        if reason not in saturated_calibrated.reasons:
            problems.append(f"seed 103002 does not report {reason}: "
                            f"{list(saturated_calibrated.reasons)}")
    # Nothing on the authoritative path can be rerolled.
    if sta.calibrate_exponent(
            _copula_design(103002, "saturated", saturated_probabilities, 500,
                           0.8, "master_trial")).reasons != \
            saturated_calibrated.reasons:
        problems.append("two calibrations of one design disagree")
    for door in (sta.calibrate_exponent, sta.cluster_curvature,
                 sta.cluster_lack_of_fit):
        strays = sorted(set(inspect.signature(door).parameters)
                        - {"design", "report"})
        if strays:
            problems.append(f"{door.__name__} takes {strays}, through which a "
                            f"decision could be rerolled")

    # The identity that makes the adjustment the right one, and the mutation
    # that removes it.
    probe = _copula_design(9001, "interior",
                           _lack_of_fit_probabilities("interior", 0.0, 0.0),
                           400, 0.8, "master_trial")
    probe_report = sta.fit_exponent(probe)
    basis = sta._nuisance_orthogonal_basis(probe, probe_report)
    naive = _naive_projection(probe, probe_report)
    x = np.array(probe.log_couplings, dtype=float)
    matrix = np.column_stack([np.ones_like(x), x])
    eta = probe_report.amplitude + probe_report.exponent * x
    hazard, factor, _ = sta._hazard_terms(eta)
    weights = np.array([cell.trials for cell in probe.cells],
                       dtype=float) * hazard * factor
    adjusted_gap = float(np.max(np.abs(matrix.T @ (weights[:, None] * basis))))
    naive_gap = float(np.max(np.abs(matrix.T @ (weights[:, None] * naive))))
    if adjusted_gap > 1e-8:
        problems.append(f"the adjusted basis is not W-orthogonal to the "
                        f"nuisance design: |X'WB| = {adjusted_gap:.3e}")
    if naive_gap <= 1e-6:
        problems.append(f"the unadjusted basis is already W-orthogonal "
                        f"(|X'WC| = {naive_gap:.3e}), so this design cannot "
                        f"show the adjustment doing anything")
    scores = sta._cluster_scores(probe, probe_report.amplitude,
                                 probe_report.exponent)
    numerator_gap = float(np.max(np.abs(scores.sum(axis=0) @ basis
                                        - scores.sum(axis=0) @ naive)))
    if numerator_gap > 1e-3:
        problems.append(f"the adjustment moved the numerator by "
                        f"{numerator_gap:.3e}; it must change only the meat")
    meat_gap = float(np.max(np.abs((scores @ basis).T @ (scores @ basis)
                                   - (scores @ naive).T @ (scores @ naive))))
    if meat_gap <= 0.0:
        problems.append("the adjustment left the cluster meat unchanged, so "
                        "the mutation below could not be detected")

    # Nothing to tune.
    signature = set(inspect.signature(sta.cluster_lack_of_fit).parameters)
    strays = sorted(signature - {"design", "report"})
    if strays:
        problems.append(f"cluster_lack_of_fit takes {strays}, through which a "
                        f"p-value could be re-rolled")
    first = sta.cluster_lack_of_fit(probe, probe_report)
    second = sta.cluster_lack_of_fit(probe, probe_report)
    if (first.statistic, first.bootstrap_p, first.seed) != (
            second.statistic, second.bootstrap_p, second.seed):
        problems.append("two runs of the test on one design disagree")
    if first.replicates != sta.LACK_OF_FIT_REPLICATES:
        problems.append("the replicate count is not the frozen one")
    if first.design_digest != probe.digest:
        problems.append("the test is not bound to the design it ran on")

    # Whole-cluster resampling: a design and the same design with its master
    # trials permuted must give the same statistic, because the multiplier
    # re-signs clusters rather than observations.
    permuted_scores = scores[np.random.default_rng(4).permutation(
        scores.shape[0])]
    order_gap = float(np.max(np.abs(permuted_scores.sum(axis=0) @ basis
                                    - scores.sum(axis=0) @ basis)))
    permuted_meat = (permuted_scores @ basis).T @ (permuted_scores @ basis)
    order_meat_gap = float(np.max(np.abs(
        permuted_meat - (scores @ basis).T @ (scores @ basis))))
    if max(order_gap, order_meat_gap) > 1e-8:
        problems.append(f"the statistic depends on the order of the clusters: "
                        f"numerator {order_gap:.2e}, meat "
                        f"{order_meat_gap:.2e}")

    # The authority actually changes the verdict.
    curved = _copula_design(9100, "interior",
                            _lack_of_fit_probabilities("interior", 0.5, 0.0),
                            400, 0.8, "master_trial")
    curved_cal = sta.calibrate_exponent(curved)
    if curved_cal.is_valid:
        problems.append(f"a bend-0.5 curved design calibrated to "
                        f"{curved_cal.verdict}, so the paired authority is "
                        f"not deciding")

    # Too few clusters is a no-result, not a rejection.
    thin = _copula_design(9200, "interior",
                          _lack_of_fit_probabilities("interior", 0.0, 0.0),
                          sta.MIN_LACK_OF_FIT_CLUSTERS - 1, 0.8,
                          "master_trial")
    thin_test = sta.cluster_lack_of_fit(thin, sta.fit_exponent(thin))
    if thin_test.adequate or thin_test.rejects:
        problems.append(f"a design with "
                        f"{sta.MIN_LACK_OF_FIT_CLUSTERS - 1} clusters "
                        f"produced an adequate test")
    thin_cal = sta.calibrate_exponent(thin)
    if "uncalibrated_fit" not in thin_cal.reasons:
        problems.append(f"an inadequate lack-of-fit calibration gave "
                        f"{list(thin_cal.reasons)}, without uncalibrated_fit")

    # For independent namespaces the marginal tests stay authoritative.
    independent = _copula_design(9300, "interior",
                                 _lack_of_fit_probabilities("interior", 1.2,
                                                            0.0),
                                 400, 0.0, "independent_namespace")
    if sta.calibrate_exponent(independent).is_valid:
        problems.append("a strongly curved independent-namespace design was "
                        "accepted, so its marginal tests are not deciding")

    refused("a lack-of-fit report constructed without the factory's token",
            lambda: sta.ClusterScoreTest(**_CLUSTER_TEST_TEMPLATE))
    refused("an adequate lack-of-fit report that also states a reason",
            _cluster_test(inadequate_reason="because"))

    null_label = "null interior, copula rho=0.8"
    return Result("general lack of fit is a nuisance-adjusted cluster score, "
                  "calibrated across dependence strengths and honest at the "
                  "boundary", not problems,
                  measured.get(null_label, (0.0,))[0], 0.13,
                  ("over ensembles frozen after the method and before this "
                   "table, each dataset scored by BOTH cluster tests: "
                   + "; ".join(f"{label} — lack of fit {rate:.1%}, curvature "
                               f"{bend:.1%} of {usable} (marginal deviance "
                               f"{marginal:.1%})"
                               for label, (rate, bend, marginal, usable, _)
                               in measured.items())
                   + f".  The nominal level is "
                     f"{sta.LACK_OF_FIT_ALPHA:.0%} and the null ensembles are "
                     f"judged by the exact two-sided binomial acceptance "
                     f"region at a guard level of {_CALIBRATION_ALPHA:g} — for "
                     f"150 datasets that is [{mutant_low}, {mutant_high}], "
                     f"which excludes the review's 19/150 mutant and admits "
                     f"an ordinary 8/150.  Four dependence structures are "
                     f"covered: independent cells and Gaussian-copula "
                     f"correlations 0.0, 0.4 and 0.8.  The review's saturated "
                     f"null, which the unadjusted test rejected 43 times in "
                     f"120, now declines to calibrate on all "
                     f"{_SATURATED_DATASETS} for BOTH tests with every cell "
                     f"still in the likelihood, and seed 103002 reports "
                     f"uncalibrated_fit and uncalibrated_curvature with no "
                     f"positive claim of either.  The adjusted basis is "
                     f"W-orthogonal to the nuisance design to "
                     f"{adjusted_gap:.1e} while the unadjusted one is off by "
                     f"{naive_gap:.1f}; the numerator moves by "
                     f"{numerator_gap:.1e} and the meat by {meat_gap:.3f}.  "
                     f"Neither test takes a seed or a replicate count, both "
                     f"are invariant to cluster order, both refuse below "
                     f"{sta.MIN_LACK_OF_FIT_CLUSTERS} clusters, and an "
                     f"unsealed or self-contradicting report is refused")
                  if not problems else "; ".join(problems[:6]), covers=(108,))


@check("control roles and holdout evidence are bound to the runs they claim",
       covers=[107])
def check_control_binding():
    """A role is a fact about a sweep, not a label at a call site.

    An independent review observed that the earlier decision path took three
    bare fits: "neither the central report nor the width-only report carries a
    manifest, fingerprint, model role, clock population, or proof that it used
    the same pipeline."  Any three could be passed in any role.

    :func:`~.compare.control_evidence` now binds a calibrated exponent to the
    verified sweep it was fitted from, re-hashes that sweep, and requires the
    role to be true of it: ``central`` is the ONE zero-detuning clock under the
    full model, ``width_only`` is the fixed-contraction model, ``full`` is the
    multi-clock population under the full model.  Each of the three real
    sweeps is offered in each of the three roles, and only the diagonal is
    accepted.

    :func:`~.compare.holdout_evidence` is checked the same way: it computes
    both scores itself, from frozen edges with the pulse centre on a boundary,
    against one declared reference; it refuses runs that disagree about the
    experiment; and it refuses the two roles swapped.
    """
    problems = []
    refused = _refuser(problems)
    sweeps = _ticket06_runs()

    accepted = {}
    for role, label in (("full", "full"), ("central", "central"),
                        ("width_only", "width")):
        try:
            accepted[role] = cmpr.control_evidence(role, sweeps[label])
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"the {role} role was refused for its own sweep: "
                            f"{type(exc).__name__}: {exc}")
    for role, label in (("central", "full"), ("central", "width"),
                        ("full", "central"), ("width_only", "full"),
                        ("width_only", "central"), ("full", "width")):
        refused(f"the {role!r} role claimed for the {label!r} sweep",
                lambda r=role, l=label: cmpr.control_evidence(r, sweeps[l]))
    if "central" in accepted:
        evidence = accepted["central"]
        if evidence.clocks != 1 or evidence.detunings != (0.0,):
            problems.append(f"the accepted central control has "
                            f"{evidence.clocks} clock(s) at "
                            f"{list(evidence.detunings)}")
    if "width_only" in accepted and accepted["width_only"].model != \
            "width_only":
        problems.append("the accepted width-only control is not the "
                        "fixed-contraction model")
    for role, evidence in accepted.items():
        if evidence.couplings != sweeps["full"].couplings:
            problems.append(f"the {role} control's couplings are not the "
                            f"sweep's")
        if not evidence.fingerprints:
            problems.append(f"the {role} control names no runs")

    # The calibration is no longer an argument, so a control cannot be issued
    # for observations its sweep does not hold.  What remains checkable is that
    # the evidence's digest IS the sweep's design digest, asserted above.
    refused("a control evidence built by hand whose calibration is about "
            "other observations",
            lambda: _hand_control_raw(
                "full", accepted["full"].calibrated, digest="elsewhere"))

    # The holdout: computed, frozen-edged, role-bound.
    holdout = cmpr.holdout_evidence(sweeps["full"].runs[-1],
                                    sweeps["full"].runs[-2],
                                    sweeps["width"].runs[-2], 2)
    if not holdout.complete:
        problems.append("a computed holdout reports itself incomplete")
    if holdout.segments != cmpr.FROZEN_SEGMENTS:
        problems.append("the holdout does not use the frozen segments")
    if holdout.full_fingerprint == holdout.control_fingerprint:
        problems.append("the holdout scored one run as both sides")
    if holdout.control_not_worse != cmpr.control_defeats(
            holdout.full_score, holdout.control_score):
        problems.append("the holdout's verdict is not its own scores' verdict")

    refused("a holdout whose full run is the width-only model",
            lambda: cmpr.holdout_evidence(sweeps["full"].runs[-1],
                                          sweeps["width"].runs[-2],
                                          sweeps["width"].runs[-1], 2))
    refused("a holdout whose control run is the full model",
            lambda: cmpr.holdout_evidence(sweeps["full"].runs[-1],
                                          sweeps["full"].runs[-2],
                                          sweeps["full"].runs[0], 2))
    refused("a holdout mixing two populations",
            lambda: cmpr.holdout_evidence(sweeps["central"].runs[-1],
                                          sweeps["full"].runs[-2],
                                          sweeps["width"].runs[-2], 2))

    # The frozen edges put the pulse centre on a boundary, and a table binned
    # any other way is refused rather than assigned to one side.
    manifest = sweeps["full"].runs[-1].manifest
    centre = manifest.value("pulse_centre")
    edges = cmpr.frozen_edges(manifest, 3)
    if centre not in edges:
        problems.append(f"frozen_edges did not place the pulse centre "
                        f"{centre} on a boundary")
    straddling = obsv.uniform_edges(manifest.value("window_open"),
                                    manifest.value("window_close"), 3)
    if centre in straddling:
        problems.append("the straddling fixture happens to land on the "
                        "centre, so it cannot show the refusal")
    else:
        refused("a rising/falling split over a table whose bin straddles the "
                "pulse centre",
                lambda: cmpr.rising_falling_split(
                    manifest,
                    obsv.risk_table(sweeps["full"].runs[-1].ledger,
                                    straddling)))

    # Every manifest field, one at a time: each must either change the
    # experiment family or be on the reviewed exclusion list.  An independent
    # review found ``drive`` missing from the old CRN-derived allowlist, so a
    # stationary one-clock sweep joined a pulsed causal experiment; the family
    # is now built by *subtraction* from the whole manifest, and this audit is
    # what keeps a future schema field covered the day it is added.
    reference_manifest = sweeps["full"].runs[0].manifest
    family = cmpr.experiment_family(reference_manifest)
    audited = allowed = pinned = 0
    for field in rawled.MANIFEST_KEYS:
        alternative = _manifest_alternative(reference_manifest, field)
        if alternative is None:
            pinned += 1
            continue
        audited += 1
        moved = cmpr.experiment_family(alternative) != family
        excluded = field in cmpr.EXPERIMENT_FAMILY_EXCLUSIONS
        if moved and excluded:
            problems.append(f"{field!r} is on the exclusion list and still "
                            f"changes the experiment family")
        if not moved and not excluded:
            problems.append(f"mutating {field!r} does not change the "
                            f"experiment family and it is not on the reviewed "
                            f"exclusion list")
        allowed += 1 if excluded else 0
    if audited < 30:
        problems.append(f"only {audited} manifest fields could be mutated, "
                        f"which is too few for this to be an audit")
    if "drive" not in cmpr.EXPERIMENT_FAMILY_FIELDS:
        problems.append("the drive is outside the experiment family, which is "
                        "the exact omission this audit exists for")

    # The review's exact reproduction: a stationary central control.
    stationary = sweeps["stationary_central"]
    if stationary.runs[0].manifest.value("drive") != "stationary":
        problems.append("the stationary fixture is not stationary")
    if cmpr.experiment_family(stationary.runs[0].manifest) == family:
        problems.append("a stationary sweep shares the pulsed experiment's "
                        "family, so the drive is still not bound")

    # The two provenance joins an independent review found missing.  Both
    # replays use only genuine factory output, and both must now refuse
    # *before* any schema-v3 status blocker is consulted.
    full_evidence = accepted.get("full")
    width_evidence = accepted.get("width_only")
    central_evidence = accepted.get("central")
    if full_evidence and width_evidence and central_evidence:
        genuine = cmpr.paired_exponent_contrast(sweeps["full"], sweeps["width"])
        foreign = cmpr.paired_exponent_contrast(sweeps["twin"], sweeps["width"])
        holdout_ok = cmpr.holdout_evidence(sweeps["full"].runs[-1],
                                           sweeps["full"].runs[-2],
                                           sweeps["width"].runs[-2], 2)
        if foreign.full_digest != genuine.full_digest:
            problems.append(
                "the gate-rewritten twin does not reproduce the full sweep's "
                "design digest, so this replay cannot show that digests alone "
                "are insufficient")
        if foreign.full_fingerprints == genuine.full_fingerprints:
            problems.append("the twin's fingerprints equal the full sweep's, "
                            "so the join under test is vacuous")
        try:
            cmpr.causal_decision(full_evidence, central_evidence,
                                 width_evidence, foreign, 0.25, holdout_ok)
        except ValueError:
            pass
        else:
            problems.append(
                "a contrast computed over a different set of full-model runs, "
                "with an identical design digest, was accepted")
        try:
            cmpr.causal_decision(full_evidence, central_evidence,
                                 width_evidence, genuine, 0.25, holdout_ok)
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"the genuinely joined decision was refused: "
                            f"{type(exc).__name__}: {exc}")

        foreign_central = cmpr.control_evidence("central", sweeps["foreign_central"])
        if foreign_central.experiment_family == \
                full_evidence.experiment_family:
            problems.append("the foreign central control shares the full "
                            "model's experiment family, so this replay is "
                            "vacuous")
        if central_evidence.experiment_family != \
                full_evidence.experiment_family:
            problems.append("the genuine central control does not share the "
                            "full model's experiment family, so the join "
                            "would refuse every real decision")
        if central_evidence.crn_identity == full_evidence.crn_identity:
            problems.append("the central control shares the full model's CRN "
                            "identity, so equality would have been the right "
                            "check after all")
        try:
            cmpr.causal_decision(full_evidence, foreign_central,
                                 width_evidence, genuine, 0.25, holdout_ok)
        except ValueError:
            pass
        else:
            problems.append("a central control from an unrelated stream "
                            "hierarchy was accepted")
        try:
            cmpr.causal_decision(
                full_evidence, central_evidence, width_evidence, genuine, 0.25,
                cmpr.holdout_evidence(sweeps["twin"].runs[-1],
                                      sweeps["twin"].runs[-2],
                                      sweeps["width"].runs[-2], 2))
        except ValueError:
            pass
        else:
            problems.append("a holdout scored over another sweep's runs was "
                            "accepted")

    coarse = cmpr.rising_falling_split(
        manifest, obsv.risk_table(sweeps["full"].runs[-1].ledger,
                                  cmpr.frozen_edges(manifest, 2)))
    fine = cmpr.rising_falling_split(
        manifest, obsv.risk_table(sweeps["full"].runs[-1].ledger, edges))
    refused("a discrepancy between two differently binned splits",
            lambda: cmpr.discrepancy_score(
                coarse, fine, obsv.winner_mismatch(sweeps["full"].runs[-1]
                                                   .ledger),
                obsv.winner_mismatch(sweeps["full"].runs[-1].ledger)))

    return Result("control roles and holdout evidence are bound to the runs "
                  "they claim", not problems, float(len(problems)), 0.0,
                  (f"each of the three real sweeps is offered in each of the "
                   f"three roles and only the diagonal is accepted: the "
                   f"central role requires the one zero-detuning clock under "
                   f"the full model, the width-only role requires the "
                   f"fixed-contraction model, and the full role requires the "
                   f"multi-clock population — six off-diagonal claims are "
                   f"refused, as is a fit covering other couplings than its "
                   f"sweep.  The holdout computes both scores itself from "
                   f"frozen edges with the pulse centre on a boundary, names "
                   f"the three runs it used, and refuses the two model roles "
                   f"swapped and two populations mixed; a table whose bin "
                   f"straddles the centre is refused rather than assigned to "
                   f"one side, and two differently binned splits cannot be "
                   f"differenced.  Every one of the "
                   f"{len(rawled.MANIFEST_KEYS)} manifest fields is mutated in "
                   f"turn and must either change the experiment family or "
                   f"appear on the reviewed exclusion list "
                   f"{list(cmpr.EXPERIMENT_FAMILY_EXCLUSIONS)}; a stationary "
                   f"central control is refused where a pulsed one is "
                   f"accepted.  Both provenance joins are exercised on "
                   f"genuine factory output: a contrast computed over a "
                   f"gate-rewritten twin of the full sweep — identical design "
                   f"digest, different fingerprints — is refused, and so is a "
                   f"central control from an unrelated stream hierarchy, "
                   f"which shares the full model's coupling grid and differs "
                   f"only in its experiment family; the genuinely joined "
                   f"decision beside them is accepted")
                  if not problems else "; ".join(problems[:6]), covers=(107,))


# ---------------------------------------------------------------------------
# 11. Feasibility, power, the frozen matrix and the pilot firewall (ticket 07)
# ---------------------------------------------------------------------------
# Everything below measures rather than assumes.  `experiments.py` is named in
# `_RAW_FORBIDDEN_MODULES`, so the raw graph cannot reach it.
#
# **This section runs no pilot.**  The pilot firewall is exercised on
# four-trial synthetic runs created, quarantined and removed by the suite; the
# bounded pilot the ticket describes needs John's checkpoint-1 approval and has
# not been run.
#
# The fixtures below are the closure round of an independent review.  Four of
# its findings are visible directly in them: the benchmark now runs at the
# intended sixty-four clocks and finest timestep with a warmup and two timed
# repeats; the power calculation sizes every arm from its own declared
# envelope; the numerical disposition carries every authoritative evidence row
# with its unit; and the feasibility conclusion is the verdict of a finite
# declared search rather than an unqualified impossibility.

_T07_ARMS = (
    # (name, clocks, probability floor, ceiling, information factor,
    #  invalid-fit probability, pairs with full)
    ("full", 64, 0.10, 0.95, 1.0, 0.05, True),
    ("central_control", 1, 0.02, 0.95, 1.0, 0.10, False),
    ("width_only_control", 64, 0.05, 0.95, 1.0, 0.05, True),
)

_T07_EXPONENT = 2.0
_T07_COUPLING_RANGE = (0.5, 2.0)
_T07_CELLS = 6

#: The declared common-random-number variance inflation, and the declared
#: conservative sizing factor beside it.  Two separate numbers on purpose: the
#: first is a claim about pairing that the recovery ensemble must not exceed,
#: the second is judgement about everything neither it nor the arm envelopes
#: capture.
_T07_PAIRING_INFLATION = 2.0
_T07_CONSERVATIVE_FACTOR = 1.25

#: The intended production timestep: ticket 04's own S3 finest step, the
#: finest level at which any continuum evidence exists at all.
_T07_TIMESTEP = 0.001953125

#: The planned 95-per-cent half-width of a production commit-time quantile,
#: two per cent of the pulse duration.  Declared rather than derived because a
#: quantile's sampling distribution depends on the density at the quantile,
#: which is what the experiment is trying to measure.
_T07_TIME_HALF_WIDTH = 0.08

#: The recovery ensemble.  Frozen before the table it produces.
_T07_RECOVERY_TRIALS = 150
_T07_RECOVERY_REPLICATES = 150
_T07_RECOVERY_SEED = 20260828
_T07_RECOVERY_CORRELATION = 0.85

#: How far the measured peak may grow when the noise cube quadruples.
_T07_PEAK_GROWTH_BOUND = 1.6

#: How far apart the walked-clock-step rates of two fixtures four times apart
#: in clock count and twenty-five times apart in timestep may sit before the
#: work model is not a work model.  An independent review asked for an
#: independent spot check of the intended-resolution rate; this is that check,
#: run inside the suite rather than quoted.
_T07_RATE_AGREEMENT = 1.5

_T07_CACHE = {}


def _t07_refuser(problems):
    """``refused(label, expected, call)`` — the exception *type* is contractual."""
    def refused(label, expected, call):
        try:
            call()
        except expected:
            return
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"{label}: raised {type(exc).__name__}, expected "
                            f"{expected.__name__}")
        else:
            problems.append(f"{label}: ACCEPTED")
    return refused


def _t07_config(clocks, timestep, duration, trials, shadow,
                namespace="t07-benchmark", label="pilot"):
    return rawcfg.RawEventConfig(
        grid=rawcfg.RawClockGrid(3.0, clocks), peak_coupling=1.0,
        pulse_duration=duration, phase_diffusion=0.08, lock_tolerance=0.35,
        dwell_time=0.5, timestep=timestep, trials=trials,
        stream_namespace=namespace, run_label=label, shadow_trials=shadow)


def _t07_benchmarks():
    """Measure the real streamed race once, and reuse it across checks.

    Four fixtures, and each answers one thing an independent review asked for:

    ``intended``
        Sixty-four clocks at the **intended** finest timestep and the proposed
        blocking, with a discarded warmup and two timed repeats.  Its pulse is
        shortened so the workload stays bounded, which preserves the clock
        count, the timestep, the per-step branching and the tongue
        entry/exit structure while cutting the step count — and it commits
        nothing, so its first pass does not truncate and its measured rate is
        the honest one.
    ``base`` / ``trials4x`` / ``steps4x``
        The controlled quadruplings, at a coarser but still representative
        setting, that carry the no-cube flatness argument.
    ``shadow``
        ``base`` with every trial shadowed instead of one, so the cost of a
        shadow rewalk is *measured* rather than assumed to equal a base
        clock-step.
    """
    if "benchmarks" in _T07_CACHE:
        return _T07_CACHE["benchmarks"]

    fingerprint = xpr.source_fingerprint()
    plan = {
        "t07-bench-intended": (64, _T07_TIMESTEP, 0.5, 1, 1),
        "t07-bench-base": (16, 0.05, 4.0, 6, 1),
        "t07-bench-trials4x": (16, 0.05, 4.0, 24, 1),
        "t07-bench-steps4x": (16, 0.0125, 4.0, 6, 1),
        "t07-bench-shadow": (16, 0.05, 4.0, 6, 6),
    }
    results = {}
    for label, (clocks, timestep, duration, trials, shadow) in plan.items():
        fixture = xpr.BenchmarkFixture(
            label, _t07_config(clocks, timestep, duration, trials, shadow),
            "full", 16, 64, 1, 2)
        results[label] = xpr.run_benchmark(fixture, fingerprint)
    _T07_CACHE["benchmarks"] = results
    return results


def _t07_slowest():
    """The benchmark with the lowest measured rate — costs are scaled from it."""
    return sorted(_t07_benchmarks().values(),
                  key=lambda item: item.clock_steps_per_second)[0]


def _t07_envelopes():
    return tuple(xpr.ArmEnvelope(*entry) for entry in _T07_ARMS)


def _t07_target():
    return xpr.SamplingTarget(
        exponent_half_width=0.25, minimum_causal_contrast=0.5,
        coupling_low=_T07_COUPLING_RANGE[0],
        coupling_high=_T07_COUPLING_RANGE[1], cells=_T07_CELLS,
        pairing_inflation=_T07_PAIRING_INFLATION,
        conservative_factor=_T07_CONSERVATIVE_FACTOR,
        resampling_unit="master_trial", arm_envelopes=_t07_envelopes(),
        shadow_fraction=0.05, maximum_trials_per_cell=20000)


def _t07_power():
    return xpr.power_estimate(_t07_target())


def _t07_recovery():
    if "recovery" not in _T07_CACHE:
        target = _t07_target()
        amplitude = (math.log(-math.log1p(-0.5))
                     - _T07_EXPONENT * math.log(math.sqrt(0.5) * math.sqrt(2.0)))
        _T07_CACHE["recovery"] = xpr.recover_exponent(
            target.couplings, amplitude, _T07_EXPONENT, _T07_RECOVERY_TRIALS,
            _T07_RECOVERY_REPLICATES, _T07_RECOVERY_SEED,
            correlation=_T07_RECOVERY_CORRELATION,
            arm_correlation=xpr.CONTRAST_COVARIANCE_FLOOR,
            control_exponent=1.0)
    return _T07_CACHE["recovery"]


def _t07_matrix():
    power = _t07_power()
    couplings = _t07_target().couplings
    return xpr.PrimaryMatrix(
        label="T07 proposed primary matrix",
        couplings=couplings, clocks=64,
        arm_clocks=tuple((name, clocks) for name, clocks, *_ in _T07_ARMS),
        arm_trials=tuple((name, power.arm_trials[name])
                         for name, *_ in _T07_ARMS),
        grid_half_width=3.0, pulse_duration=4.0, pulse_centre=0.0,
        phase_diffusion=0.08, lock_tolerance=0.35, dwell_time=0.5,
        timestep=_T07_TIMESTEP,
        timestep_ladder=(_T07_TIMESTEP, _T07_TIMESTEP / 2.0,
                         _T07_TIMESTEP / 4.0),
        refinement_couplings=(couplings[1], couplings[3]),
        refinement_arm="full", refinement_trials_per_cell=200,
        trials_per_cell=power.arm_trials["full"], shadow_fraction=0.05,
        minimum_eligible_clocks=xpr.MIN_ELIGIBLE_CLOCKS,
        discrete_staircase_fallback=(
            "if fewer than the declared minimum number of clocks is eligible "
            "at the weakest coupling, the claim narrows to the exact finite "
            "discrete grid and its visible staircase; the spacing-weighted "
            "continuum flux is never substituted for the bare finite sum"),
        stop_rule=(
            "a trial stops at the earliest endpoint on which any clock "
            "completes its uninterrupted dwell; every same-endpoint "
            "co-completer is retained and no winner is randomized"),
        failure_rule=(
            "a refinement ladder that misses the frozen numerical budget, or a "
            "moving-band audit that returns numerical_no_result, blocks "
            "scientific interpretation of the whole sweep; no fit window is "
            "reselected and no budget is widened after results are opened"))


def _t07_budget():
    power = _t07_power()
    return xpr.NumericalBudget(
        label="T07 production numerical budget, tied to planned uncertainty",
        allowed_fraction=xpr.ALLOWED_NUMERICAL_FRACTION,
        coverage_sigma=xpr.COVERAGE_SIGMA,
        probability_half_width=xpr.CONFIDENCE_Z * math.sqrt(
            0.25 / power.trials_per_cell),
        time_half_width=_T07_TIME_HALF_WIDTH,
        trials_per_cell=power.trials_per_cell,
        reference_probability=0.5, intended_timestep=_T07_TIMESTEP)


def _t07_evidence():
    """**Every** authoritative ticket-04 row, at each ladder's finest level.

    Not one envelope per unit: an independent review pointed out that
    selecting a maximum by absolute point error can drop a row whose
    uncertainty-aware bound is larger, and that the execution note's "six rows"
    did not match the four the code supplied.  Every observable at every
    position is carried now, and the limiting row is chosen by the full bound
    inside its own unit.

    ``configuration`` is ``non_intended`` on every row, and that is the
    finding rather than an oversight: the S3 ladder is a *stationary* reference
    cell and the S3b matrix a reduced pulsed one.
    """
    if "evidence" in _T07_CACHE:
        return _T07_CACHE["evidence"]

    s3_budgets = _s3_budgets()
    s3 = kdf.compare_refinement(_s3_dataset(), s3_budgets, s3_budgets.digest)
    pooled_budgets = _audit_budgets(
        "S3b moving-band audit, pooled reference budgets", _AUDIT_TRIALS,
        ("pooled",))
    pooled = kdf.compare_refinement(_audit_dataset(), pooled_budgets,
                                    pooled_budgets.digest)

    stationary = ("the ticket-04 S3 stationary reference cell: one fixed "
                  "coupling, one fixed band, three declared starts, no pulse "
                  "and no population")
    moving = ("the ticket-04 S3b reduced moving-band matrix, pooled over three "
              "independently keyed clocks at the finest declared step")

    rows = []
    for verdict, source, clusters, description in (
            (s3, "stationary_oracle", _S3_WALKERS, stationary),
            (pooled, "moving_band_audit", _AUDIT_TRIALS, moving)):
        finest = min(level.timestep for level in verdict.levels)
        for level in verdict.levels:
            if level.timestep != finest:
                continue
            if level.observable == "added_resets_mean":
                # Ticket 04 froze this as a diagnostic with no continuum limit
                # and `require_decrease = false`; it is reported there and is
                # not one of the convergent observables a budget gates on.
                continue
            rows.append(xpr.NumericalEvidence(
                source=source, observable=level.observable,
                unit=level.unit, position=level.position,
                timestep=level.timestep, measured=level.absolute_error,
                standard_error=level.standard_error, sample_clusters=clusters,
                verdict=verdict.verdict, configuration="non_intended",
                description=description))
    _T07_CACHE["evidence"] = (tuple(rows), s3, pooled)
    return _T07_CACHE["evidence"]


def _t07_disposition():
    evidence, _, _ = _t07_evidence()
    return xpr.numerical_disposition(_t07_budget(), evidence)


#: The finite declared option set the feasibility search enumerates.  Frozen
#: here, above the search that reads it, so that "no feasible option among
#: those searched" names a set a reader can inspect.
_T07_OPTIONS = (
    ("as proposed", 1.0, 1.0, 2406, "non_intended"),
    ("half the timestep", 0.5, 1.0, 2406, "non_intended"),
    ("an eighth of the timestep", 0.125, 1.0, 2406, "non_intended"),
    ("a sixteenth of the timestep", 0.0625, 1.0, 2406, "non_intended"),
    ("16x the validation sample", 1.0, 16.0, 2406, "non_intended"),
    ("256x the validation sample", 1.0, 256.0, 2406, "non_intended"),
    ("an eighth of the step and 256x the sample", 0.125, 256.0, 2406,
     "non_intended"),
    ("a sixteenth of the step, 1024x the sample", 0.0625, 1024.0, 2406,
     "non_intended"),
    ("100 trials per cell, as proposed otherwise", 1.0, 1.0, 100,
     "non_intended"),
    ("35 trials per cell, as proposed otherwise", 1.0, 1.0, 35,
     "non_intended"),
    ("a sixteenth of the step, 1024x the sample, 35 trials", 0.0625, 1024.0,
     35, "non_intended"),
    ("all of the above, measured at the intended configuration", 0.0625,
     1024.0, 35, "intended"),
)


def _t07_options():
    return tuple(xpr.FeasibilityOption(*entry) for entry in _T07_OPTIONS)


def _t07_search():
    evidence, _, _ = _t07_evidence()
    return xpr.search_feasible_options(_t07_budget(), evidence, _t07_options())


def _t07_firewall():
    return xpr.PilotFirewall(
        pilot_namespace="xpilot-t07-range",
        production_namespace="prod-t07-primary",
        pilot_prefix="xpilot-t07", production_prefix="prod-t07",
        minimum_events=xpr.MIN_PILOT_EVENTS,
        minimum_survivors=xpr.MIN_PILOT_SURVIVORS,
        minimum_cells=xpr.MIN_SELECTED_CELLS)


def _t07_fixture_couplings():
    """The four candidate couplings the deterministic fixture covers.

    The proposed matrix's own first four nodes, **bit for bit**, so that they
    are couplings the frozen production plan also declares.  That is what makes
    the negative probe sharp: when the production plan refuses these runs it
    refuses them for their clock count and their timestep — for being a
    different experiment — and not merely for sitting at a coupling it has
    never heard of.
    """
    return tuple(_t07_target().couplings[:4])

#: How many trials the fixture's *source* runs walk before cloning.  Small
#: enough that four of them cost a few seconds, large enough that both a
#: commitment and an unresolved trial appear at every declared coupling.
_T07_FIXTURE_SOURCE_TRIALS = 12

#: The fixture's row resolution.  Eight clocks at a twenty-five-times coarser
#: step than the production plan's: a *different, honestly declared plan*, not
#: the production plan's manifest with cheaper rows underneath it.
_T07_FIXTURE_CLOCKS = 8
_T07_FIXTURE_TIMESTEP = 0.05


def _t07_plan():
    """The frozen range-only pilot plan — the pilot a checkpoint would approve.

    An independent review found the pilot writer authenticating *where* a run
    was written and not *which pilot John approved*: it took an arbitrary raw
    configuration and either model, so a width-only two-clock ``dt=1``
    two-trial diagnostic could be written to the right place and then projected
    into authoritative range evidence.  This record is the missing half, and
    every authoritative door takes it.
    """
    # **The** approved pilot, built from the module's own frozen spec rather
    # than from constants restated here: an independent review's eight-clock
    # plan satisfied every self-consistency rule and drove the proposal, so
    # identity is what the production doors check and there is exactly one
    # thing for them to check against.
    return xpr.canonical_pilot_plan(_t07_firewall(), xpr.source_fingerprint())


def _t07_fixture_plan():
    """A second plan, built by the **same factory**, at a runnable resolution.

    The frozen production plan runs 64 clocks at ``dt = 1.953125e-3`` over 200
    trials in each of six cells; that is about forty-three hours of real race
    time and it is exactly the work checkpoint 1 has not authorized.  A test
    suite cannot run it, and a fixture that *claimed* to be it — the production
    plan's manifest with cheaper rows underneath — would be a fabricated
    measurement sitting inside the very boundary these checks exist to defend.

    So the fixture declares what it is.  This is a different plan, honestly
    stating eight clocks and ``dt = 0.05``, minted through the same
    :func:`experiments.pilot_plan` factory, against the same firewall and
    run-name family, at the same 200 trials per cell.  Its runs therefore carry
    a manifest that is *its own* manifest, and the suite asserts both
    directions: the fixture's runs are authoritative under the fixture plan and
    are **refused** under the production plan, which is what proves the plan
    check is a check on the physics and not on the location.

    Nothing scientific is read from these runs.  They exist to exercise the
    authority boundary — that a recount is driven by bytes on disk rather than
    by a caller's record — and they are removed on every exit path.
    """
    return xpr.pilot_plan(
        label="T07 deterministic pilot fixture plan (verifier-only, not the "
              "approved pilot)",
        firewall=_t07_firewall(), fingerprint=xpr.source_fingerprint(),
        couplings=_t07_fixture_couplings(), clocks=_T07_FIXTURE_CLOCKS,
        grid_half_width=3.0, timestep=_T07_FIXTURE_TIMESTEP,
        pulse_duration=4.0, pulse_centre=0.0, phase_diffusion=0.08,
        lock_tolerance=0.35, dwell_time=0.5, trials_per_cell=200,
        shadow_fraction=0.05, run_name_prefix="xpilot-t07-fixture-cell",
        # **Declared, not inferred.**  A production decision door asks for
        # ``approved_production_pilot`` and refuses this plan by name, so the
        # cheap eight-clock fixture cannot reach a proposal or a checkpoint
        # however convenient its numbers are.
        purpose="verifier_fixture")


#: The **reserved** run names the approved production pilot writes its cells
#: under, derived from the same frozen spec the canonical plan is built from.
#: Nothing the verifier's cloning helper writes may carry one of these names.
def _t07_reserved_run_names():
    """The approved production pilot's own ordered cell names."""
    spec = xpr.PRODUCTION_PILOT_SPEC
    return tuple(f"{spec['run_name_prefix']}-{index}"
                 for index in range(len(spec["couplings"])))


def _t07_require_fixture_plan(plan):
    """Validate ``plan`` and return a **freshly built** fixture plan to use.

    Note the return value.  This door does not hand the caller's record back;
    it hands back the record :func:`_t07_fixture_plan` builds, and the writers
    below continue with **that** object and never with the one they were given.

    The cloning helper below is the one place in this package that writes a
    finished five-file closure without walking the races it describes.  An
    independent review found it authenticating nothing at all: it took whatever
    plan it was handed, wrote cells under whatever ``run_name_for`` returned,
    and called ``config_for`` twice — once for the tiny source run and once
    again for the manifest written above the clone.

    Both halves of that are reachable authority.  Handing it the canonical
    production plan made it write the reserved ``xpilot-t07-cell-*`` family
    directly; and because a ``PilotPlan`` *subclass* may answer ``config_for``
    differently on alternate calls, the review's ``AlternatingPlan`` — whose
    fields and digest equalled the canonical plan's — returned a cheap
    ``dt = 0.05``, coupling-0.2 configuration for the source walk and the
    canonical configuration for the manifest.  Four-trial histories at a
    twenty-five-times coarser step were then presented under the approved
    pilot's own manifest, the genuine exact-typed canonical plan recounted
    them, and the selection, post-range join, proposal, authoritative rebuild
    and checkpoint all accepted the resulting ``post_range_powered`` snapshot.
    A cloning helper had minted production evidence.

    So the door is identity, taken **before any directory exists**:

    - the record type is exactly :class:`experiments.PilotPlan`, so a subclass
      that can override ``config_for`` — the whole alternating attack — is
      refused by type rather than by watching what it returns;
    - the declared purpose is ``verifier_fixture`` and the run-name family
      carries :data:`experiments.FIXTURE_PREFIX_MARKER`, so the canonical
      production plan is refused by what it says it is;
    - the plan rebuilds exactly through ``require_authoritative_plan`` against
      the live firewall, the live source fingerprint and the live schema
      versions, so a sealed exact-typed relabel does not survive;
    - and it agrees field for field and digest for digest with
      :func:`_t07_fixture_plan`, so a *different* honestly-built fixture plan,
      or one carrying a copied digest, is refused as well.  There is one
      fixture this helper may write, and this is it;
    - finally the names it would write are checked against the reserved
      production family, so a fixture cannot occupy a production identity even
      if some future edit made the four rules above disagree.

    **Fields are not behaviour.**  A second independent review pointed out that
    the list above validates a record and then lets the writers call methods on
    it.  :class:`experiments.PilotPlan` is frozen but not slotted, so an
    *exact-typed* instance carrying every declared field and the right digest
    can still take instance attributes through ``object.__setattr__`` that
    shadow ``require_run_name``, ``coupling_for``, ``config_for`` and
    ``run_name_for`` — plain functions are non-data descriptors, so the
    instance dictionary wins.  The reviewer built exactly that, passed this
    door, and had the per-cell helper write an honest eight-clock ``dt = 0.05``
    closure under the reserved name ``xpilot-t07-cell-0``.  The manifest
    underneath was the fixture's own and no canonical recount was claimed, but
    a fixture had still occupied a production identity, which is the invariant.

    Two independent answers, both here:

    - the supplied record is **refused** if it carries any attribute outside
      the declared dataclass fields, which is precisely what a shadowing
      instance attribute is.  ``run_names``, ``digest`` and ``cells`` are
      properties — data descriptors — and were never shadowable; the four
      plain methods were, and now are not;
    - and the caller's record is **not returned**.  What comes back is the
      freshly constructed :func:`_t07_fixture_plan` record, built at this
      boundary from the module's own factory rather than taken from a cache or
      an alias, so even an unforeseen route to instance state on the supplied
      object cannot influence a name, a coupling or a configuration afterwards.
    """
    xpr.require_exact_type(plan, xpr.PilotPlan, "plan")
    # Before anything is read from it: a frozen dataclass keeps its fields in
    # the instance dictionary, so *only* field names belong there.  Anything
    # else is an injected attribute, and for the four plain methods the writers
    # call it would shadow the class implementation outright.
    injected = sorted(set(vars(plan)) - set(xpr.PilotPlan.__dataclass_fields__))
    if injected:
        raise ValueError(
            f"this pilot plan carries the instance attribute(s) {injected}, "
            f"which are not declared fields of PilotPlan.  The record is "
            f"frozen but not slotted, so such an attribute shadows the class "
            f"method of the same name; a plan whose fields and digest are this "
            f"fixture's while its name, coupling or configuration mapping is a "
            f"caller's function is not this fixture")
    if plan.purpose != "verifier_fixture":
        raise ValueError(
            f"the deterministic fixture writer clones a handful of real "
            f"histories up to a declared trial count; it may do that only for "
            f"a plan declaring purpose 'verifier_fixture', and this plan "
            f"declares {plan.purpose!r}.  Cloned histories written under the "
            f"approved pilot's own manifest would be a fabricated measurement "
            f"inside the boundary these checks exist to defend")
    if xpr.FIXTURE_PREFIX_MARKER not in plan.run_name_prefix:
        raise ValueError(
            f"the fixture writer writes only under a run-name family carrying "
            f"{xpr.FIXTURE_PREFIX_MARKER!r}; {plan.run_name_prefix!r} does "
            f"not, so its cells would be indistinguishable by name from runs "
            f"the approved pilot wrote")
    expected = _t07_fixture_plan()
    xpr.require_authoritative_plan(plan, _t07_firewall(),
                                   xpr.source_fingerprint(),
                                   purpose="verifier_fixture")
    disagree = [name for name in xpr.PilotPlan.__dataclass_fields__
                if name != "seal"
                and getattr(plan, name) != getattr(expected, name)]
    if disagree or plan.digest != expected.digest:
        raise ValueError(
            f"this is not the verifier's own fixture plan.  It disagrees with "
            f"the plan _t07_fixture_plan builds on "
            f"{disagree or ['digest']}; a plan that is internally consistent, "
            f"and even one that reproduces a digest, is not thereby the one "
            f"fixture this cloning helper is permitted to write")
    reserved = _t07_reserved_run_names()
    clash = [name for name in plan.run_names if name in reserved]
    if clash:
        raise ValueError(
            f"this plan writes {clash}, which is inside the approved "
            f"production pilot's reserved run-name family {list(reserved)}; a "
            f"cloned fixture cell may never occupy a production identity")
    # The freshly built record, never the caller's.  ``expected`` came from
    # ``_t07_fixture_plan()`` a few lines above — the factory, called here, not
    # a module cache or an alias someone else holds — so nothing that was ever
    # attached to the supplied object travels past this line.
    if set(vars(expected)) - set(xpr.PilotPlan.__dataclass_fields__):
        raise AssertionError(
            "the freshly built fixture plan carries an attribute outside its "
            "declared fields; the record this door returns is supposed to be "
            "the factory's own and nothing else")
    return expected


def _require_fixture_source_name(source_name, plan):
    """Return ``source_name`` only if it is an honest fixture-only scratch name.

    The source run is a real twelve-trial race and it is thrown away as soon as
    its histories have been cloned, but while it exists it is a run in the
    quarantine like any other.  So it carries the fixture marker too, it is one
    path segment, and it is neither one of this plan's declared cell names nor
    anything inside the approved pilot's reserved family.
    """
    name = xpr._require_text(source_name, "source_name", maximum=96)
    if "/" in name or "\\" in name or name in (".", ".."):
        raise ValueError(f"source_name must be one path segment, got {name!r}")
    if xpr.FIXTURE_PREFIX_MARKER not in name:
        raise ValueError(
            f"the fixture's scratch source run {name!r} does not carry "
            f"{xpr.FIXTURE_PREFIX_MARKER!r}; every run this helper writes says "
            f"in its own name that it is a fixture")
    if name in plan.run_names or name in _t07_reserved_run_names():
        raise ValueError(
            f"the scratch source run {name!r} is a declared cell name; a "
            f"twelve-trial source walk may not be written under a name a "
            f"recount would later read as a cell")
    return name


def _t07_clone_rows(source, plan):
    """Clone one source run's real histories up to the plan's trial count.

    The fixture's one liberty, and it is a liberty about **arithmetic**, not
    about physics.  Every row here is a row a real race wrote: a committed
    trial's ledger line with its own winners, co-completion, per-winner columns
    and opportunity totals, and the eight authoritative clock rows and the
    eight no-stop shadow rows that belong to it; and the same for an unresolved
    trial.  What the clone changes is the trial *identifier* and how many times
    each history appears, so that a cell reaches the plan's declared 200 trials
    with at least twenty commitments and at least twenty survivors without
    walking two hundred races per cell in a test suite.

    Everything the closure gate derives is therefore still derived from real
    rows: the category comes from the clock rows, the winner list from the
    clocks that say they won, the four count totals and the opportunity sum
    from the same rows, and the exposure of every row is **recomputed** here
    through ``raw_race.exposure_of`` — the writer's own expression — against
    that row's own observation end.  Nothing is asserted beside the rows.

    The shadow sample stays the prefix rule it is: the plan's shadow count is
    the first ``shadow_trials`` identifiers, and each of those is cloned from a
    source trial that really was shadowed, so every shadow row is still the
    same physical walk as the censored row it sits beside.
    """
    ledger = list(source.rows("ledger"))
    clocks = list(source.rows("clocks"))
    shadow = list(source.rows("shadow"))
    per_trial = {}
    for row in clocks:
        per_trial.setdefault(row["trial"], []).append(row)
    per_shadow = {}
    for row in shadow:
        per_shadow.setdefault(row["trial"], []).append(row)
    stops = {row["trial"]: row["stop_time"] for row in ledger}

    shadowed = sorted(per_shadow)
    committed = [row["trial"] for row in ledger
                 if row["category"] == "committed" and row["trial"] in per_shadow]
    survivors = [row["trial"] for row in ledger
                 if row["category"] != "committed" and row["trial"] in per_shadow]
    if not committed or not survivors:
        raise AssertionError(
            f"the fixture source run produced categories "
            f"{sorted({row['category'] for row in ledger})} over "
            f"{len(shadowed)} shadowed trials; the clone needs one committed "
            f"and one unresolved history that were both shadowed")
    lines = {row["trial"]: row for row in ledger}

    # Alternating, so both categories are present in the shadow prefix as well
    # as in the body, and both counts are far above the frozen minima.
    order = [committed[0] if index % 2 == 0 else survivors[0]
             for index in range(plan.trials_per_cell)]

    opened = plan.window_open
    closed = plan.window_close
    out_ledger, out_clocks, out_shadow = [], [], []
    for index, origin in enumerate(order):
        row = dict(lines[origin])
        row["trial"] = index
        out_ledger.append(row)
        for item in per_trial[origin]:
            clone = dict(item)
            clone["trial"] = index
            ended = (clone["committed_at"] if clone["committed_at"] is not None
                     else stops[origin])
            clone["exposure_time"] = rawrace.exposure_of(opened, ended)
            out_clocks.append(clone)
        if index < plan.shadow_trials:
            for item in per_shadow[origin]:
                clone = dict(item)
                clone["trial"] = index
                ended = (clone["committed_at"]
                         if clone["committed_at"] is not None else closed)
                clone["exposure_time"] = rawrace.exposure_of(opened, ended)
                out_shadow.append(clone)
    return out_ledger, out_clocks, out_shadow


def _t07_write_fixture_cell(plan, coupling, source_name, cell_name):
    """Write one deterministic fixture cell **directly under the quarantine**.

    The source run is a real pilot run at this plan's own configuration and a
    small trial count; the cell is that run's histories cloned to the plan's
    declared trial count under the plan's own 45-key manifest.  The five files
    are written straight into the quarantine and nowhere else — there is no
    production-root path at any moment — and the whole quarantine tree is
    removed by the caller's ``finally``.

    **Identity first, and one configuration.**  :func:`_t07_require_fixture_plan`
    runs before anything is opened or created, so a plan that is not this
    verifier's fixture plan is refused with no directory, no source run and no
    closure to clean up.  ``config_for`` is then called **once** and the single
    immutable snapshot drives both the source walk and the manifest written
    above the clone: an independent review's alternating plan answered that
    question differently on its two calls, so the cheap histories underneath
    and the manifest on top described two different experiments.
    """
    # **The validated record replaces the argument.**  Every ``plan.`` call
    # below — the name mapping, the coupling mapping, the configuration, the
    # window, the model and the blocking — is made on the freshly built fixture
    # plan this door returns, never on the object the caller handed in.
    plan = _t07_require_fixture_plan(plan)
    cell_name = plan.require_run_name(cell_name)
    if plan.coupling_for(cell_name) != coupling:
        raise ValueError(
            f"the plan writes {cell_name!r} at coupling "
            f"{plan.coupling_for(cell_name)!r} and this call names coupling "
            f"{coupling!r}; the name/coupling mapping is frozen inside the "
            f"plan digest and a cell written against the wrong one is a cell "
            f"the plan does not describe")
    source_name = _require_fixture_source_name(source_name, plan)
    root = xpr._quarantine_root()
    # One snapshot, taken once.  The source run is this configuration at a
    # small trial count; the manifest is this same configuration at the
    # declared one, and there is no second question to answer differently.
    config = plan.config_for(coupling)
    source_config = dataclasses.replace(
        config, trials=_T07_FIXTURE_SOURCE_TRIALS,
        shadow_trials=_T07_FIXTURE_SOURCE_TRIALS)
    root.mkdir(parents=True, exist_ok=True)
    results = os.open(str(PACKAGE_DIR / rawrun.RESULTS_DIRNAME),
                      os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        parent = os.open(xpr.QUARANTINE_DIRNAME,
                         os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                         dir_fd=results)
    finally:
        os.close(results)
    try:
        rawrun._write_scoped_run(source_config, source_name, parent,
                                 str(root / source_name), plan.model,
                                 plan.clock_block, plan.step_window)
    finally:
        os.close(parent)
    source, _, _ = xpr._read_quarantined(source_name)
    ledger, clocks, shadow = _t07_clone_rows(source, plan)

    manifest = rawrun.raw_manifest(config, plan.model)
    manifest_bytes = rawled.canonical_manifest_bytes(manifest)
    payloads = {
        "ledger": rawled.encode_table(rawled.LEDGER_COLUMNS, ledger),
        "clocks": rawled.encode_table(rawled.CLOCK_COLUMNS, clocks),
        "shadow": rawled.encode_table(rawled.SHADOW_COLUMNS, shadow),
    }
    counts = {"ledger": len(ledger), "clocks": len(clocks),
              "shadow": len(shadow)}
    marker = rawled.CloseMarker(
        rawled.LEDGER_SCHEMA_VERSION,
        tuple((name, counts[name], rawled.digest_bytes(payloads[name]))
              for name in rawled.TABLE_NAMES),
        rawled.digest_bytes(manifest_bytes))
    directory = root / cell_name
    directory.mkdir(parents=True, exist_ok=False)
    (directory / rawrun.RUN_FILENAMES["manifest"]).write_bytes(manifest_bytes)
    for name, payload in payloads.items():
        (directory / rawrun.RUN_FILENAMES[name]).write_bytes(payload)
    # Marker last, exactly as the writer orders it: a directory without one is
    # an unfinished run and this door reads no unfinished run.
    (directory / rawrun.RUN_FILENAMES["marker"]).write_bytes(
        rawled.canonical_marker_bytes(marker))
    shutil.rmtree(root / source_name, ignore_errors=True)
    return cell_name


def _t07_pilot_fixture(plan):
    """Build the whole deterministic fixture and return its ordered run names.

    Four cells, one per declared candidate coupling, each at the plan's own
    trial count with a hundred committed and a hundred unresolved trials — far
    above the frozen twenty-and-twenty minimum, so the count rule selects every
    cell and the selection is the full declared range.  Deterministic: the raw
    streams are counter-keyed, so the same plan writes the same bytes, and the
    clone is a pure reindexing of them.

    The identity door runs here as well as inside the per-cell writer, so a
    plan this helper may not write is refused before the loop starts and
    therefore before the quarantine root is created at all — and, as there, the
    record it returns replaces the argument, so the couplings iterated and the
    names written are the freshly built fixture plan's own.
    """
    plan = _t07_require_fixture_plan(plan)
    names = []
    for index, coupling in enumerate(plan.couplings):
        names.append(_t07_write_fixture_cell(
            plan, coupling, f"xpilot-t07-fixture-src-{index}",
            plan.run_name_for(coupling)))
    if tuple(names) != plan.run_names:
        raise AssertionError(f"the fixture wrote {names} and the plan freezes "
                             f"{list(plan.run_names)}")
    return tuple(names)


def _t07_extra_lines():
    """The range pilot as its own visible line, priced from the frozen plan.

    Not from a caller's trial count and cell count any more: the approved
    pilot's own cell, trial, clock, step and shadow numbers are what price it,
    so a pilot line and the plan it claims to price cannot disagree.
    """
    return (xpr.pilot_cost_from_plan(_t07_plan(), _t07_slowest(),
                                     _t07_resources().safety_factor),)


#: The proposed matrix's own maxima, for the schema-derived row bound.
_T07_MAX_TRIALS = 6346
_T07_MAX_CLOCKS = 64


def _t07_row_bound():
    """The schema-derived worst-case bytes per durable row, for the mix run."""
    matrix = _t07_matrix()
    return xpr.row_width_bound(_T07_MAX_TRIALS, _T07_MAX_CLOCKS,
                               matrix.steps_at(matrix.timestep))


def _t07_suite_maxima():
    """The most conservative serialization and memory the fixture family saw.

    An independent review found the storage total built on the *slowest timing*
    fixture's 91.16 bytes per row while another fixture in the same family
    measured 106.22, and the handoff summary quoting the larger number beside a
    total built on the smaller one.  Timing and serialization are different
    measurements; the cost model takes the slowest rate and the **widest** rows
    and the **largest** peak, each from whichever fixture produced it.
    """
    results = _t07_benchmarks().values()
    # The larger of the empirical maximum and the schema-derived bound, which
    # is the rule an independent review asked for: the small fixtures cannot
    # see four-digit trial identifiers, full float spellings or 64-winner list
    # cells, and the schema can.
    empirical = max(item.bytes_per_row for item in results)
    return (max(empirical, _t07_row_bound()["blended"]),
            max(max(item.fixed_bytes for item in results),
                _t07_row_bound()["header_bytes"]),
            max(item.peak_bytes for item in results))


def _t07_resources():
    per_row, fixed, peak = _t07_suite_maxima()
    return xpr.matrix_resource_estimate(
        _t07_matrix(), _t07_slowest(), safety_factor=1.5,
        bytes_per_row=per_row, fixed_bytes=fixed, peak_bytes=peak)


def _t07_synthetic_counts(firewall, pattern, offset=0):
    """Display-only count records, for prose and for refusal probes.

    They carry no provenance and the authoritative path never consults them:
    ``select_range`` and ``post_range_power`` take quarantined **run names** and
    re-open and re-count every one internally.  These exist so that a check can
    say what a pattern *would* mean without writing six runs to disk.

    The verifier takes the projection seal openly here, for the same reason it
    already takes ``analysis._SEAL``: the count-only **rule** and the rule's
    **binding to real quarantined runs** are two different subjects and are
    checked separately.  ``check_pilot_firewall`` proves the binding on an
    actual quarantined run — that a fabricated record cannot be built by an
    ordinary caller, that an unquarantined handle is refused, and that the
    closure digest is the whole five-file closure.  These fixtures then
    exercise the arithmetic of the rule over count patterns whose answers were
    written down first.
    """
    del firewall, offset
    return tuple(xpr.PilotCellCounts(coupling, 100, committed)
                 for coupling, committed in pattern)


def _t07_measured_arm_correlation():
    """What the recovery generator's between-arm latent correlation *is*.

    A Gaussian copula at per-cell correlation ``r`` with a requested between-arm
    correlation ``rho`` realizes ``r^2 * rho`` in the generated variables.  An
    independent review pointed out that the ensemble therefore does not
    exercise the declared adverse floor, and it is right — so the measurement
    is computed here, carried in the proposal beside the floor under its own
    name, and never presented as the floor.
    """
    recovery = _t07_recovery()
    return recovery.correlation ** 2 * recovery.arm_correlation


def _t07_proposal():
    disposition = _t07_disposition()
    return xpr.proposed_production_manifest(
        label="T07 proposed production manifest (dry run, unsigned)",
        fingerprint=xpr.source_fingerprint(), matrix=_t07_matrix(),
        target=_t07_target(), power=_t07_power(), disposition=disposition,
        search=_t07_search(), benchmark=_t07_slowest(),
        resources=_t07_resources(), firewall=_t07_firewall(),
        recovery=_t07_recovery(), plan=_t07_plan(),
        status_reason=(
            "checkpoint 1 has not been granted and the numerical disposition "
            "blocks: " + ", ".join(disposition.blockers)))


def _t07_kernel_benchmarks():
    """Time the **actual** ticket-04 validation kernels, not the raw writer.

    Two public entry points, each measured on its own unit with one discarded
    warmup and two timed repeats:

    * ``killed_diffusion.solve_survival`` — the stationary oracle itself, an
      implicit PDE solve, priced per **space-time cell** of its own grid; and
    * ``killed_diffusion.compare_refinement`` over the frozen moving-band
      dataset — the paired cluster bootstrap that dominates the audit's
      comparison work, priced per **resample-observation**.

    An independent review found the validation options costed with generic
    two-pass raw-writer work.  These are the algorithms, and their units are
    kept apart: nothing in this module divides a PDE cell by a bootstrap
    resample.
    """
    if "kernels" in _T07_CACHE:
        return _T07_CACHE["kernels"]
    fingerprint = xpr.source_fingerprint()
    geometry = kdf.BandGeometry(*_s3_band(), _S3_DIFFUSION, _S3_COUPLING,
                                _S3_DETUNING)
    positions = _s3_positions()
    oracle = xpr.benchmark_kernel(
        label="stationary oracle solve", kernel="oracle_cell",
        unit="oracle_cell", operations=_S3_SPACE * _S3_TIME,
        run=lambda: kdf.solve_survival(geometry, positions, _S3_HORIZON,
                                       _S3_SPACE, _S3_TIME),
        problem=(f"killed_diffusion.solve_survival on a {_S3_SPACE} x "
                 f"{_S3_TIME} implicit grid over {len(positions)} declared "
                 f"start positions to horizon {_S3_HORIZON}"),
        fingerprint=fingerprint)

    dataset = _audit_dataset()
    budgets = _audit_budgets("S3b moving-band audit, pooled reference budgets",
                             _AUDIT_TRIALS, ("pooled",))
    sampling = _audit_contract(_AUDIT_TRIALS).sampling
    observations = (sampling.resamples * _AUDIT_TRIALS
                    * len(dataset.samples) * len(_AUDIT_STRIDES))
    audit = xpr.benchmark_kernel(
        label="moving-band paired bootstrap", kernel="resample_observation",
        unit="resample_observation", operations=observations,
        run=lambda: kdf.compare_refinement(dataset, budgets, budgets.digest),
        problem=(f"killed_diffusion.compare_refinement over the frozen "
                 f"moving-band dataset: {sampling.resamples} resamples x "
                 f"{_AUDIT_TRIALS} clusters x {len(dataset.samples)} samples x "
                 f"{len(_AUDIT_STRIDES)} levels"),
        fingerprint=fingerprint)
    _T07_CACHE["kernels"] = (oracle, audit)
    return _T07_CACHE["kernels"]


#: The finite staged validation campaign.  Every stage is declared here, above
#: the code that prices it, and none of them is promised sufficient.
_T07_STAGES = (
    # (label, unit, attacks, kernel, timestep factor, sample factor, spatial
    #  refinement factor, depends_on)
    ("stationary probability, dt/16 at doubled space", "probability",
     "timestep_bias", "oracle_cell", 0.0625, 1.0, 4, ""),
    ("stationary probability, dt/64 at quadrupled space", "probability",
     "timestep_bias", "oracle_cell", 0.015625, 1.0, 16,
     "stationary probability, dt/16 at doubled space"),
    ("stationary probability, dt/256 at eightfold space", "probability",
     "timestep_bias", "oracle_cell", 0.00390625, 1.0, 64,
     "stationary probability, dt/64 at quadrupled space"),
    ("stationary time quantile, dt/256 at eightfold space", "time",
     "timestep_bias", "oracle_cell", 0.00390625, 1.0, 64,
     "stationary probability, dt/256 at eightfold space"),
    ("moving-band probability, 64x master trials", "probability",
     "sampling_error", "resample_observation", 1.0, 64.0, 64, ""),
    ("moving-band probability, dt/16 replay", "probability",
     "timestep_bias", "resample_observation", 0.0625, 1.0, 16,
     "moving-band probability, 64x master trials"),
    ("moving-band time quantile, 1024x master trials", "time",
     "sampling_error", "resample_observation", 1.0, 1024.0, 1024,
     "moving-band probability, 64x master trials"),
)


def _t07_campaign():
    """The staged campaign, priced from the actual kernel measurements."""
    if "campaign" in _T07_CACHE:
        return _T07_CACHE["campaign"]
    oracle, audit = _t07_kernel_benchmarks()
    budget = _t07_budget()
    stages = []
    for (label, unit, attacks, kernel, timestep, sample, spatial,
         depends) in _T07_STAGES:
        allowance = budget.allowance(unit)
        # ``operations`` is a *relative shape*, not a price: the stage's own
        # declared factors, and nothing multiplied by a measured rate.  There
        # is no code path in this module that turns it into seconds.
        operations = int(math.ceil(spatial * sample / timestep))
        stages.append(xpr.ValidationStage(
            label=label, unit=unit, attacks=attacks, kernel=kernel,
            operations=operations,
            candidate=(f"timestep x{timestep:g}, sample x{sample:g}, spatial "
                       f"x{spatial:g} relative to the ticket-04 ladder"),
            timestep_factor=timestep, sample_factor=sample,
            depends_on=depends,
            success_rule=(
                f"every {unit} row of this ladder must land, bias plus "
                f"{xpr.COVERAGE_SIGMA} standard errors, under the frozen "
                f"{unit} allowance {allowance:.6g} at the trial count the "
                f"matrix proposes"),
            no_result_rule=(
                "a stage that misses its target is a numerical_no_result: the "
                "budget is not widened, the allowance is not re-derived, and "
                "the moving-band verdict is not re-decided"),
            stop_rule=(
                "stop at the first stage whose own predecessor returned a "
                "numerical_no_result; a later stage never runs on an "
                "unresolved one.  There is no resource cap here because there "
                "is no measured cost to cap")))
    campaign = xpr.ValidationCampaign(
        label="T07 staged intended-configuration validation campaign",
        stages=tuple(stages), benchmarks=(oracle, audit),
        scaling_assumption=(
            "each stage is priced by multiplying its kernel's measured "
            "operation count linearly: an implicit PDE solve scales with its "
            "space-time cells and a cluster bootstrap with its "
            "resample-observations.  Both are stated assumptions about the "
            "kernels' own shapes and neither is an extrapolation across "
            "kernels; the two units are never divided by one another"),
        note=(
            "NO STAGE IS PROMISED SUFFICIENT, AND THIS CAMPAIGN CARRIES NO "
            "COST.  There is no estimate, no range, no lower bound and no "
            "upper bound: the two kernels that were timed omit the moving "
            "replay and the stationary endpoint generation, so nothing built "
            "on them would bound the work.  Each stage's operation count is a "
            "relative shape and is never multiplied by a rate.  Running the "
            "whole campaign might resolve the numerical block; nothing here "
            "shows that it would, and failure at any stage remains a "
            "numerical_no_result"))
    _T07_CACHE["campaign"] = campaign
    return campaign


def _t07_alternatives():
    """The two things John can choose between — **built by the module**.

    An independent review handed ``checkpoint_one_handoff`` a costed Option A
    whose ``supports`` string was ``"a physical scaling claim"``, using genuine
    components everywhere else, and it was accepted.  So the builders moved
    into ``experiments`` and the checkpoint derives them; this helper exists so
    that other checks and the prose guard can read the same records the
    checkpoint will build, and it takes them from the same public function.
    """
    return xpr.checkpoint_alternatives(
        _t07_matrix(), _t07_slowest(), _t07_disposition(),
        _t07_resources().safety_factor)


#: The label the checkpoint handoff is built under, in one place so the
#: authoritative rebuild and the record itself cannot disagree about it.
_T07_HANDOFF_LABEL = "T07 checkpoint-1 feasibility handoff"


def _t07_handoff_components():
    """The exact components ``checkpoint_one_handoff`` is given.

    Named once, because :func:`experiments._require_authoritative_checkpoint`
    has to be handed the *same* components in order to mean anything: a
    rebuild from a different set would answer a different question.
    """
    return dict(
        label=_T07_HANDOFF_LABEL,
        benchmarks=tuple(_t07_benchmarks().values()), target=_t07_target(),
        power=_t07_power(), recovery=_t07_recovery(),
        disposition=_t07_disposition(), search=_t07_search(),
        matrix=_t07_matrix(), resources=_t07_resources(),
        firewall=_t07_firewall(), proposal=_t07_proposal(),
        plan=_t07_plan())


def _t07_handoff():
    return xpr.checkpoint_one_handoff(**_t07_handoff_components())


@check("the experiments layer is versioned, unreachable from the raw graph, "
       "and refuses every value outside its closed vocabularies", covers=[110])
def check_experiments_isolation():
    """Orchestration may see the answer's shape; the event generator may not."""
    problems = []
    refused = _t07_refuser(problems)

    if "experiments" not in _RAW_FORBIDDEN_MODULES:
        problems.append("experiments is not in the raw graph's forbidden list")
    if not (PACKAGE_DIR / "experiments.py").exists():
        problems.append("experiments.py does not exist, so forbidding it "
                        "forbids nothing")
    for path in sorted(PACKAGE_DIR.glob("raw_*.py")):
        for node in ast.walk(ast.parse(path.read_text(encoding="utf-8"))):
            named = []
            if isinstance(node, ast.Import):
                named = [alias.name for alias in node.names]
            elif isinstance(node, ast.ImportFrom):
                named = [node.module or ""] + [alias.name
                                               for alias in node.names]
            if any(name and name.split(".")[-1] == "experiments"
                   and "raw_experiments" not in name for name in named):
                problems.append(f"{path.name} imports experiments")

    # ---- every closed vocabulary, pinned member for member -----------------
    # An independent review rebound ``FEASIBILITY_VERDICTS`` in a fresh process
    # with an extra ``review_rogue_verdict`` and this check still passed,
    # because it looked only for one bad spelling.  "Closed" is a claim about
    # the whole set, so the whole set is written out here and compared in
    # order; and each pin is exercised by adding and removing a member, so a
    # vocabulary the criterion names cannot be enforced by accident.
    pinned = {
        "PROPOSAL_STATUSES": ("checkpoint_blocked",),
        "FEASIBILITY_VERDICTS": ("feasible_matrix",
                                 "no_feasible_matrix_among_searched",
                                 "unresolved"),
        "BUDGET_VERDICTS": ("satisfied", "numerical_no_result", "unresolved"),
        "BUDGET_BLOCKERS": ("moving_band_numerical_no_result",
                            "endpoint_envelope_exceeds_allowance",
                            "audit_envelope_exceeds_allowance",
                            "no_evidence_at_intended_configuration",
                            "probability_window_empty",
                            "time_bounds_fail_at_every_trial_count",
                            "evidence_missing"),
        "POWER_STAGES": ("provisional_pre_pilot", "post_range_join"),
        "POWER_VERDICTS": ("powered", "no_powered_matrix"),
        "POST_RANGE_STATUSES": ("post_range_refused",
                                "post_range_no_powered_matrix",
                                "post_range_powered"),
        "SELECTION_REFUSALS": ("no_eligible_cells", "run_too_short",
                               "not_contiguous_enough"),
        "PILOT_ROLES": ("range_only",),
        "PILOT_PURPOSES": ("approved_production_pilot", "verifier_fixture"),
        "ALTERNATIVE_LABELS": ("intended_configuration_validation",
                               "narrowed_claim"),
        "SUPPORT_CLASSES": ("unpriced_no_claim",
                            "machinery_and_diagnostic_only"),
        "CONFIGURATION_LABELS": ("intended", "non_intended", "unmeasured"),
        "PERMITTED_PILOT_FIELDS": ("coupling", "trials", "committed",
                                   "survivors"),
        "TICKET_08_DERIVATION_STATUSES": ("not_started",),
        "TICKET_08_AUTHORIZATION_STATUSES": ("not_authorized",),
    }

    def vocabulary_problems(namespace):
        """Every pinned vocabulary in ``namespace`` that is not its pinned set."""
        found = []
        for name, expected in pinned.items():
            actual = tuple(namespace[name])
            if actual != expected:
                found.append(f"{name} is {list(actual)} and criterion 110 "
                             f"pins {list(expected)}")
        return found

    live = {name: getattr(xpr, name) for name in pinned}
    problems.extend(vocabulary_problems(live))
    # The negative controls, run against copies so the live module is never
    # mutated: an added member and a removed member must each be detected, for
    # every vocabulary the criterion names.
    for name in pinned:
        for label, altered in (
                ("an added", tuple(live[name]) + ("review_rogue_member",)),
                ("a removed", tuple(live[name])[:-1]),
                ("a reordered", tuple(reversed(live[name])))):
            if altered == tuple(live[name]):
                continue                 # a one-member set cannot be reordered
            if not vocabulary_problems({**live, name: altered}):
                problems.append(f"{label} member of {name} is not detected; "
                                f"the criterion calls that vocabulary closed "
                                f"and nothing pins it")
    if "no_feasible_matrix" in xpr.FEASIBILITY_VERDICTS:
        problems.append("an unqualified no_feasible_matrix verdict is back; "
                        "the evidence supports a statement about the options "
                        "actually searched")
    # And the criterion no longer claims a production gate this package does
    # not contain, so the text and the enforcement say the same thing.
    if "production gate" in ACCEPTANCE_CRITERIA[110]:
        problems.append("criterion 110 still names a production gate; there "
                        "is none in this package and nothing here can enforce "
                        "one")
    refused("a budget verdict outside BUDGET_VERDICTS", ValueError,
            lambda: xpr.BudgetDisposition("cleared", (), (), "a" * 64,
                                          "b" * 64, 0, True))
    refused("a blocker outside BUDGET_BLOCKERS", ValueError,
            lambda: xpr.BudgetDisposition("unresolved", ("looks_fine",), (),
                                          "a" * 64, "b" * 64, 0, True))
    refused("a non-finite number in a canonical record", ValueError,
            lambda: xpr.canonical_bytes({"x": float("nan")}))
    refused("an object a canonical record cannot hold", TypeError,
            lambda: xpr.canonical_bytes({"x": object()}))
    refused("a proposal built without the factory seal", TypeError,
            lambda: xpr.ProposedProductionManifest(_t07_proposal().fields))

    if cmpr.PRODUCTION_STATUS_SCHEMA <= rawled.MANIFEST_SCHEMA_VERSION:
        problems.append(f"ticket 06's production status schema "
                        f"{cmpr.PRODUCTION_STATUS_SCHEMA} no longer sits above "
                        f"the live manifest schema "
                        f"{rawled.MANIFEST_SCHEMA_VERSION}")
    if xpr.CONTENT_REVISION < 2:
        problems.append("the content revision was not bumped for this round")

    return Result("the experiments layer is versioned, unreachable from the "
                  "raw graph, and refuses every value outside its closed "
                  "vocabularies", not problems, float(len(problems)), 0.0,
                  (f"experiments.py is on the raw forbidden list and exists; "
                   f"no raw_*.py module names it; content revision "
                   f"{xpr.CONTENT_REVISION}; "
                   f"{len(xpr.PROPOSED_MANIFEST_KEYS)} declared proposal "
                   f"fields of which {len(xpr.DESIGN_DIGEST_KEYS)} are the "
                   f"measurement-free design freeze; "
                   f"{len(pinned)} closed vocabularies pinned member for "
                   f"member and each exercised by an added, removed and "
                   f"reordered member; "
                   f"{len(xpr.BUDGET_BLOCKERS)} closed blockers and exactly "
                   f"one proposal status, which is "
                   f"{xpr.PROPOSAL_STATUSES[0]!r}; the proposal type is "
                   f"factory-only and refuses a caller-built record; ticket "
                   f"06's status schema {cmpr.PRODUCTION_STATUS_SCHEMA} still "
                   f"sits above the live manifest schema "
                   f"{rawled.MANIFEST_SCHEMA_VERSION}")
                  if not problems else "; ".join(problems[:6]), covers=(110,))


@check("throughput is measured at the intended clock count and finest "
       "timestep with a warmup and repeated timings, the work model separates "
       "the shadow rewalk, and no noise cube is materialized", covers=[111])
def check_feasibility_benchmark():
    """The benchmark measures the thing production would run, at its resolution.

    An independent review found the fixtures at sixteen clocks and coarse
    timesteps while the matrix proposed sixty-four clocks at ``1.953125e-3``,
    with no warmup on two of three fixtures and one timed repeat each.  All
    three are closed here:

    * the ``intended`` fixture runs **64 clocks at the intended timestep** and
      the proposed blocking, its pulse shortened so the workload stays bounded
      while the clock count, the step size, the per-step branching and the
      tongue crossing structure are the proposed ones;
    * every fixture has a discarded warmup and **two** timed repeats, both
      recorded; and
    * the work model is per **walked** clock-step — two censoring passes plus
      the shadow rewalk — so a matrix priced with this rate computes its own
      walked steps the same way instead of multiplying a shadow-bearing rate by
      a shadow factor again.

    The rates of fixtures four times apart in clock count and twenty-five times
    apart in timestep must agree within a declared band.  That is the
    independent spot check, run here rather than quoted.
    """
    problems = []
    refused = _t07_refuser(problems)
    results = _t07_benchmarks()
    intended = results["t07-bench-intended"]
    base = results["t07-bench-base"]
    trials4x = results["t07-bench-trials4x"]
    steps4x = results["t07-bench-steps4x"]
    shadow = results["t07-bench-shadow"]

    matrix = _t07_matrix()
    if intended.clocks != matrix.clocks:
        problems.append(f"the intended fixture runs {intended.clocks} clocks "
                        f"against the matrix's {matrix.clocks}")
    if intended.steps * _T07_TIMESTEP <= 0.0 or \
            abs(intended.steps * _T07_TIMESTEP - 0.5) > 1e-9:
        problems.append("the intended fixture is not at the intended timestep")
    if intended.truncating:
        problems.append("the intended fixture committed, so its first pass "
                        "truncated and its rate is not the honest one")
    for result in results.values():
        if len(result.repeat_seconds) < 2:
            problems.append(f"{result.fixture_label} has one timed repeat")
        if not result.traced:
            problems.append(f"{result.fixture_label} was not traced")
        if result.walked_clock_steps != (
                xpr.RACE_PASSES * result.nominal_clock_steps
                + result.shadow_clock_steps):
            problems.append(f"{result.fixture_label}'s work model does not add "
                            f"up")

    if trials4x.nominal_clock_steps != 4 * base.nominal_clock_steps:
        problems.append("the trials fixture is not a clean quadrupling")
    if steps4x.nominal_clock_steps != 4 * base.nominal_clock_steps:
        problems.append("the steps fixture is not a clean quadrupling")
    growth = {"trials": trials4x.peak_bytes / base.peak_bytes,
              "steps": steps4x.peak_bytes / base.peak_bytes}
    for label, value in growth.items():
        if value > _T07_PEAK_GROWTH_BOUND:
            problems.append(
                f"quadrupling the {label} grew the traced peak by {value:.2f}, "
                f"past the {_T07_PEAK_GROWTH_BOUND:.2f} bound; a materialized "
                f"noise cube would have grown by four")

    # The spot check: rates across the fixture family agree.
    rates = [item.clock_steps_per_second for item in results.values()]
    spread = max(rates) / min(rates)
    if spread > _T07_RATE_AGREEMENT:
        problems.append(f"the walked-clock-step rates span a factor "
                        f"{spread:.2f}, past the {_T07_RATE_AGREEMENT} band; "
                        f"the work model is not describing the work")

    # The shadow rewalk is measured, not assumed.  Its incremental cost per
    # walked clock-step must sit inside the same band as the base rate.
    extra_steps = shadow.walked_clock_steps - base.walked_clock_steps
    extra_time = shadow.wall_seconds - base.wall_seconds
    shadow_rate = extra_steps / extra_time if extra_time > 0 else 0.0
    if shadow_rate <= 0.0:
        problems.append("the shadow fixture was not slower than the base one, "
                        "so the rewalk cost could not be measured")
    elif not (1.0 / _T07_RATE_AGREEMENT
              <= shadow_rate / base.clock_steps_per_second
              <= _T07_RATE_AGREEMENT):
        problems.append(f"the incremental shadow rewalk runs at "
                        f"{shadow_rate:.0f} walked clock-steps/s against the "
                        f"base fixture's {base.clock_steps_per_second:.0f}; "
                        f"charging it at the base rate is then wrong")

    root = PACKAGE_DIR / rawrun.RESULTS_DIRNAME
    if root.exists():
        leftovers = sorted(entry.name for entry in root.iterdir()
                           if entry.name.startswith("t07-bench-"))
        if leftovers:
            problems.append(f"the benchmark left {leftovers} behind")

    refused("a fixture whose config is not a RawEventConfig", TypeError,
            lambda: xpr.BenchmarkFixture("probe", object(), "full", 1, 1, 1, 2))
    refused("a fixture with no warmup", ValueError,
            lambda: xpr.BenchmarkFixture("probe", _t07_probe_config(), "full",
                                         1, 1, 0, 2))
    refused("a fixture with a single timed repeat", ValueError,
            lambda: xpr.BenchmarkFixture("probe", _t07_probe_config(), "full",
                                         1, 1, 1, 1))
    refused("a result with one timed repeat", ValueError,
            lambda: xpr.BenchmarkResult(
                "probe", "a" * 64, "b" * 64, "p", 10, 10, 30, 2, 1, 1, 1, 10,
                (1.0,), 100, 200, 100, 10, 0))
    refused("a result whose work model does not add up", ValueError,
            lambda: xpr.BenchmarkResult(
                "probe", "a" * 64, "b" * 64, "p", 10, 10, 31, 2, 1, 1, 1, 10,
                (1.0, 1.1), 100, 200, 100, 10, 0))

    slowest = _t07_slowest()
    projected = (_t07_resources().clock_steps * 8.0 / xpr.RACE_PASSES
                 / max(item.peak_bytes for item in results.values()))
    return Result("throughput is measured at the intended clock count and "
                  "finest timestep with a warmup and repeated timings, the "
                  "work model separates the shadow rewalk, and no noise cube "
                  "is materialized", not problems,
                  max(max(growth.values()), spread / _T07_RATE_AGREEMENT
                      * _T07_PEAK_GROWTH_BOUND), _T07_PEAK_GROWTH_BOUND,
                  (f"{len(results)} fixtures through raw_runner.write_raw_run "
                   f"at clock_block 16 and step_window 64, each with one "
                   f"discarded warmup and two traced timed repeats.  The "
                   f"intended fixture is {intended.clocks} clocks at timestep "
                   f"{_T07_TIMESTEP} over {intended.steps} steps, commits "
                   f"nothing so its first pass does not truncate, and runs at "
                   f"{intended.clock_steps_per_second:.0f} walked "
                   f"clock-steps/s over repeats "
                   f"{[round(value, 3) for value in intended.repeat_seconds]}. "
                   f"Across the family the rates span a factor {spread:.2f} "
                   f"against a {_T07_RATE_AGREEMENT} band, and the "
                   f"incremental shadow rewalk measures "
                   f"{shadow_rate:.0f} clock-steps/s against the base "
                   f"{base.clock_steps_per_second:.0f} — so the shadow is "
                   f"charged once, at a measured rate, rather than as a "
                   f"multiplier on a rate that already contained it.  Costing "
                   f"uses the slowest, {slowest.fixture_label!r} at "
                   f"{slowest.clock_steps_per_second:.0f}/s.  Traced peak "
                   f"{base.peak_bytes / 1024:.0f} kB rising "
                   f"{growth['trials']:.2f}x at four times the trials and "
                   f"{growth['steps']:.2f}x at four times the steps, against a "
                   f"cube that quadruples both times; at the proposed matrix "
                   f"the unstreamed cube would be {projected:.0f} times the "
                   f"largest peak measured here")
                  if not problems else "; ".join(problems[:6]), covers=(111,))


def _t07_probe_config():
    """A minimal valid raw configuration, for the refusal probes."""
    return _t07_config(2, 0.5, 4.0, 1, 1, namespace="t07-probe")


@check("every arm is sized from its own declared envelope, the recovery "
       "ensemble counts only valid fits under a non-monotone dependence, and "
       "the contrast is sized against adverse covariance", covers=[112])
def check_power_recovery():
    """The sizing arithmetic, checked against a simulation of itself.

    An independent review's three findings are closed here.

    1. **Arm-aware sizing.**  Every arm declares a conservative probability
       envelope and is sized from the least informative point in it.  The
       central control is one clock and less informative, so it needs more
       trials; the full and width-only arms pair and therefore share a count.
       An earlier revision sized one curve and applied it to all three.
    2. **Valid fits only, under real dependence.**  The recovery ensemble draws
       its shared master-trial latent from the package's own counter-keyed
       physical stream and combines it with a per-cell component at a declared
       correlation below one, so realizations are **not** monotone across
       coupling.  Refused fits are excluded from every statistic rather than
       averaged into it.
    3. **Adverse covariance.**  The contrast is sized at a declared negative
       full-minus-control correlation, and the ensemble measures the contrast's
       own spread so the declared floor can be checked against it.  The claim
       that pairing "can only reduce" the contrast variance is gone.

    The post-range join is exercised too: a selection built from count
    summaries alone re-sizes the design, and a selection that does not belong
    to those counts is refused.
    """
    problems = []
    refused = _t07_refuser(problems)
    recovery = _t07_recovery()
    target = _t07_target()
    power = _t07_power()

    bias = abs(recovery.independent_mean - _T07_EXPONENT)
    allowed = 4.0 * recovery.independent_stdev / math.sqrt(
        recovery.independent_valid)
    if bias > allowed:
        problems.append(f"the independent ensemble recovered "
                        f"{recovery.independent_mean:.4f} against a declared "
                        f"{_T07_EXPONENT}, a bias of {bias:.4f} past the "
                        f"{allowed:.4f} Monte Carlo allowance")
    ratio = recovery.independent_stdev / recovery.predicted_stdev
    if not 0.80 <= ratio <= 1.20:
        problems.append(f"the closed-form design standard error "
                        f"{recovery.predicted_stdev:.5f} and the measured "
                        f"independent spread {recovery.independent_stdev:.5f} "
                        f"differ by a factor {ratio:.3f}")
    if recovery.inflation > target.pairing_inflation:
        problems.append(f"the measured pairing inflation "
                        f"{recovery.inflation:.4f} exceeds the declared "
                        f"{target.pairing_inflation:.4f}")
    declared_contrast = 2.0 * (1.0 - target.contrast_covariance_floor) / 2.0
    if recovery.contrast_inflation > declared_contrast:
        problems.append(
            f"the measured contrast variance inflation "
            f"{recovery.contrast_inflation:.4f} exceeds the declared adverse "
            f"floor's {declared_contrast:.4f}; the contrast is sized from a "
            f"covariance the design can beat")
    if recovery.correlation >= 1.0:
        problems.append("the recovery ensemble is perfectly monotone again")
    if min(recovery.paired_valid, recovery.independent_valid,
           recovery.contrast_valid) >= recovery.replicates:
        # Not a defect, but worth knowing: with no refused fits the
        # valid-only rule is untested on this fixture.
        pass

    # Arm awareness: the one-clock control must not carry the full arm's count.
    trials = power.arm_trials
    if trials["full"] != trials["width_only_control"]:
        problems.append("the two paired arms carry different trial counts")
    if trials["central_control"] == trials["full"]:
        problems.append("the central control was sized from the full arm's "
                        "envelope rather than its own")
    if power.driving_arm != "central_control":
        problems.append(f"the driving arm is {power.driving_arm!r}; the "
                        f"least informative envelope should drive")
    if power.trials_per_cell < power.analytic_independent_trials:
        problems.append("pairing and the conservative factor reduced the count")

    # The post-range join, from count summaries only.
    firewall = _t07_firewall()
    counts = _t07_synthetic_counts(firewall,
                                   ((0.5, 30), (0.66, 45), (0.87, 55),
                                    (1.15, 65), (1.52, 75), (2.0, 99)))
    try:
        api_plan = _t07_api_plan()
        names = _t07_api_quarantined()
        selection = xpr.select_range(api_plan, _t07_api_firewall(), names)
        # Whether these small fixtures happen to clear the count rule is not
        # the point; that the authoritative path read them off disk, under the
        # frozen plan, is.
        joined = (xpr.post_range_power(target, api_plan, _t07_api_firewall(),
                                       names)
                  if selection.selected else None)
        forged = _t07_synthetic_counts(firewall, ((0.4, 30), (0.6, 45),
                                                  (0.9, 55), (1.3, 65),
                                                  (1.8, 75), (2.4, 85)))
        preview = xpr.preview_range(firewall, forged)
        if type(preview) is type(selection):
            problems.append("a display preview and an authoritative selection "
                            "are the same type, so a preview could enter an "
                            "authoritative door")
        if hasattr(preview, "closure_digests"):
            problems.append("a display preview carries closure digests")
    finally:
        _t07_drop_quarantine()
        for index in range(6):
            shutil.rmtree(
                rawrun.raw_results_directory(f"xpilot-api-cell-{index}"),
                ignore_errors=True)
    if joined is not None and joined.stage != "post_range_join":
        problems.append("the join did not produce a post-range stage")
    if not power.is_provisional:
        problems.append("the pre-pilot estimate is not labelled provisional")
    if joined is not None and joined.is_provisional:
        problems.append("the joined estimate is still labelled provisional")
    refused("a post-range join over caller-built counts", TypeError,
            lambda: xpr.post_range_power(target, _t07_api_plan(),
                                         _t07_api_firewall(), counts))
    refused("a post-range join over no quarantined run", ValueError,
            lambda: xpr.post_range_power(target, _t07_api_plan(),
                                         _t07_api_firewall(), ()))
    refused("a post-range join whose plan and firewall disagree", ValueError,
            lambda: xpr.post_range_power(target, _t07_api_plan(), firewall,
                                         ("xpilot-api-cell-0",)))

    refused("an arm envelope whose information factor exceeds one", ValueError,
            lambda: xpr.ArmEnvelope("full", 1, 0.1, 0.9, 1.5, 0.0))
    refused("a target without the mandatory negative controls", ValueError,
            lambda: xpr.SamplingTarget(
                0.25, 0.5, 0.5, 2.0, 6, 1.0, 1.0, "master_trial",
                (xpr.ArmEnvelope("full", 1, 0.1, 0.9, 1.0, 0.0),), 0.05, 100))
    refused("a positive contrast covariance floor", ValueError,
            lambda: xpr.SamplingTarget(
                0.25, 0.5, 0.5, 2.0, 6, 1.0, 1.0, "master_trial",
                _t07_envelopes(), 0.05, 100,
                contrast_covariance_floor=0.5))

    return Result("every arm is sized from its own declared envelope, the "
                  "recovery ensemble counts only valid fits under a "
                  "non-monotone dependence, and the contrast is sized against "
                  "adverse covariance", not problems, abs(ratio - 1.0), 0.20,
                  (f"{recovery.replicates} replicates per ensemble at "
                   f"{recovery.trials_per_cell} trials in each of "
                   f"{target.cells} cells, exponent {_T07_EXPONENT} declared "
                   f"before the table, shared latent from the package's keyed "
                   f"physical stream at correlation "
                   f"{recovery.correlation} so realizations are not monotone "
                   f"across coupling: independent mean "
                   f"{recovery.independent_mean:.4f} sd "
                   f"{recovery.independent_stdev:.5f} against a closed-form "
                   f"{recovery.predicted_stdev:.5f} (ratio {ratio:.3f}) over "
                   f"{recovery.independent_valid}/{recovery.replicates} valid "
                   f"fits; paired sd {recovery.paired_stdev:.5f}, inflation "
                   f"{recovery.inflation:.3f} against the declared "
                   f"{target.pairing_inflation}; contrast sd "
                   f"{recovery.contrast_stdev:.5f} at arm correlation "
                   f"{recovery.arm_correlation}, inflation "
                   f"{recovery.contrast_inflation:.3f} against the declared "
                   f"{declared_contrast:.3f}.  Arm-aware sizing gives "
                   f"{ {k: v for k, v in sorted(trials.items())} }, driven by "
                   f"{power.driving_arm!r}; the analytic independent-cell "
                   f"requirement alone is {power.analytic_independent_trials}. "
                   f"The post-range join re-sizes from a count-only selection "
                   f"and refuses a selection that did not come from those "
                   f"counts")
                  if not problems else "; ".join(problems[:6]), covers=(112,))


@check("the numerical budget uses its own frozen coverage sigma, carries every "
       "authoritative evidence row with its unit, and reports a probability "
       "window and a time verdict separately", covers=[113])
def check_numerical_budget():
    """The gate this ticket exists to apply, and the answer it gives.

    Three of an independent review's findings are closed here:

    * ``coverage_sigma`` is read **from the budget**, so two budgets differing
      only in coverage no longer produce identical rows;
    * every authoritative ticket-04 row is carried, not one maximum per unit
      selected by absolute point error; and
    * the probability window and the time verdict are reported separately,
      because a time-unit failure fails at every trial count and folding it
      into a scalar "admissible n" hides that.
    """
    problems = []
    refused = _t07_refuser(problems)
    evidence, s3, pooled = _t07_evidence()
    budget = _t07_budget()
    disposition = _t07_disposition()
    power = _t07_power()

    if pooled.verdict != "numerical_no_result":
        problems.append(f"the pooled moving-band ladder now reports "
                        f"{pooled.verdict!r}")
    if "numerical_no_result" not in rawrun.MOVING_BAND_STATUS:
        problems.append("raw_runner.MOVING_BAND_STATUS no longer records a "
                        "numerical no-result")
    if disposition.verdict != "numerical_no_result":
        problems.append(f"the disposition is {disposition.verdict!r}")
    for blocker in ("moving_band_numerical_no_result",
                    "endpoint_envelope_exceeds_allowance",
                    "no_evidence_at_intended_configuration",
                    "probability_window_empty",
                    "time_bounds_fail_at_every_trial_count"):
        if blocker not in disposition.blockers:
            problems.append(f"{blocker} is absent from "
                            f"{list(disposition.blockers)}")
    if disposition.time_admissible:
        problems.append("the time rows are reported as admissible")
    if disposition.admissible_trials != 0:
        problems.append(f"the overall admissible count is "
                        f"{disposition.admissible_trials} while a time row "
                        f"fails; a time failure fails at every n")
    if disposition.probability_admissible_trials >= power.trials_per_cell:
        problems.append("the probability window is not empty")
    if len(disposition.rows) != len(evidence):
        problems.append("the disposition dropped an evidence row")
    if len(evidence) < 12:
        problems.append(f"only {len(evidence)} authoritative rows were "
                        f"supplied; ticket 04's two ladders carry more than "
                        f"that at their finest levels")

    # The sigma is authoritative: a budget with a different one moves the rows.
    wide = xpr.NumericalBudget(budget.label, budget.allowed_fraction, 9.0,
                               budget.probability_half_width,
                               budget.time_half_width, budget.trials_per_cell,
                               budget.reference_probability,
                               budget.intended_timestep)
    if wide.digest == budget.digest:
        problems.append("two budgets with different sigmas share a digest")
    widened = xpr.numerical_disposition(wide, evidence)
    if widened.rows == disposition.rows:
        problems.append("changing the frozen coverage sigma left every "
                        "evidence row identical; the sigma is not being used")

    if abs(budget.allowance("probability")
           - 0.25 * budget.probability_half_width) > 1e-15:
        problems.append("the probability allowance is not a quarter of the "
                        "planned half-width")
    if abs(budget.allowance("time") - (0.25 * budget.time_half_width
                                       + _T07_TIMESTEP)) > 1e-15:
        problems.append("the time allowance is not a quarter plus one step")
    for item in evidence:
        expected = abs(item.measured) + budget.coverage_sigma \
            * item.standard_error
        if abs(item.bound_at(budget.coverage_sigma) - expected) > 1e-15:
            problems.append(f"{item.observable}'s bound is not "
                            f"|measured| + sigma * standard error")

    # Bias and sampling error scale separately.
    probe = xpr.NumericalEvidence("stationary_oracle", "survival",
                                  "probability", "x", 0.01, 0.04, 0.01, 100,
                                  "pass", "non_intended", "probe")
    if abs(probe.projected_bound(2.0, 1.0, 100.0)
           - (0.04 + 2.0 * 0.001)) > 1e-15:
        problems.append("enlarging the sample moved the bias")
    if abs(probe.projected_bound(2.0, 0.25, 1.0)
           - (0.02 + 2.0 * 0.01)) > 1e-15:
        problems.append("refining the timestep moved the sampling error")

    refused("a disposition claiming satisfied while carrying blockers",
            ValueError,
            lambda: xpr.BudgetDisposition("satisfied",
                                          ("probability_window_empty",), (),
                                          "a" * 64, "b" * 64, 0, True))
    refused("evidence with a verdict outside the oracle's vocabulary",
            ValueError,
            lambda: xpr.NumericalEvidence("stationary_oracle", "survival",
                                          "probability", "x", 0.01, 0.0, 0.0,
                                          1, "looks_ok", "intended", "cfg"))
    refused("evidence at an undeclared configuration", ValueError,
            lambda: xpr.NumericalEvidence("stationary_oracle", "survival",
                                          "probability", "x", 0.01, 0.0, 0.0,
                                          1, "pass", "probably", "cfg"))

    empty = xpr.numerical_disposition(budget, ())
    if empty.verdict != "unresolved" or \
            empty.blockers != ("evidence_missing",):
        problems.append(f"an empty evidence set produced {empty.verdict!r}")
    tiny = xpr.NumericalEvidence(
        "stationary_oracle", "survival", "probability", "x=0.0",
        _T07_TIMESTEP, budget.allowance("probability") / 10.0, 0.0, 1000,
        "pass", "intended", "the intended production configuration")
    passing = xpr.numerical_disposition(budget, (tiny,))
    if passing.verdict != "satisfied" or passing.blockers:
        problems.append(f"evidence inside the allowance at the intended "
                        f"configuration still blocked: {passing.verdict!r}")

    worst_probability = disposition.limiting("probability")
    worst_time = disposition.limiting("time")
    return Result("the numerical budget uses its own frozen coverage sigma, "
                  "carries every authoritative evidence row with its unit, and "
                  "reports a probability window and a time verdict separately",
                  not problems,
                  float(disposition.probability_admissible_trials),
                  float(power.trials_per_cell),
                  (f"{len(evidence)} authoritative rows from ticket 04's two "
                   f"ladders at their finest levels, every one carried and "
                   f"judged.  Planned per-cell probability half-width "
                   f"{budget.probability_half_width:.5f} at "
                   f"{budget.trials_per_cell} trials gives a "
                   f"{budget.allowance('probability'):.5f} allowance; the "
                   f"limiting probability row is {worst_probability[1]!r} at "
                   f"{worst_probability[4]:.5f}, capping the trial count at "
                   f"{disposition.probability_admissible_trials} against the "
                   f"{power.trials_per_cell} the target needs.  The limiting "
                   f"time row is {worst_time[1]!r} at {worst_time[4]:.5f} "
                   f"against a {worst_time[5]:.5f} allowance and **fails at "
                   f"every trial count**, so the overall admissible count is "
                   f"{disposition.admissible_trials} rather than the "
                   f"probability scalar.  S3 verdict {s3.verdict!r}, S3b "
                   f"pooled {pooled.verdict!r} carried through unchanged; "
                   f"disposition {disposition.verdict!r} with "
                   f"{list(disposition.blockers)}.  Raising the frozen sigma "
                   f"to 9 moves every row, so the frozen value is the one in "
                   f"use; bias and sampling error scale by their own levers; "
                   f"and evidence inside the allowance at the intended "
                   f"configuration still satisfies the same rule")
                  if not problems else "; ".join(problems[:6]), covers=(113,))


@check("the feasibility search is finite, declared and reported row by row, "
       "and its verdict names the options actually examined", covers=[119])
def check_feasibility_search():
    """What has been ruled out, and what has merely not been tried.

    An independent review's judgement, implemented: the evidence supports "no
    feasible matrix **among the options searched**", not an unqualified
    impossibility, and a claim about all timesteps and all samples needs a
    search or a bound.  So a finite declared option set is enumerated — coarser
    is refused, refinement and enlargement act on their own terms, and every
    row is reported with the factor by which it misses.

    The search is also shown to *work*: an option generous enough to fit, at
    the intended configuration, returns ``feasible_matrix``, and the same
    option on transferred evidence returns ``unresolved`` rather than
    ``feasible_matrix``.  Without those two the verdict could be a constant.
    """
    problems = []
    refused = _t07_refuser(problems)
    evidence, _, _ = _t07_evidence()
    budget = _t07_budget()
    search = _t07_search()

    if search.verdict != "no_feasible_matrix_among_searched":
        problems.append(f"the search reports {search.verdict!r}")
    if search.searched != len(_T07_OPTIONS):
        problems.append("the search did not examine every declared option")
    for row in search.rows:
        if row[6]:
            problems.append(f"option {row[0]!r} fits, so the verdict cannot be "
                            f"no_feasible_matrix_among_searched")
    proposed = search.row("as proposed")
    if proposed[5] <= 1.0:
        problems.append("the proposed option is reported as fitting")

    # The two positive controls.
    generous = xpr.NumericalEvidence(
        "stationary_oracle", "survival", "probability", "x", _T07_TIMESTEP,
        1e-6, 1e-7, 1000, "pass", "intended", "probe")
    ok_intended = xpr.search_feasible_options(
        budget, (generous,),
        (xpr.FeasibilityOption("generous", 1.0, 1.0, 100, "intended"),))
    if ok_intended.verdict != "feasible_matrix":
        problems.append(f"a fitting option at the intended configuration gave "
                        f"{ok_intended.verdict!r}")
    transferred = xpr.NumericalEvidence(
        "stationary_oracle", "survival", "probability", "x", _T07_TIMESTEP,
        1e-6, 1e-7, 1000, "pass", "non_intended", "probe")
    ok_transferred = xpr.search_feasible_options(
        budget, (transferred,),
        (xpr.FeasibilityOption("generous", 1.0, 1.0, 100, "non_intended"),))
    if ok_transferred.verdict != "unresolved":
        problems.append(f"a fitting option on transferred evidence gave "
                        f"{ok_transferred.verdict!r} rather than unresolved")

    refused("an option proposing a coarser timestep", ValueError,
            lambda: xpr.FeasibilityOption("coarser", 2.0, 1.0, 10,
                                          "non_intended"))
    refused("an option throwing validation data away", ValueError,
            lambda: xpr.FeasibilityOption("smaller", 1.0, 0.5, 10,
                                          "non_intended"))
    refused("a search over no options", ValueError,
            lambda: xpr.search_feasible_options(budget, evidence, ()))
    refused("a search over no evidence", ValueError,
            lambda: xpr.search_feasible_options(budget, (), _t07_options()))

    worst = min(row[5] for row in search.rows)
    best = min(search.rows, key=lambda row: row[5])
    return Result("the feasibility search is finite, declared and reported row "
                  "by row, and its verdict names the options actually "
                  "examined", not problems, worst, 1.0,
                  (f"{search.searched} declared options — the proposal as it "
                   f"stands, four refinements down to a sixteenth of the "
                   f"timestep, sample enlargements to 1024x, three reduced "
                   f"trial counts, their combinations, and one option that "
                   f"additionally measures at the intended configuration — "
                   f"each projected with bias and sampling error scaled by "
                   f"their own levers.  None fits: the closest is "
                   f"{best[0]!r} at {best[5]:.2f} times its allowance.  The "
                   f"verdict is therefore {search.verdict!r} and names this "
                   f"set, not every conceivable design.  A generous option at "
                   f"the intended configuration returns feasible_matrix and "
                   f"the same option on transferred evidence returns "
                   f"unresolved, so the verdict reads its input")
                  if not problems else "; ".join(problems[:6]), covers=(119,))


@check("the proposed matrix names its refinement cells, arm and grids exactly, "
       "and its cost is a checkable sum of named line items", covers=[114])
def check_primary_matrix():
    """A finite matrix, an exact execution graph, and an auditable total.

    An independent review found "2 of 6 cells, 1 of 3 arms" leaving the choice
    to be made after data are opened, the central control's one-clock grid
    absent from the manifest, a shadow fraction taken on a grand total rather
    than per run, and a shadow multiplier applied to a rate whose benchmark
    already carried a shadow.  All four are closed:

    * ``refinement_couplings`` and ``refinement_arm`` are exact identities;
    * ``arm_clocks`` carries the arm-specific grid, and the central control is
      required to be exactly one clock;
    * every line rounds its shadow **per run**; and
    * the cost model computes walked clock-steps itself, so the shadow is
      charged once against a rate measured in the same unit.

    The arithmetic is recomputed here, independently of the module.
    """
    problems = []
    refused = _t07_refuser(problems)
    matrix = _t07_matrix()
    resources = _t07_resources()
    slowest = _t07_slowest()
    power = _t07_power()

    if not matrix.meets_minimum_cells:
        problems.append(f"only {matrix.eligible_at_weakest} clocks are "
                        f"eligible at the weakest coupling")
    if matrix.clocks_of("central_control") != 1:
        problems.append("the central control is not one clock")
    if len(matrix.refinement_couplings) >= len(matrix.couplings):
        problems.append("the ladder refines every cell")
    if dict(matrix.arm_trials) != power.arm_trials:
        problems.append("the matrix does not carry the sized per-arm counts")

    # The execution ledger, recomputed from first principles here.
    steps = matrix.steps_at(matrix.timestep)
    physical = shadow = rows = 0
    clock_steps = 0.0
    for name in matrix.arms:
        trials = matrix.trials_of(name)
        clocks = matrix.clocks_of(name)
        per_run_shadow = int(math.ceil(trials * matrix.shadow_fraction))
        runs = len(matrix.couplings)
        physical += runs * trials
        shadow += runs * per_run_shadow
        rows += runs * (trials + trials * clocks + per_run_shadow * clocks)
        clock_steps += runs * (xpr.RACE_PASSES * trials * clocks * steps
                               + per_run_shadow * clocks * steps)
    for timestep in matrix.timestep_ladder[1:]:
        trials = matrix.refinement_trials_per_cell
        clocks = matrix.clocks_of(matrix.refinement_arm)
        finer = matrix.steps_at(timestep)
        per_run_shadow = int(math.ceil(trials * matrix.shadow_fraction))
        runs = len(matrix.refinement_couplings)
        physical += runs * trials
        shadow += runs * per_run_shadow
        rows += runs * (trials + trials * clocks + per_run_shadow * clocks)
        clock_steps += runs * (xpr.RACE_PASSES * trials * clocks * finer
                               + per_run_shadow * clocks * finer)
    if resources.physical_trials != physical:
        problems.append(f"the estimate reports {resources.physical_trials} "
                        f"physical trial executions against an independently "
                        f"recomputed {physical}")
    if resources.shadow_rewalks != shadow:
        problems.append(f"the estimate reports {resources.shadow_rewalks} "
                        f"shadow rewalks against {shadow}")
    if abs(resources.rows - rows) > 0.5:
        problems.append(f"the estimate reports {resources.rows} durable rows "
                        f"against {rows}")
    if abs(resources.clock_steps - clock_steps) > 1e-6 * clock_steps:
        problems.append(f"the estimate reports {resources.clock_steps:.6g} "
                        f"walked clock-steps against {clock_steps:.6g}")
    if abs(resources.wall_seconds
           - clock_steps / slowest.clock_steps_per_second * 1.5) > \
            1e-6 * resources.wall_seconds:
        problems.append("the wall-time estimate is not the walked clock-steps "
                        "divided by the measured rate times the safety factor")
    per_row, fixed_bytes, peak_bytes = _t07_suite_maxima()
    if per_row < slowest.bytes_per_row:
        problems.append("the conservative row coefficient is below the "
                        "timing fixture's own")
    if resources.peak_bytes != peak_bytes:
        problems.append("the estimate does not carry the largest measured peak")
    if abs(resources.storage_bytes
           - (rows * per_row + resources.runs * fixed_bytes)) > 1.0:
        problems.append("the storage estimate does not separate fixed per-run "
                        "overhead from row-proportional bytes")

    # The pilot is a separate line, never inside the matrix total.
    pilot = xpr.pilot_cost_line(matrix, slowest, 200, 8, 1.5,
                                _t07_suite_maxima()[0])
    if any(item.name == pilot.name for item in resources.lines):
        problems.append("the pilot is inside the production total")

    refused("a matrix whose central control is not one clock", ValueError,
            lambda: _t07_matrix_with(arm_clocks=(("full", 64),
                                                 ("central_control", 2),
                                                 ("width_only_control", 64))))
    refused("a matrix refining a coupling it does not run", ValueError,
            lambda: _t07_matrix_with(refinement_couplings=(0.31, 0.42)))
    refused("a matrix refining every cell", ValueError,
            lambda: _t07_matrix_with(
                refinement_couplings=_t07_target().couplings))
    refused("a matrix whose refinement arm is not an arm", ValueError,
            lambda: _t07_matrix_with(refinement_arm="nobody"))
    refused("a matrix whose scalar count disagrees with its table", ValueError,
            lambda: _t07_matrix_with(trials_per_cell=7))
    refused("a resource estimate with no line items", ValueError,
            lambda: xpr.ResourceEstimate("l", "a" * 64, "b" * 64, (), 1.0, 1.0,
                                         1.0, 1, 1))

    return Result("the proposed matrix names its refinement cells, arm and "
                  "grids exactly, and its cost is a checkable sum of named "
                  "line items", not problems,
                  abs(resources.clock_steps - clock_steps) / clock_steps, 1e-6,
                  (f"{len(matrix.couplings)} frozen coupling nodes over "
                   f"{matrix.clocks} clocks on a {matrix.grid_parity} midpoint "
                   f"grid, spacing {matrix.grid_spacing:.6g}, "
                   f"{matrix.eligible_at_weakest} eligible at the weakest "
                   f"coupling against a minimum of "
                   f"{matrix.minimum_eligible_clocks}.  Arm grids "
                   f"{ {k: v for k, v in matrix.arm_clocks} }, arm trial "
                   f"counts { {k: v for k, v in matrix.arm_trials} }.  The "
                   f"ladder refines exactly "
                   f"{[round(value, 5) for value in matrix.refinement_couplings]}"
                   f" on the {matrix.refinement_arm!r} arm at "
                   f"{matrix.refinement_trials_per_cell} trials.  "
                   f"{len(resources.lines)} named cost lines summing to "
                   f"{resources.runs} runs, {resources.physical_trials} "
                   f"physical trial executions, {resources.shadow_rewalks} "
                   f"shadow rewalks, {resources.rows:.0f} durable rows, "
                   f"{resources.clock_steps:.4g} walked clock-steps, "
                   f"{resources.wall_hours:.0f} h at safety "
                   f"{resources.safety_factor} and "
                   f"{resources.storage_bytes / 1e6:.0f} MB — every one of "
                   f"which is recomputed independently in this check.  The "
                   f"range pilot is priced separately at "
                   f"{pilot.wall_seconds / 3600.0:.1f} h and is not inside "
                   f"that total")
                  if not problems else "; ".join(problems[:6]), covers=(114,))


def _t07_matrix_with(**changes):
    """The proposed matrix with one field replaced, for the refusal probes."""
    matrix = _t07_matrix()
    fields = {name: getattr(matrix, name)
              for name in ("label", "couplings", "clocks", "arm_clocks",
                           "arm_trials", "grid_half_width", "pulse_duration",
                           "pulse_centre", "phase_diffusion", "lock_tolerance",
                           "dwell_time", "timestep", "timestep_ladder",
                           "refinement_couplings", "refinement_arm",
                           "refinement_trials_per_cell", "trials_per_cell",
                           "shadow_fraction", "minimum_eligible_clocks",
                           "discrete_staircase_fallback", "stop_rule",
                           "failure_rule")}
    fields.update(changes)
    return xpr.PrimaryMatrix(**fields)


@check("pilot runs are quarantined out of the production reader's reach, the "
       "count door checks the directory family, and only counts come back",
       covers=[115])
def check_pilot_firewall():
    """The firewall, attacked rather than described.

    An independent review broke the old one twice, and both are closed:

    1. it wrote a **pilot-labelled, pilot-keyed** four-trial run into a
       directory called ``prod-t07-review-bypass`` and the count door accepted
       it, because nothing looked at the name.  ``require_pilot_name`` now
       refuses a run in the production family and a run in neither; and
    2. it opened the same fixture with public ``raw_runner.open_raw_run`` and
       read commit times, dwell resets, band entries, eligible and exposure
       time, final phases and co-completion.  A typed narrow return never
       prevented that.  A closed pilot run is now **moved** into a quarantine
       directory that ``open_raw_run`` cannot address — its name is two
       segments, which that door refuses — and this module's count projection
       is the only supported path to it.

    Quarantine does not cost auditability: the projection re-reads the five
    files, puts them through the same eight-check closure gate, and compares
    the ledger digest with the one the handle carries.

    The pilot has **not been run**: these are four-trial synthetic fixtures
    created, quarantined and removed by this check.
    """
    problems = []
    refused = _t07_refuser(problems)
    firewall = _t07_firewall()

    refused("a firewall sharing one stream namespace", ValueError,
            lambda: xpr.PilotFirewall("xpilot-shared", "xpilot-shared",
                                      "xpilot-a", "prod-b", 1, 1, 4))
    refused("a firewall whose production namespace lacks its prefix",
            ValueError,
            lambda: xpr.PilotFirewall("xpilot-a", "xpilot-b", "xpilot-a",
                                      "prod-b", 1, 1, 4))
    refused("a firewall declaring pilot trials eligible", ValueError,
            lambda: xpr.PilotFirewall("xpilot-a", "prod-b", "xpilot-a", "prod-b",
                                      1, 1, 4, True))
    refused("a run name in the production family", ValueError,
            lambda: firewall.require_pilot_name("prod-t07-review-bypass"))
    refused("a run name in neither family", ValueError,
            lambda: firewall.require_pilot_name("verify-something"))
    refused("a run name that is not one segment", ValueError,
            lambda: firewall.require_pilot_name("pilot-t07/inner"))
    if firewall.require_pilot_name("xpilot-t07-cell-0") != "xpilot-t07-cell-0":
        problems.append("a legitimate pilot name was not returned unchanged")

    for name in xpr.FORBIDDEN_PILOT_FIELDS:
        if firewall.permits(name):
            problems.append(f"the firewall permits {name!r}")
    for name in xpr.PERMITTED_PILOT_FIELDS:
        if not firewall.permits(name):
            problems.append(f"the firewall forbids the permitted {name!r}")

    quarantine = PACKAGE_DIR / rawrun.RESULTS_DIRNAME / xpr.QUARANTINE_DIRNAME
    names = ["xpilot-t07-fixture-fx-0", "prod-t07-review-bypass",
             "xpilot-t07-foreign", "xpilot-t07-undeclared",
             "xpilot-t07-crossed", "xpilot-t07-residue-a",
             "prod-t07-residue-b"]
    try:
        for name in names:
            shutil.rmtree(rawrun.raw_results_directory(name),
                          ignore_errors=True)
        plan = xpr.pilot_plan(
            label="T07 firewall probe plan", firewall=firewall,
            fingerprint=xpr.source_fingerprint(),
            couplings=(0.5, 0.9, 1.4, 2.0), clocks=4, grid_half_width=3.0,
            timestep=0.5, pulse_duration=4.0, pulse_centre=0.0,
            phase_diffusion=0.08, lock_tolerance=0.35, dwell_time=0.5,
            trials_per_cell=4, shadow_fraction=0.25,
            run_name_prefix="xpilot-t07-fixture-fx", purpose="verifier_fixture")
        pilot_config = plan.config_for(0.5)
        fixture_name = plan.run_name_for(0.5)
        run = xpr.write_pilot_run(plan, firewall, 0.5, fixture_name)
        # The production writer refuses the reserved identity outright, so the
        # review's two bypass fixtures cannot even be created there any more.
        refused("writing a reserved pilot into the production root", ValueError,
                lambda: rawrun.write_raw_run(pilot_config,
                                             "prod-t07-review-bypass"))
        refused("writing a reserved pilot under a pilot name in production",
                ValueError,
                lambda: rawrun.write_raw_run(pilot_config,
                                             "xpilot-t07-elsewhere"))
        if Path(rawrun.raw_results_directory(fixture_name)).exists():
            problems.append("a transient production-root entry exists for a "
                            "quarantined pilot")

        # The review's exact reproduction: a pilot-labelled, pilot-keyed run in
        # the production directory family.
        refused("writing a pilot into the production directory family",
                ValueError,
                lambda: xpr.write_pilot_run(plan, firewall, 0.5,
                                            "prod-t07-review-bypass"))
        # **Which pilot, not only where.**  There is no configuration and no
        # model parameter any more, so the review's width-only, two-clock,
        # dt=1, two-trial run cannot be written through this door at all: the
        # plan names the model and the configuration, and a coupling it does
        # not declare is refused.  The plan/firewall join is checked too.
        refused("a coupling the plan does not declare", ValueError,
                lambda: xpr.write_pilot_run(plan, firewall, 0.4321,
                                            "xpilot-t07-fixture-fx-0"))
        refused("a declared coupling written under another cell's name",
                ValueError,
                lambda: xpr.write_pilot_run(plan, firewall, 0.5,
                                            plan.run_name_for(0.9)))
        refused("a run name the plan does not freeze", ValueError,
                lambda: xpr.write_pilot_run(plan, firewall, 0.5,
                                            "xpilot-t07-undeclared"))
        refused("a plan frozen against another firewall", ValueError,
                lambda: xpr.write_pilot_run(
                    plan,
                    xpr.PilotFirewall("xpilot-t07-range", "prod-t07-primary",
                                      "xpilot-t07", "prod-t07", 5, 5, 4),
                    0.5, plan.run_name_for(0.5)))
        for parameter in ("config", "model", "clock_block", "step_window"):
            if parameter in inspect.signature(
                    xpr.write_pilot_run).parameters:
                problems.append(f"write_pilot_run still takes a "
                                f"{parameter!r} parameter, so the pilot it "
                                f"writes is still a caller's choice")
        # **A refusal leaves no residue.**  The review found a wrong run_label
        # refused only after the run had been written and closed, leaving a
        # quarantined directory that blocked a correct retry.  Every check now
        # happens before any directory is created, and a label is no longer
        # expressible at all.
        for label, coupling, name in (
                ("an undeclared coupling", 0.4321, "xpilot-t07-fixture-fx-1"),
                ("a production-family name", 0.5, "prod-t07-residue-b")):
            try:
                xpr.write_pilot_run(plan, firewall, coupling, name)
            except ValueError:
                if (quarantine / name).exists() or \
                        Path(rawrun.raw_results_directory(name)).exists():
                    problems.append(f"refusing {label} left a directory "
                                    f"behind that blocks a correct retry")
            else:
                problems.append(f"{label} was accepted")
        if not (quarantine / fixture_name).is_dir():
            problems.append("the run did not reach the quarantine")

        # The unrestricted reader can no longer address it, by either spelling.
        refused("open_raw_run on the quarantined name", ValueError,
                lambda: rawrun.open_raw_run(fixture_name))
        refused("open_raw_run through the quarantine path", ValueError,
                lambda: rawrun.open_raw_run(
                    f"{xpr.QUARANTINE_DIRNAME}/pilot-t07-fixture"))
        refused("open_raw_run on the quarantine directory itself", ValueError,
                lambda: rawrun.open_raw_run(xpr.QUARANTINE_DIRNAME))

        counts = xpr.pilot_counts(firewall, run)
        exposed = {name for name in dir(counts) if not name.startswith("_")}
        leaked = sorted(exposed & set(xpr.FORBIDDEN_PILOT_FIELDS))
        if leaked:
            problems.append(f"PilotCellCounts exposes {leaked}")
        if exposed != {"coupling", "trials", "committed", "survivors"}:
            problems.append(f"PilotCellCounts exposes {sorted(exposed)}")
        if counts.trials != 4 or counts.committed + counts.survivors != 4:
            problems.append(f"the counts do not reconcile: {counts!r}")
        if sorted(exposed) != ["committed", "coupling", "survivors",
                               "trials"]:
            problems.append(f"the count surface is {sorted(exposed)}")

        # The closure gate really ran: a mutated quarantined table is refused.
        table = quarantine / fixture_name / rawrun.RUN_FILENAMES["ledger"]
        original = table.read_bytes()
        try:
            # Duplicating the last row moves both the table digest and the
            # row count the marker declares, so the mutation cannot be a
            # no-op on a fixture that happens to lack a particular category.
            table.write_bytes(original + original.splitlines(True)[-1])
            refused("a mutated quarantined ledger", ValueError,
                    lambda: xpr.pilot_counts(firewall, run))
        finally:
            table.write_bytes(original)
        restored = xpr.pilot_counts(firewall, run)
        if (restored.coupling, restored.trials, restored.committed) != \
                (counts.coupling, counts.trials, counts.committed):
            problems.append("restoring the bytes did not restore the counts")
        # An unquarantined run in the pilot family, reachable by the ordinary
        # reader, is not reachable through this door by any handle.
        refused("a handle naming a run that was never quarantined", ValueError,
                lambda: xpr.pilot_counts(
                    firewall, xpr.QuarantinedPilotRun(
                        "xpilot-t07-foreign", run.closure_digest, 4, 1.0)))
    finally:
        shutil.rmtree(quarantine, ignore_errors=True)
        for name in names:
            shutil.rmtree(rawrun.raw_results_directory(name),
                          ignore_errors=True)

    return Result("pilot runs are quarantined out of the production reader's "
                  "reach, the count door checks the directory family, and only "
                  "counts come back", not problems, float(len(problems)), 0.0,
                  (f"a shared namespace, a prefix-less namespace and an "
                   f"eligible pilot are refused at construction; a run name in "
                   f"the production family, in neither family, or spelled with "
                   f"a separator is refused at the door — including the "
                   f"review's own 'prod-t07-review-bypass' reproduction, which "
                   f"carried a pilot label and a pilot namespace.  A closed "
                   f"pilot run is written directly into "
                   f"{xpr.QUARANTINE_DIRNAME!r}, after which "
                   f"raw_runner.open_raw_run refuses it by every spelling — "
                   f"the bare name, the two-segment path and the quarantine "
                   f"directory itself — and the count projection is the only "
                   f"way in.  It re-runs the full closure gate: a duplicated "
                   f"row in the quarantined ledger is refused, and "
                   f"restoring the bytes restores the counts.  The record it "
                   f"returns exposes exactly coupling, trials, committed, "
                   f"survivors -- four values and no provenance field -- "
                   f"and none of the "
                   f"{len(xpr.FORBIDDEN_PILOT_FIELDS)} forbidden names.  No "
                   f"pilot has been run: these are four-trial synthetic "
                   f"fixtures, created and removed here")
                  if not problems else "; ".join(problems[:6]), covers=(115,))


@check("the count-only range rule binds its pilot ledgers, and the reference "
       "rate is derived inside the manifest rather than supplied", covers=[116])
def check_range_selection():
    """What a pilot would decide, decided from four numbers per cell.

    An independent review found the frozen contraction rate supplied as a free
    argument beside a caller-constructed selection, so a manifest could not
    prove the rate was the one the selected range implies.  Two changes close
    it: a :class:`RangeSelection` carries the close-marker digest of every
    pilot ledger its counts came from, and the manifest builder computes the
    rate itself through :func:`reference_rate` — there is no argument for one.
    """
    problems = []
    refused = _t07_refuser(problems)
    firewall = xpr.PilotFirewall("xpilot-t07-probe", "prod-t07-probe",
                                 "xpilot-t07p", "prod-t07p", 20, 20, 4)

    def counts(pattern):
        return _t07_synthetic_counts(firewall, pattern)

    clean = counts([(0.4, 2), (0.5, 30), (0.7, 45), (1.0, 55), (1.4, 70),
                    (2.0, 99)])
    selection = xpr.preview_range(firewall, clean)
    if not selection.selected or selection.low != 0.5 or selection.high != 1.4 \
            or selection.cells != 4:
        problems.append(f"the clean pattern selected {selection!r}")
    if type(selection) is not xpr.PreviewRangeSelection:
        problems.append("preview_range did not return the display-only type")
    refused("the reference rate from a display preview", TypeError,
            lambda: xpr.reference_rate(selection))

    for label, pattern, expected in (
            ("saturated", [(0.5, 30), (0.7, 45), (1.0, 55), (1.4, 70),
                           (2.0, 100), (3.0, 100)], None),
            ("gapped", [(0.5, 30), (0.7, 45), (1.0, 1), (1.4, 70), (2.0, 75),
                        (3.0, 80)], "not_contiguous_enough"),
            ("barren", [(0.5, 0), (0.7, 1), (1.0, 2), (1.4, 100), (2.0, 100),
                        (3.0, 100)], "no_eligible_cells"),
            ("short", [(0.5, 30), (0.7, 45), (1.0, 55)], "run_too_short")):
        outcome = xpr.preview_range(firewall, counts(pattern))
        if expected is None:
            if not outcome.selected or outcome.high != 1.4:
                problems.append(f"the {label} pattern gave {outcome!r}")
        elif outcome.selected or outcome.refusal != expected:
            problems.append(f"the {label} pattern gave {outcome!r} rather than "
                            f"refusing as {expected}")

    gapped = xpr.preview_range(firewall, counts(
        [(0.5, 30), (0.7, 45), (1.0, 1), (1.4, 70), (2.0, 75), (3.0, 80)]))
    # **The rate is an authoritative door.**  An independent review built a
    # six-cell RangeSelection out of invented digests, handed it to the old
    # one-argument signature and got 1.0000000000000002 back, which then went
    # into a proposal whose source table said it came from a count-only rule.
    # There is no selection parameter now: the door takes the frozen plan, the
    # firewall it was frozen against and the ordered quarantined run names, and
    # recomputes everything from one reopened snapshot.
    for parameter in ("selection",):
        if parameter in inspect.signature(xpr.reference_rate).parameters:
            problems.append(f"reference_rate still takes a {parameter!r}, so "
                            f"a caller-built range still authorizes its own "
                            f"contraction rate")
    refused("a reference rate from a caller-built selection", TypeError,
            lambda: xpr.reference_rate(
                xpr.RangeSelection(0.5, 2.0, 4, "", "a" * 64, "b" * 64,
                                   tuple(f"{i:064x}" for i in range(4)))))

    # ---- the cloning helper cannot mint production evidence ---------------
    # The exact round-10 escape, replayed.  The fixture writer clones a handful
    # of real histories up to a declared trial count; an independent review
    # handed it the *canonical production plan* and got the reserved
    # ``xpilot-t07-cell-*`` family written, and handed it an ``AlternatingPlan``
    # subclass — canonical fields, canonical digest — whose ``config_for``
    # answered with a cheap ``dt = 0.05``, coupling-0.2 configuration on the
    # source call and the canonical configuration on the manifest call.  Six
    # counterfeit canonical closures resulted; the genuine exact-typed
    # canonical plan then recounted them and ``select_range``,
    # ``post_range_power``, ``proposed_production_manifest``,
    # ``require_authoritative_proposal`` and ``checkpoint_one_handoff`` all
    # accepted the resulting ``post_range_powered`` snapshot.
    #
    # Every one of these is required to refuse **before a directory exists**,
    # so the quarantine root is inspected on both sides of each attempt.
    canonical_plan = _t07_plan()
    genuine_fixture = _t07_fixture_plan()
    quarantine = xpr._quarantine_root()

    class _AlternatingPlan(xpr.PilotPlan):
        """A ``PilotPlan`` subclass that answers ``config_for`` two ways.

        The review's reproduction, verbatim in behaviour: odd calls return a
        cheap coarse-step configuration for the source walk, even calls return
        the plan's own configuration for the manifest written above the clone.
        """

        def config_for(self, coupling):
            calls = getattr(self, "_alternating_calls", 0)
            object.__setattr__(self, "_alternating_calls", calls + 1)
            honest = super().config_for(coupling)
            if calls % 2 == 0:
                return dataclasses.replace(
                    honest, timestep=_T07_FIXTURE_TIMESTEP, peak_coupling=0.2)
            return honest

    def _same_fields(plan, subclass):
        return subclass(**{name: getattr(plan, name)
                           for name in xpr.PilotPlan.__dataclass_fields__
                           if name != "seal"},
                        seal=xpr._PLAN_SEAL)

    alternating = _same_fields(canonical_plan, _AlternatingPlan)
    alternating_fixture = _same_fields(genuine_fixture, _AlternatingPlan)
    relabelled = xpr.PilotPlan(
        **{**{name: getattr(canonical_plan, name)
              for name in xpr.PilotPlan.__dataclass_fields__ if name != "seal"},
           "purpose": "verifier_fixture"},
        seal=xpr._PLAN_SEAL)
    # A second, honestly built fixture plan: it satisfies every rule about
    # self-consistency and purpose, and it is still not the one fixture this
    # helper may write.
    other_fixture = xpr.pilot_plan(
        label="a second verifier fixture plan, not this verifier's",
        firewall=_t07_firewall(), fingerprint=xpr.source_fingerprint(),
        couplings=_t07_fixture_couplings(), clocks=_T07_FIXTURE_CLOCKS,
        grid_half_width=3.0, timestep=_T07_FIXTURE_TIMESTEP,
        pulse_duration=4.0, pulse_centre=0.0, phase_diffusion=0.08,
        lock_tolerance=0.35, dwell_time=0.5, trials_per_cell=200,
        shadow_fraction=0.05, run_name_prefix="xpilot-t07-fixture-cell",
        purpose="verifier_fixture")
    # The attacks are only attacks if they really do carry the digests they
    # claim; a subclass that failed to reproduce them would prove nothing.
    for label, forged, real in (
            ("the alternating canonical subclass", alternating,
             canonical_plan),
            ("the alternating fixture subclass", alternating_fixture,
             genuine_fixture)):
        if forged.digest != real.digest:
            problems.append(f"{label} does not reproduce the digest it copies, "
                            f"so this replay does not exercise the escape")

    first_cell = genuine_fixture.couplings[0]
    reserved_name = _t07_reserved_run_names()[0]

    # ---- fields are not behaviour ------------------------------------------
    # The second review's finding.  ``PilotPlan`` is frozen but **not slotted**,
    # so an *exact-typed* instance carrying every declared field and the right
    # digest can still take instance attributes that shadow the plain methods
    # the writers call: functions are non-data descriptors and the instance
    # dictionary wins.  The reviewer shadowed ``require_run_name``,
    # ``coupling_for`` and ``run_name_for``, passed the identity door, and had
    # the per-cell helper write an honest eight-clock closure under the
    # reserved name ``xpilot-t07-cell-0``.  No canonical recount was claimed
    # and none is needed: a fixture had occupied a production identity.
    def _shadowed(**attributes):
        """An exact-typed fixture plan carrying injected instance attributes."""
        instance = xpr.PilotPlan(
            **{name: getattr(genuine_fixture, name)
               for name in xpr.PilotPlan.__dataclass_fields__
               if name != "seal"},
            seal=xpr._PLAN_SEAL)
        for name, value in attributes.items():
            # ``run_names`` is a property — a data descriptor — so
            # ``object.__setattr__`` would be refused by it and an entry in the
            # instance dictionary could never win a lookup.  It is written
            # directly here anyway, because the door refuses *any* attribute
            # outside the declared fields and that rule should be exercised on
            # a name that was never shadowable as well as on ones that were.
            if isinstance(vars(xpr.PilotPlan).get(name), property):
                vars(instance)[name] = value
            else:
                object.__setattr__(instance, name, value)
        return instance

    cheap_config = dataclasses.replace(
        genuine_fixture.config_for(first_cell), timestep=0.5, trials=2,
        shadow_trials=1)
    # The reviewer's exact instance: the three mappings the per-cell writer
    # consults, all answered by the caller, so a reserved name is accepted,
    # mapped to a real declared coupling and written.
    review_case = _shadowed(require_run_name=lambda name: name,
                            coupling_for=lambda name: first_cell,
                            run_name_for=lambda coupling: reserved_name)
    shadow_cases = (
        ("require_name", _shadowed(require_run_name=lambda name: name)),
        ("coupling_for", _shadowed(coupling_for=lambda name: first_cell)),
        ("config_for", _shadowed(config_for=lambda coupling: cheap_config)),
        ("run_name_for",
         _shadowed(run_name_for=lambda coupling: reserved_name)),
        ("require_run_names",
         _shadowed(require_run_names=lambda names: tuple(names))),
        ("require_manifest",
         _shadowed(require_manifest=lambda manifest, coupling: manifest)),
        ("run_names", _shadowed(run_names=_t07_reserved_run_names())),
        ("an unrelated attribute", _shadowed(predictor=object())),
        ("the reviewer's three-method instance", review_case),
    )
    for label, instance in shadow_cases:
        if type(instance) is not xpr.PilotPlan:
            problems.append(f"the {label} shadow case is not exact-typed, so "
                            f"it does not exercise the finding")
        if instance.digest != genuine_fixture.digest:
            problems.append(f"the {label} shadow case does not carry the "
                            f"fixture's own digest, so it does not exercise "
                            f"the finding")

    shadow_attacks = tuple(
        (f"an exact-type instance shadowing {label}", ValueError,
         (lambda i=instance: _t07_pilot_fixture(i)))
        for label, instance in shadow_cases) + tuple(
        (f"the per-cell writer given an instance shadowing {label}",
         ValueError,
         (lambda i=instance: _t07_write_fixture_cell(
             i, first_cell, "xpilot-t07-fixture-src-0", reserved_name)))
        for label, instance in shadow_cases) + (
        ("the identity door itself given the reviewer's instance", ValueError,
         lambda: _t07_require_fixture_plan(review_case)),)

    attacks = shadow_attacks + (
            ("the canonical production plan", ValueError,
             lambda: _t07_pilot_fixture(canonical_plan)),
            ("the alternating canonical subclass", TypeError,
             lambda: _t07_pilot_fixture(alternating)),
            ("an alternating subclass carrying the fixture's own digest",
             TypeError, lambda: _t07_pilot_fixture(alternating_fixture)),
            ("a sealed exact-type relabel of the canonical plan", ValueError,
             lambda: _t07_pilot_fixture(relabelled)),
            ("a dataclasses.replace of the fixture plan", TypeError,
             lambda: _t07_pilot_fixture(
                 dataclasses.replace(genuine_fixture, trials_per_cell=8))),
            ("a second self-consistent fixture plan", ValueError,
             lambda: _t07_pilot_fixture(other_fixture)),
            ("the per-cell writer handed the canonical plan", ValueError,
             lambda: _t07_write_fixture_cell(
                 canonical_plan, canonical_plan.couplings[0],
                 "xpilot-t07-fixture-src-0", reserved_name)),
            ("the per-cell writer handed the alternating subclass", TypeError,
             lambda: _t07_write_fixture_cell(
                 alternating, alternating.couplings[0],
                 "xpilot-t07-fixture-src-0", reserved_name)),
            ("the per-cell writer asked for a reserved cell name", ValueError,
             lambda: _t07_write_fixture_cell(
                 genuine_fixture, first_cell, "xpilot-t07-fixture-src-0",
                 reserved_name)),
            ("the per-cell writer asked for an unmarked source name",
             ValueError,
             lambda: _t07_write_fixture_cell(
                 genuine_fixture, first_cell, reserved_name,
                 genuine_fixture.run_names[0])),
            ("the per-cell writer asked to write one cell's coupling under "
             "another cell's name", ValueError,
             lambda: _t07_write_fixture_cell(
                 genuine_fixture, first_cell, "xpilot-t07-fixture-src-0",
                 genuine_fixture.run_names[1])))

    def _replay(phase, expected_entries, sentinel_bytes):
        """Every attack once, with the quarantine's contents held fixed.

        ``expected_entries`` is exactly what the quarantine must hold after
        each refusal: nothing at all when the root was absent, and only the
        untouched bystander run when it was not.
        """
        for label, expected_error, call in attacks:
            existed = quarantine.exists()
            refused(f"the fixture writer driven by {label} ({phase})",
                    expected_error, call)
            if quarantine.exists() and not existed:
                problems.append(
                    f"{label} ({phase}) was refused, but only after the "
                    f"quarantine root had been created; the identity door has "
                    f"to close before anything is written")
            entries = (sorted(path.name for path in quarantine.iterdir())
                       if quarantine.exists() else [])
            if entries != expected_entries:
                problems.append(f"{label} ({phase}) left the quarantine "
                                f"holding {entries} rather than "
                                f"{expected_entries}")
            if reserved_name in entries:
                problems.append(f"{label} ({phase}) wrote the reserved "
                                f"production name {reserved_name!r}")
            if sentinel_bytes is not None:
                current = (bystander.read_bytes() if bystander.is_file()
                           else None)
                if current != sentinel_bytes:
                    problems.append(f"{label} ({phase}) mutated or removed an "
                                    f"unrelated pre-existing quarantine run")

    # Phase one: from an absent quarantine.  Nothing may be created at all.
    shutil.rmtree(quarantine, ignore_errors=True)
    bystander = quarantine / "xpilot-t07-fixture-bystander" / "ledger.bin"
    _replay("absent quarantine", [], None)

    # Phase two: beside an unrelated pre-existing run.  A refused call may
    # neither add to the quarantine nor touch what was already in it.
    try:
        bystander.parent.mkdir(parents=True, exist_ok=False)
        witness = b"an unrelated quarantined run that predates these calls"
        bystander.write_bytes(witness)
        _replay("populated quarantine", [bystander.parent.name], witness)
    finally:
        shutil.rmtree(quarantine, ignore_errors=True)

    # And the consequence the escape produced is gone: the approved pilot's
    # reserved cells do not exist, so its own recount finds nothing to read.
    refused("the canonical plan recounting its reserved cells after the "
            "refused fixture attempts", ValueError,
            lambda: xpr.select_range(canonical_plan, _t07_firewall(),
                                     canonical_plan.run_names))
    # The positive control, so the door above is a door and not a wall.  It
    # returns the **freshly built** record rather than the caller's, so the
    # test is field and digest equality and deliberately not identity.
    admitted = _t07_require_fixture_plan(genuine_fixture)
    if admitted is genuine_fixture:
        problems.append("the identity door handed the caller's own record "
                        "back; the writers are supposed to continue with a "
                        "freshly built plan, not with the object they were "
                        "given")
    if type(admitted) is not xpr.PilotPlan or \
            admitted.digest != genuine_fixture.digest or \
            any(getattr(admitted, name) != getattr(genuine_fixture, name)
                for name in xpr.PilotPlan.__dataclass_fields__
                if name != "seal"):
        problems.append("the verifier's own fixture plan did not survive the "
                        "fixture-identity door")
    if set(vars(admitted)) - set(xpr.PilotPlan.__dataclass_fields__):
        problems.append("the record the identity door returns carries an "
                        "attribute outside its declared fields")

    # The deterministic fixture: four real quarantined cells at the plan's own
    # declared trial count, cloned from real committed and unresolved
    # histories, and the whole authoritative join taken over them.
    fixture_plan = _t07_fixture_plan()
    fixture_firewall = _t07_firewall()
    rate = None
    try:
        runs = _t07_pilot_fixture(fixture_plan)
        cells = xpr._authoritative_cells(fixture_plan, fixture_firewall, runs)
        for cell, _, _ in cells:
            if cell.trials != fixture_plan.trials_per_cell:
                problems.append(f"a fixture cell holds {cell.trials} trials "
                                f"and the plan declares "
                                f"{fixture_plan.trials_per_cell}")
            if cell.committed < xpr.MIN_PILOT_EVENTS or \
                    cell.survivors < xpr.MIN_PILOT_SURVIVORS:
                problems.append(f"a fixture cell has {cell.committed} "
                                f"commitments and {cell.survivors} survivors, "
                                f"below the frozen minima")
        if len(cells) < xpr.MIN_SELECTED_CELLS:
            problems.append(f"the fixture covers {len(cells)} cells")
        chosen = xpr.select_range(fixture_plan, fixture_firewall, runs)
        if not chosen.selected or chosen.cells != len(runs):
            problems.append(f"the fixture selection is {chosen!r}")
        if len(set(chosen.closure_digests)) != len(runs):
            problems.append("the fixture selection does not bind one closure "
                            "digest per run")
        rate = xpr.reference_rate(fixture_plan, fixture_firewall, runs)
        if rate != dyn.fixed_contraction_rate(chosen.low, chosen.high):
            problems.append("the reference rate is not "
                            "dynamics.fixed_contraction_rate over the "
                            "recomputed range")
        # **The plan check is a check on the physics.**  The fixture's
        # couplings are the production plan's own first four nodes, so this
        # refusal is about the clock count and the timestep -- about being a
        # different experiment -- and not about an unknown coupling.
        refused("the frozen production plan reading the fixture's runs",
                ValueError,
                lambda: xpr.select_range(_t07_plan(), fixture_firewall, runs))
        refused("a recount that names a run twice", ValueError,
                lambda: xpr.select_range(fixture_plan, fixture_firewall,
                                         (runs[0], runs[0])))
        # ---- the fixture plan cannot reach a production decision --------
        for label, call in (
                ("the proposal factory",
                 lambda: xpr.proposed_production_manifest(
                     label="probe", fingerprint=xpr.source_fingerprint(),
                     matrix=_t07_matrix(), target=_t07_target(),
                     power=_t07_power(), disposition=_t07_disposition(),
                     search=_t07_search(), benchmark=_t07_slowest(),
                     resources=_t07_resources(), firewall=fixture_firewall,
                     status_reason="probe", recovery=_t07_recovery(),
                     plan=fixture_plan)),
                ("the proposal factory beside real quarantined runs",
                 lambda: xpr.proposed_production_manifest(
                     label="probe", fingerprint=xpr.source_fingerprint(),
                     matrix=_t07_matrix(), target=_t07_target(),
                     power=_t07_power(), disposition=_t07_disposition(),
                     search=_t07_search(), benchmark=_t07_slowest(),
                     resources=_t07_resources(), firewall=fixture_firewall,
                     status_reason="probe", recovery=_t07_recovery(),
                     plan=fixture_plan, pilot_run_names=runs))):
            refused(f"a verifier fixture plan reaching {label}", ValueError,
                    call)
        # ---- and a forged post-range power cannot enter one -------------
        # The review's exact reproduction: a provisional estimate relabelled
        # post_range_join with an invented selection digest, handed in beside
        # four real runs.
        forged_power = dataclasses.replace(
            _t07_power(), stage="post_range_join", selection_digest="f" * 64)
        refused("a forged post-range power beside real quarantined runs",
                ValueError,
                lambda: xpr.proposed_production_manifest(
                    label="probe", fingerprint=xpr.source_fingerprint(),
                    matrix=_t07_matrix(), target=_t07_target(),
                    power=forged_power, disposition=_t07_disposition(),
                    search=_t07_search(), benchmark=_t07_slowest(),
                    resources=_t07_resources(), firewall=fixture_firewall,
                    status_reason="probe", recovery=_t07_recovery(),
                    plan=fixture_plan, pilot_run_names=runs))
        # ---- exact pilot identity and order ---------------------------
        # Every one of these is an **authority** refusal: "these are not that
        # pilot's runs" is not a statement about coupling ranges.  An
        # independent review read the four runs in reverse and got a selection
        # back, and omitted one and got a scientific ``run_too_short``.
        for label, supplied in (
                ("reordered", tuple(reversed(runs))),
                ("one cell omitted", runs[:-1]),
                ("a duplicated run", (runs[0],) + runs[1:] + (runs[0],)),
                ("an extra undeclared run", runs + ("xpilot-t07-fixture-cell-9",)),
                ("a foreign run", runs[:-1] + ("xpilot-api-fixture-cell-0",)),
                ("a run swapped for another cell's name",
                 (runs[1], runs[0]) + runs[2:])):
            for door, call in (
                    ("select_range",
                     lambda n=supplied: xpr.select_range(
                         fixture_plan, fixture_firewall, n)),
                    ("post_range_plan",
                     lambda n=supplied: xpr.post_range_plan(
                         _t07_target(), fixture_plan, fixture_firewall, n))):
                try:
                    outcome = call()
                except ValueError:
                    continue
                except Exception as exc:                      # noqa: BLE001
                    problems.append(f"{door} on {label} raised "
                                    f"{type(exc).__name__}")
                else:
                    problems.append(
                        f"{door} accepted {label} and answered "
                        f"{getattr(outcome, 'status', outcome)!r}; a set of "
                        f"runs that is not the approved pilot's is an "
                        f"authority refusal, never a scientific result")
        if xpr.select_range(fixture_plan, fixture_firewall,
                            fixture_plan.run_names).digest != chosen.digest:
            problems.append("the plan's own frozen run names do not reproduce "
                            "the selection")

        # ---- the affordability ceiling binds every arm ------------------
        # An independent review found this fixture reported ``powered`` while
        # its unpaired central control was sized at 22 211 trials per cell
        # against a declared ceiling of 20 000, because only the paired count
        # was compared.
        powered = xpr.post_range_power(_t07_target(), fixture_plan,
                                       fixture_firewall, runs)
        if powered.stage != "post_range_join" or powered.cells != len(runs):
            problems.append(f"the post-range join is {powered.stage!r} over "
                            f"{powered.cells} cells")
        ceiling = _t07_target().maximum_trials_per_cell
        worst = max(powered.arm_trials.values())
        if worst > ceiling and powered.verdict == "powered":
            problems.append(
                f"the join reports 'powered' while its {powered.driving_arm} "
                f"arm needs {worst} trials per cell against the declared "
                f"ceiling {ceiling}")
        state = xpr.post_range_plan(_t07_target(), fixture_plan,
                                    fixture_firewall, runs)
        if (state.status == "post_range_powered") != (powered.verdict
                                                      == "powered"):
            problems.append(f"the post-range status {state.status!r} and the "
                            f"power verdict {powered.verdict!r} disagree")
        for arm, count in powered.arm_trials.items():
            if count > ceiling and powered.verdict == "powered":
                problems.append(f"arm {arm} at {count} exceeds the ceiling in "
                                f"a powered join")
        # The exact boundary, both sides of it: a ceiling at the worst arm's
        # own count admits the matrix, and one trial below it refuses.
        for label, allowed, should_pass in (("at the worst arm's count", worst,
                                             True),
                                            ("one below it", worst - 1,
                                             False)):
            at_bound = xpr.post_range_power(
                dataclasses.replace(_t07_target(),
                                    maximum_trials_per_cell=allowed),
                fixture_plan, fixture_firewall, runs)
            affordable = not any(
                "affordability ceiling" in reason
                for reason in at_bound.reasons)
            if affordable != should_pass:
                problems.append(
                    f"a ceiling {label} ({allowed}) "
                    f"{'refused' if should_pass else 'admitted'} a join whose "
                    f"worst arm needs {worst}")
            if max(at_bound.arm_trials.values()) > allowed and affordable:
                problems.append(f"an arm exceeds the ceiling {allowed} in an "
                                f"estimate reporting no affordability reason")

        # ---- the seal is construction only ------------------------------
        # The review reached ``_PLAN_SEAL`` and built an exact-typed plan
        # carrying a false Python version, NumPy version, platform and
        # configuration digest; the proposal took it and recorded the *live*
        # environment beside it.  The plan is rebuilt from its own declared
        # inputs and the live package now, so each of these is refused.
        for field, value in (("python_version", "9.9.9"),
                             ("numpy_version", "0.0.0"),
                             ("platform", "not-this-machine"),
                             ("source_digest", "b" * 64),
                             ("config_digest", "a" * 64),
                             ("ledger_schema_version", 99),
                             ("manifest_schema_version", 99),
                             ("grid_spacing", 1.0),
                             ("steps", 7),
                             ("shadow_trials", 3),
                             ("purpose", "approved_production_pilot")):
            forged_plan = xpr.PilotPlan(
                **{**{name: getattr(fixture_plan, name)
                      for name in xpr.PilotPlan.__dataclass_fields__
                      if name != "seal"},
                   field: value},
                seal=xpr._PLAN_SEAL)
            refused(f"a sealed plan whose {field} is not what its inputs "
                    f"build", ValueError,
                    lambda fp=forged_plan: xpr.require_authoritative_plan(
                        fp, fixture_firewall, xpr.source_fingerprint(),
                        purpose=fp.purpose))
            refused(f"a recount driven by a plan whose {field} is forged",
                    ValueError,
                    lambda fp=forged_plan: xpr.select_range(
                        fp, fixture_firewall, runs))
        if xpr.require_authoritative_plan(
                fixture_plan, fixture_firewall, xpr.source_fingerprint(),
                purpose="verifier_fixture") is not fixture_plan:
            problems.append("the genuine fixture plan did not survive its own "
                            "authoritative rebuild")
    finally:
        shutil.rmtree(PACKAGE_DIR / rawrun.RESULTS_DIRNAME
                      / xpr.QUARANTINE_DIRNAME, ignore_errors=True)
    refused("a reference rate from a refused selection", ValueError,
            lambda: xpr._rate_of(
                xpr.RangeSelection(0.0, 0.0, 0, "no_eligible_cells", "a" * 64,
                                   "b" * 64, ("c" * 64,))))
    refused("a count record with more commitments than trials", ValueError,
            lambda: xpr.PilotCellCounts(1.0, 10, 11))
    refused("two count records at one coupling", ValueError,
            lambda: xpr.preview_range(firewall, counts(
                [(0.5, 30), (0.5, 31), (0.7, 45), (1.0, 55), (1.4, 70)])))
    refused("a selection carrying both a range and a refusal", ValueError,
            lambda: xpr.RangeSelection(0.5, 2.0, 4, "no_eligible_cells",
                                       "a" * 64, "b" * 64, ("c" * 64,)))
    refused("a selection with no pilot ledgers behind it", ValueError,
            lambda: xpr.RangeSelection(0.5, 2.0, 4, "", "a" * 64, "b" * 64,
                                       ()))

    # The manifest derives the rate; there is no argument for one.
    if "fixed_contraction_rate" in inspect.signature(
            xpr.proposed_production_manifest).parameters:
        problems.append("the manifest builder still takes a contraction rate")
    if "selection" in inspect.signature(
            xpr.proposed_production_manifest).parameters:
        problems.append("the manifest builder still takes a naked selection")
    if "plan" not in inspect.signature(
            xpr.proposed_production_manifest).parameters:
        problems.append("the manifest builder does not bind a pilot plan")
    if _t07_proposal().value("fixed_contraction_rate") is not None:
        problems.append("a provisional proposal names a contraction rate")

    return Result("the count-only range rule binds its pilot ledgers, and the "
                  "reference rate is derived inside the manifest rather than "
                  "supplied", not problems, float(len(problems)), 0.0,
                  (f"five frozen count patterns with answers declared before "
                   f"the rule ran: a clean run selects [0.5, 1.4] over 4 "
                   f"cells, saturated cells are excluded, a gap refuses rather "
                   f"than bridging, no eligible cell refuses, and a short run "
                   f"refuses before looking.  The selection carries the "
                   f"close-marker digest of all {len(clean)} pilot ledgers, "
                   f"and a selection with none is refused.  The rule digest is "
                   f"invariant to the counts and the counts digest is not.  "
                   f"The reference rate {rate:.9f} is "
                   f"dynamics.fixed_contraction_rate itself.  The *authority* "
                   f"is one level up: the manifest builder has no parameter "
                   f"for a selection or for a rate, and recomputes both from "
                   f"quarantined run names")
                  if not problems else "; ".join(problems[:6]), covers=(116,))


@check("the proposal is factory-only, semantically validated field by field, "
       "and frozen by a measurement-free design digest", covers=[117])
def check_proposal_freeze():
    """A complete proposal that is structurally unable to be an approval.

    An independent review constructed every non-special field as the string
    ``"wrong-but-json-valid"`` and the public type accepted and hashed it, and
    separately built one with status ``checkpoint_one_approved``.  Both are
    closed, and by two independent mechanisms:

    * the type is **factory-only** — the public constructor demands a token it
      does not export, and the factory derives every field from exact component
      records rather than taking values; and
    * every field is checked against a declared rule even when the token is
      present, so a wrong enum, a non-digest digest, a negative count or a list
      of the wrong thing is refused rather than hashed.

    The freeze itself moved: ``design_digest`` covers the declared design and
    no measurement, so re-running the same source reproduces it, while the
    whole-proposal digest still binds the benchmark evidence and moves.
    """
    problems = []
    refused = _t07_refuser(problems)
    proposal = _t07_proposal()
    frozen = proposal.design_digest

    fields = proposal.as_dict()
    if sorted(fields) != sorted(xpr.PROPOSED_MANIFEST_KEYS):
        problems.append("the proposal's keys are not the declared key set")
    if proposal.status != "checkpoint_blocked":
        problems.append(f"the proposal's status is {proposal.status!r}")
    if fields["numerical_gate"] != rawrun.NUMERICAL_GATE:
        problems.append("the proposal does not record the diagnostic gate")
    if fields["pilot_trials_eligible"] is not False:
        problems.append("the proposal declares pilot trials eligible")
    if fields["content_revision"] != xpr.CONTENT_REVISION:
        problems.append("the proposal does not record the content revision")

    # The review's own reproduction: a complete, JSON-valid, false record.
    special = {"schema": xpr.EXPERIMENTS_SCHEMA,
               "content_revision": xpr.CONTENT_REVISION,
               "status": "checkpoint_blocked",
               "numerical_gate": rawrun.NUMERICAL_GATE,
               "production_status_schema": cmpr.PRODUCTION_STATUS_SCHEMA,
               "pilot_trials_eligible": False}
    wrong = tuple((key, special.get(key, "wrong-but-json-valid"))
                  for key in xpr.PROPOSED_MANIFEST_KEYS)
    refused("an all-wrong-but-JSON-valid proposal, unsealed", TypeError,
            lambda: xpr.ProposedProductionManifest(wrong))
    refused("an all-wrong-but-JSON-valid proposal, sealed", ValueError,
            lambda: xpr.ProposedProductionManifest(wrong, xpr._SEAL))

    # Every single field, wrong on its own, with the seal present.
    accepted = []
    for key, value in proposal.fields:
        replacement = ("not-a-value" if not isinstance(value, str)
                       else -1 if not isinstance(value, (int, float))
                       else None)
        if isinstance(value, str):
            replacement = -1
        elif isinstance(value, bool):
            replacement = True
        elif isinstance(value, (int, float)):
            replacement = "not-a-number"
        elif isinstance(value, list):
            replacement = "not-a-list"
        elif value is None:
            replacement = "not-a-null"
        mutated = tuple((name, replacement if name == key else held)
                        for name, held in proposal.fields)
        try:
            xpr.ProposedProductionManifest(mutated, xpr._SEAL)
        except (TypeError, ValueError):
            continue
        accepted.append(key)
    if accepted:
        problems.append(f"these fields accepted a wrong value: {accepted}")

    omitted = 0
    for key in xpr.PROPOSED_MANIFEST_KEYS:
        without = tuple((name, value) for name, value in proposal.fields
                        if name != key)
        try:
            xpr.ProposedProductionManifest(without, xpr._SEAL)
        except ValueError:
            omitted += 1
        else:
            problems.append(f"a proposal omitting {key!r} was accepted")
    refused("a proposal carrying an undeclared field", ValueError,
            lambda: xpr.ProposedProductionManifest(
                proposal.fields + (("extra_note", "hello"),), xpr._SEAL))
    refused("a proposal naming one field twice", ValueError,
            lambda: xpr.ProposedProductionManifest(
                proposal.fields + (("status", "checkpoint_blocked"),),
                xpr._SEAL))

    # Cross-field relationships, not merely per-field types.
    for label, key, value in (
            ("a grid spacing that is not the grid's", "grid_spacing", 0.5),
            ("a parity that is not the population's", "grid_parity", "odd"),
            ("a ladder that does not start at the timestep", "timestep_ladder",
             [0.004, 0.002, 0.001]),
            ("refinement cells outside the sweep", "refinement_couplings",
             [0.31, 0.42]),
            ("a refinement arm that is not an arm", "refinement_arm",
             "nobody"),
            ("a production status schema at the live version",
             "production_status_schema", rawled.MANIFEST_SCHEMA_VERSION),
            ("a blocked verdict with no blockers", "numerical_blockers", [])):
        mutated = tuple((name, value if name == key else held)
                        for name, held in proposal.fields)
        refused(label, ValueError,
                lambda m=mutated: xpr.ProposedProductionManifest(m, xpr._SEAL))

    refused("an approved status", ValueError,
            lambda: xpr.proposed_production_manifest(
                "probe", xpr.source_fingerprint(), _t07_matrix(), _t07_target(),
                _t07_power(), _t07_disposition(), _t07_search(), _t07_slowest(),
                _t07_resources(), _t07_firewall(), "probe",
                _t07_recovery(), _t07_plan(),
                status="checkpoint_one_approved"))
    other_target = xpr.SamplingTarget(
        0.30, 0.5, 0.5, 2.0, 6, 2.0, 1.25, "master_trial", _t07_envelopes(),
        0.05, 20000)
    refused("a proposal whose power estimate is about another target",
            ValueError,
            lambda: xpr.proposed_production_manifest(
                "probe", xpr.source_fingerprint(), _t07_matrix(), other_target,
                _t07_power(), _t07_disposition(), _t07_search(), _t07_slowest(),
                _t07_resources(), _t07_firewall(), "probe",
                recovery=_t07_recovery(), plan=_t07_plan()))
    refused("a proposal whose matrix does not carry the sized counts",
            ValueError,
            lambda: xpr.proposed_production_manifest(
                "probe", xpr.source_fingerprint(),
                _t07_matrix_with(arm_trials=(("full", 7),
                                             ("central_control", 7),
                                             ("width_only_control", 7)),
                                 trials_per_cell=7),
                _t07_target(), _t07_power(), _t07_disposition(), _t07_search(),
                _t07_slowest(), _t07_resources(), _t07_firewall(), "probe",
                recovery=_t07_recovery(), plan=_t07_plan()))

    # ---- one experiment, or a named refusal -------------------------------
    # An independent review multiplied every coupling of an otherwise valid,
    # honestly resource-priced six-node matrix by 1.1 and put it through the
    # proposal, the authoritative rebuild and the checkpoint.  All three
    # accepted it; the record said peak_couplings[0] = 0.55 beside
    # pilot_candidate_couplings[0] = 0.5.  Every join compared counts and
    # digests; none compared the physics the records share.
    scaled = tuple(value * 1.1 for value in _t07_target().couplings)
    off_matrix = _t07_matrix_with(
        couplings=scaled, refinement_couplings=(scaled[1], scaled[3]))
    per_row, fixed_bytes, peak_bytes = _t07_suite_maxima()
    off_resources = xpr.matrix_resource_estimate(
        off_matrix, _t07_slowest(), safety_factor=1.5, bytes_per_row=per_row,
        fixed_bytes=fixed_bytes, peak_bytes=peak_bytes)

    def off_grid(**changes):
        merged = dict(
            label="probe", fingerprint=xpr.source_fingerprint(),
            matrix=off_matrix, target=_t07_target(), power=_t07_power(),
            disposition=_t07_disposition(), search=_t07_search(),
            benchmark=_t07_slowest(), resources=off_resources,
            firewall=_t07_firewall(), status_reason="probe",
            recovery=_t07_recovery(), plan=_t07_plan())
        merged.update(changes)
        return merged

    refused("the review's 1.1x coupling grid at the proposal", ValueError,
            lambda: xpr.proposed_production_manifest(**off_grid()))
    refused("the review's 1.1x coupling grid at the authoritative rebuild",
            ValueError,
            lambda: xpr.require_authoritative_proposal(proposal,
                                                       **off_grid()))
    refused("the review's 1.1x coupling grid at the checkpoint", ValueError,
            lambda: xpr.checkpoint_one_handoff(
                label="probe", benchmarks=(_t07_slowest(),),
                target=_t07_target(), power=_t07_power(),
                recovery=_t07_recovery(), disposition=_t07_disposition(),
                search=_t07_search(), matrix=off_matrix,
                resources=off_resources, firewall=_t07_firewall(),
                proposal=proposal,
                plan=_t07_plan()))
    try:
        xpr.require_shared_physical_identity(_t07_target(), off_matrix,
                                             _t07_plan())
    except ValueError as exc:
        if "peak_couplings" not in str(exc):
            problems.append("the physical-identity refusal does not name the "
                            "disagreeing field")

    # One field at a time, across every shared physical field the records
    # carry, so the join cannot rot into a coupling-only comparison.
    for field, changes in (
            ("clocks", dict(clocks=32,
                            arm_clocks=(("full", 32),
                                        ("central_control", 1),
                                        ("width_only_control", 32)))),
            ("grid_half_width", dict(grid_half_width=2.5)),
            ("timestep", dict(timestep=_T07_TIMESTEP * 2.0,
                              timestep_ladder=(_T07_TIMESTEP * 2.0,
                                               _T07_TIMESTEP,
                                               _T07_TIMESTEP / 2.0))),
            ("pulse_duration", dict(pulse_duration=3.0)),
            ("pulse_centre", dict(pulse_centre=0.25)),
            ("phase_diffusion", dict(phase_diffusion=0.09)),
            ("lock_tolerance", dict(lock_tolerance=0.36)),
            ("dwell_time", dict(dwell_time=0.6)),
            ("shadow_fraction", dict(shadow_fraction=0.06)),
            ("pilot_arm", dict(refinement_arm="width_only_control"))):
        try:
            xpr.require_shared_physical_identity(
                _t07_target(), _t07_matrix_with(**changes), _t07_plan())
        except ValueError as exc:
            if field not in str(exc):
                problems.append(f"a matrix disagreeing on {field} was refused "
                                f"without naming it")
        except Exception as exc:                              # noqa: BLE001
            problems.append(f"a matrix disagreeing on {field} raised "
                            f"{type(exc).__name__}")
        else:
            problems.append(f"a matrix disagreeing on {field} was accepted; "
                            f"the shared-physical join compares counts and "
                            f"digests only")
    # The positive control: the coherent pre-pilot records agree.
    # ``_t07_target()`` builds a fresh record each call, so this compares the
    # value rather than the identity of the object it hands back.
    if xpr.require_shared_physical_identity(
            _t07_target(), _t07_matrix(),
            _t07_plan()).digest != _t07_target().digest:
        problems.append("the coherent pre-pilot records were refused")
    if sorted(xpr.shared_physical_identity(
            _t07_target(), _t07_matrix(),
            _t07_plan())) != sorted(xpr.SHARED_PHYSICAL_FIELDS):
        problems.append("the shared-physical table is not the declared field "
                        "set")

    # ---- the production doors take **the** approved pilot -----------------
    # An independent review built an eight-clock, dt=0.05, four-cell plan that
    # declared ``approved_production_pilot``, carried a run-name family with no
    # fixture marker, rebuilt from its own inputs consistently -- and drove the
    # production proposal.  Every rule it satisfied was a rule about
    # self-consistency; none of them asked which pilot it was.
    canonical = xpr.canonical_pilot_plan(_t07_firewall(),
                                         xpr.source_fingerprint())
    if canonical.digest != _t07_plan().digest:
        problems.append("the frozen pilot is not the canonical production plan")
    replay = xpr.pilot_plan(
        label=canonical.label, firewall=_t07_firewall(),
        fingerprint=xpr.source_fingerprint(),
        couplings=_t07_fixture_couplings(), clocks=8, grid_half_width=3.0,
        timestep=0.05, pulse_duration=4.0, pulse_centre=0.0,
        phase_diffusion=0.08, lock_tolerance=0.35, dwell_time=0.5,
        trials_per_cell=200, shadow_fraction=0.05,
        run_name_prefix="xpilot-t07-probe-cell",
        purpose="approved_production_pilot")
    refused("the review's eight-clock approved-purpose plan at a production "
            "door", ValueError,
            lambda: xpr.require_canonical_pilot_plan(
                replay, _t07_firewall(), xpr.source_fingerprint()))
    refused("that plan driving the production proposal", ValueError,
            lambda: xpr.proposed_production_manifest(
                label="probe", fingerprint=xpr.source_fingerprint(),
                matrix=_t07_matrix(), target=_t07_target(),
                power=_t07_power(), disposition=_t07_disposition(),
                search=_t07_search(), benchmark=_t07_slowest(),
                resources=_t07_resources(), firewall=_t07_firewall(),
                status_reason="probe", recovery=_t07_recovery(), plan=replay))
    # One field at a time, across every declared production-plan input.
    mutations = (("couplings", tuple(canonical.couplings[:5])),
                 ("clocks", 32), ("grid_half_width", 2.5),
                 ("timestep", canonical.timestep * 2.0),
                 ("pulse_duration", 3.0), ("pulse_centre", 0.25),
                 ("phase_diffusion", 0.09), ("lock_tolerance", 0.36),
                 ("dwell_time", 0.6), ("trials_per_cell", 199),
                 ("shadow_fraction", 0.06), ("label", "another pilot"),
                 ("run_name_prefix", "xpilot-t07-other"))
    inputs = dict(
        label=canonical.label, firewall=_t07_firewall(),
        fingerprint=xpr.source_fingerprint(), couplings=canonical.couplings,
        clocks=canonical.clocks, grid_half_width=canonical.grid_half_width,
        timestep=canonical.timestep, pulse_duration=canonical.pulse_duration,
        pulse_centre=canonical.pulse_centre,
        phase_diffusion=canonical.phase_diffusion,
        lock_tolerance=canonical.lock_tolerance,
        dwell_time=canonical.dwell_time,
        trials_per_cell=canonical.trials_per_cell,
        shadow_fraction=canonical.shadow_fraction,
        run_name_prefix=canonical.run_name_prefix,
        purpose="approved_production_pilot")
    for field, value in mutations:
        refused(f"a production plan whose {field} is not the approved pilot's",
                ValueError,
                lambda f=field, val=value: xpr.require_canonical_pilot_plan(
                    xpr.pilot_plan(**{**inputs, f: val}), _t07_firewall(),
                    xpr.source_fingerprint()))
    if xpr.require_canonical_pilot_plan(
            canonical, _t07_firewall(),
            xpr.source_fingerprint()) is not canonical:
        problems.append("the canonical plan did not survive its own identity "
                        "check")

    # ---- a post-range proposal fails closed, by name ----------------------
    # The review found this factory serializing two conflicting designs at
    # once: a four-cell post-range estimate calling for 8 419/22 211/8 419
    # trials per cell beside the supplied pre-pilot six-cell matrix carrying
    # 2 406/6 346/2 406, each with its own digest, in one record.  Deriving the
    # coherent post-range target, matrix and resources is ticket-08 work, so
    # the factory refuses by name until they exist.
    fixture_plan = _t07_fixture_plan()
    try:
        fixture_runs = _t07_pilot_fixture(fixture_plan)
        snapshot = xpr.post_range_plan(_t07_target(), fixture_plan,
                                       _t07_firewall(), fixture_runs)
        joined = xpr.post_range_power(_t07_target(), fixture_plan,
                                      _t07_firewall(), fixture_runs)
        if snapshot.status != "post_range_no_powered_matrix":
            problems.append(f"the fixture's post-range state is "
                            f"{snapshot.status!r}; it exceeds the declared "
                            f"affordability ceiling and must block")
        if joined.verdict == "powered":
            problems.append("a join over the ceiling reports 'powered'")
        # The inner power join, exercised through the factory's own private
        # helper, because no fixture plan may reach a production proposal.
        forged = dataclasses.replace(_t07_power(), stage="post_range_join",
                                     selection_digest="f" * 64)
        refused("a forged post-range power against the authoritative snapshot",
                ValueError,
                lambda: xpr._require_snapshot_power(forged, joined))
        refused("a provisional estimate against the authoritative snapshot",
                ValueError,
                lambda: xpr._require_snapshot_power(_t07_power(), joined))
        if xpr._require_snapshot_power(joined, joined) is not joined:
            problems.append("the authoritative estimate did not survive its "
                            "own comparison")
        if joined.digest != snapshot.power_digest:
            problems.append("the snapshot's power digest is not its own "
                            "estimate's")
        # The named fail-closed rule itself, exercised directly: the outer
        # canonical-plan gate means no fixture plan reaches the factory, and a
        # rule that cannot be reached cannot be trusted.
        refused("a post-range estimate beside the pre-pilot target and matrix",
                ValueError,
                lambda: xpr._require_post_range_design(
                    joined, _t07_target(), _t07_matrix()))
        try:
            xpr._require_post_range_design(joined, _t07_target(),
                                           _t07_matrix())
        except ValueError as exc:
            if xpr.POST_RANGE_MATRIX_NOT_DERIVED not in str(exc):
                problems.append("the fail-closed refusal does not name "
                                "post_range_matrix_not_derived")
        # The positive control: the pre-pilot design is coherent and passes.
        if xpr._require_post_range_design(
                _t07_power(), _t07_target(),
                _t07_matrix()).digest != _t07_power().digest:
            problems.append("the coherent pre-pilot design was refused by the "
                            "post-range design rule")
        # And the named fail-closed refusal, at all three doors.
        for door, call in (
                ("the proposal factory",
                 lambda: xpr.proposed_production_manifest(
                     label="probe", fingerprint=xpr.source_fingerprint(),
                     matrix=_t07_matrix(), target=_t07_target(), power=joined,
                     disposition=_t07_disposition(), search=_t07_search(),
                     benchmark=_t07_slowest(), resources=_t07_resources(),
                     firewall=_t07_firewall(), status_reason="probe",
                     recovery=_t07_recovery(), plan=fixture_plan,
                     pilot_run_names=fixture_runs)),
                ("the authoritative rebuild",
                 lambda: xpr.require_authoritative_proposal(
                     proposal, label=proposal.value("proposal_label"),
                     fingerprint=xpr.source_fingerprint(),
                     matrix=_t07_matrix(), target=_t07_target(), power=joined,
                     disposition=_t07_disposition(), search=_t07_search(),
                     benchmark=_t07_slowest(), resources=_t07_resources(),
                     firewall=_t07_firewall(),
                     status_reason=proposal.value("status_reason"),
                     recovery=_t07_recovery(), plan=fixture_plan,
                     pilot_run_names=fixture_runs)),
                ("the checkpoint handoff",
                 lambda: xpr.checkpoint_one_handoff(
                     label="probe", benchmarks=(_t07_slowest(),),
                     target=_t07_target(), power=joined,
                     recovery=_t07_recovery(), disposition=_t07_disposition(),
                     search=_t07_search(), matrix=_t07_matrix(),
                     resources=_t07_resources(), firewall=_t07_firewall(),
                     proposal=proposal,
                     plan=fixture_plan,
                     pilot_run_names=fixture_runs))):
            try:
                call()
            except ValueError as exc:
                if xpr.POST_RANGE_MATRIX_NOT_DERIVED not in str(exc) and \
                        "approved_production_pilot" not in str(exc):
                    problems.append(f"{door} refused a post-range record "
                                    f"without naming the reason: {exc}")
            except Exception as exc:                          # noqa: BLE001
                problems.append(f"{door} raised {type(exc).__name__}")
            else:
                problems.append(f"{door} accepted a post-range power estimate "
                                f"beside the pre-pilot matrix, serializing two "
                                f"conflicting designs in one record")
    finally:
        shutil.rmtree(PACKAGE_DIR / rawrun.RESULTS_DIRNAME
                      / xpr.QUARANTINE_DIRNAME, ignore_errors=True)

    xpr.require_unchanged_proposal(proposal, frozen)

    def rehashed(**changes):
        """A mutated proposal whose own design digest is recomputed.

        Necessary because the digest is now *inside* the record: a mutation
        that did not rehash would be refused at construction, which proves the
        recomputation and not the guard.  This rebuilds the freeze so the guard
        has a well-formed, differently-frozen record to reject.
        """
        body = tuple((name, changes.get(name, value))
                     for name, value in proposal.fields
                     if name != "design_digest")
        held = dict(body)
        design = xpr._digest({key: (list(held[key])
                                    if isinstance(held[key], tuple)
                                    else held[key])
                              for key in xpr.DESIGN_DIGEST_KEYS})
        return xpr.ProposedProductionManifest(
            body + (("design_digest", design),), xpr._SEAL)

    for label, changes in (
            ("a trial count edited after the freeze",
             {"trials_per_cell": 7,
              "arm_trials": [["full", 7], ["central_control", 7],
                             ["width_only_control", 7]]}),
            ("a *source* edited after the freeze", {"source_digest": "f" * 64}),
            ("an environment edited after the freeze",
             {"numpy_version": "0.0"}),
            ("the firewall edited after the freeze",
             {"firewall_digest": "e" * 64}),
            ("the reference-rate rule edited after the freeze",
             {"reference_rate_rule": xpr.REFERENCE_RATE_RULE}),
            ("the numerical budget edited after the freeze",
             {"numerical_budget_digest": "d" * 64})):
        try:
            mutated = rehashed(**changes)
        except (TypeError, ValueError):
            continue                        # refused even earlier: also fine
        if changes.get("reference_rate_rule") == xpr.REFERENCE_RATE_RULE:
            continue                        # the control: unchanged value
        refused(label, ValueError,
                lambda m=mutated: xpr.require_unchanged_proposal(m, frozen))
        if mutated.design_digest == frozen:
            problems.append(f"{label} left the design digest unchanged")

    # The four ways a caller can try to make one of these without the factory.
    refused("a proposal built by the public constructor", TypeError,
            lambda: xpr.ProposedProductionManifest(proposal.fields))
    refused("a proposal built by dataclasses.replace", TypeError,
            lambda: dataclasses.replace(proposal, fields=proposal.fields))
    refused("a proposal built by copy.replace-style reconstruction", TypeError,
            lambda: type(proposal)(proposal.fields))
    duplicate = copy.deepcopy(proposal)
    if duplicate.design_digest != frozen:
        problems.append("a deep copy of a proposal has a different freeze")

    if _t07_proposal().design_digest != frozen:
        problems.append("rebuilding the same proposal changed its design "
                        "digest; the reproducible freeze is not reproducible")
    for key in ("benchmark_digest", "resource_digest"):
        if key in xpr.DESIGN_DIGEST_KEYS:
            problems.append(f"the wall-time-bearing {key} is inside the "
                            f"reproducible design freeze")
    for key in ("source_digest", "python_version", "numpy_version", "platform",
                "firewall_digest", "selection_digest",
                "pilot_ledger_fingerprints", "fixed_contraction_rate",
                "reference_rate_rule", "numerical_budget_digest",
                "evidence_digest", "search_digest", "power_digest",
                "matrix_digest", "arm_trials",
                "measured_arm_latent_correlation"):
        if key not in xpr.DESIGN_DIGEST_KEYS:
            problems.append(f"{key} is outside the design freeze")
    if sorted(set(xpr.PROPOSED_MANIFEST_KEYS)
              - set(xpr.DESIGN_DIGEST_KEYS)) != \
            sorted(set(xpr.DESIGN_DIGEST_EXCLUSIONS)):
        problems.append("the design freeze excludes something undeclared")
    # The measured correlation and the frozen floor are two named things.
    # The durable component-source map covers the exact field set, agrees with
    # the design freeze, and classifies only genuine free text as free text.
    mapped = set(xpr.PROPOSAL_FIELD_SOURCES)
    declared = set(xpr.PROPOSED_MANIFEST_KEYS)
    if mapped != declared:
        problems.append(f"the component-source map misses "
                        f"{sorted(declared - mapped)} and carries "
                        f"{sorted(mapped - declared)}")
    if len(xpr.PROPOSAL_FIELD_SOURCES) != len(xpr.PROPOSED_MANIFEST_KEYS):
        problems.append("the component-source map has a duplicate")
    free = sorted(key for key, (_, kind) in xpr.PROPOSAL_FIELD_SOURCES.items()
                  if kind == "free_text")
    if free != ["proposal_label", "status_reason"]:
        problems.append(f"the free-text classification is {free}; only a "
                        f"human description of the record may be free text")
    for key, (_, kind) in xpr.PROPOSAL_FIELD_SOURCES.items():
        if kind not in ("derived", "free_text"):
            problems.append(f"{key} has an unknown classification {kind!r}")
    # Every free-text field is *outside* the rebuild's comparison in the sense
    # that the rebuild takes it from the record; every other field is derived
    # and must therefore be inside the design freeze unless it is one of the
    # five declared exclusions.
    for key, (_, kind) in xpr.PROPOSAL_FIELD_SOURCES.items():
        inside = key in xpr.DESIGN_DIGEST_KEYS
        expected = key not in xpr.DESIGN_DIGEST_EXCLUSIONS
        if inside != expected:
            problems.append(f"{key} is {'in' if inside else 'out of'} the "
                            f"design freeze against the declared exclusions")
    if not xpr.SEAL_IS_NOT_THE_AUTHORITY:
        problems.append("the seal statement is empty")

    if proposal.value("measured_arm_latent_correlation") == \
            proposal.value("contrast_covariance_floor"):
        problems.append("the measured arm correlation and the frozen "
                        "covariance floor are the same number, so one of them "
                        "is being presented as the other")

    return Result("the proposal is factory-only, semantically validated field "
                  "by field, and frozen by a measurement-free design digest",
                  not problems, float(len(problems)), 0.0,
                  (f"{len(xpr.PROPOSED_MANIFEST_KEYS)} declared fields, every "
                   f"one required — {omitted} single-field omissions each "
                   f"refused — and every one of them additionally refused when "
                   f"given a wrong value of the wrong kind, with the factory "
                   f"seal present.  The review's complete "
                   f"'wrong-but-json-valid' record is refused twice over, "
                   f"unsealed and sealed.  Seven cross-field relationships are "
                   f"checked, an approved status is refused, the power, matrix "
                   f"and benchmark joins each refuse a substituted record, and "
                   f"a single edited field changes the design digest and fails "
                   f"the post-freeze guard.  The design freeze "
                   f"{frozen[:16]}... covers "
                   f"{len(xpr.DESIGN_DIGEST_KEYS)} declared fields and no "
                   f"measurement, so rebuilding the proposal reproduces it")
                  if not problems else "; ".join(problems[:6]), covers=(117,))


@check("the checkpoint-1 handoff derives its own verdict and carries "
       "one blocked unpriced option and one machinery-only diagnostic, "
       "neither of which is running the pilot",
       covers=[118])
def check_checkpoint_handoff():
    """The one place the answer is assembled, and it is not a caller's to give.

    An independent review's judgement for presentation: do not put an
    unqualified no-feasible conclusion to John, and present the alternatives
    beside the narrower statement.  Both are structural here.  ``feasibility``
    is derived from the search, the disposition, the power verdict and the
    matrix's own eligible-clock count — there is no parameter for it — and a
    handoff that does not carry **both** declared alternatives is refused.
    """
    problems = []
    refused = _t07_refuser(problems)
    handoff = _t07_handoff()
    summary = handoff.summary()

    if handoff.feasibility != "no_feasible_matrix_among_searched":
        problems.append(f"the handoff reports {handoff.feasibility!r}")
    if handoff.proposal.status != "checkpoint_blocked":
        problems.append("the proposal is not blocked")
    if summary["numerical_verdict"] != "numerical_no_result":
        problems.append("the summary does not report the numerical no-result")
    if summary["time_admissible"]:
        problems.append("the summary reports the time rows as admissible")
    if summary["probability_admissible_trials"] >= \
            summary["paired_trials_per_cell"]:
        problems.append("the summary does not show an empty probability "
                        "window")
    if summary["projected_cube_margin"] < 100.0:
        problems.append(f"the projected cube margin "
                        f"{summary['projected_cube_margin']:.1f} is too small "
                        f"to be evidence that streaming bought anything")
    if summary["power_stage"] != "provisional_pre_pilot":
        problems.append("the summary does not mark the design provisional")

    labels = sorted(item.label for item in handoff.alternatives)
    if labels != sorted(xpr.ALTERNATIVE_LABELS):
        problems.append(f"the handoff offers {labels}")
    for item in handoff.alternatives:
        if item.is_priced and item.cost.wall_hours <= 0.0:
            problems.append(f"{item.label} is priced at nothing")
    validation = handoff.alternative("intended_configuration_validation")
    if validation.is_priced:
        problems.append("the validation outline is presented as costed; its "
                        "kernels omit the observation generation entirely")
    if "unpriced" not in validation.summary:
        problems.append("the validation outline does not say it is unpriced")
        if not item.prerequisites:
            problems.append(f"{item.label} has no prerequisites")
    narrowed = handoff.alternative("narrowed_claim")
    bound = xpr.row_width_bound(35, _t07_matrix().clocks,
                                _t07_matrix().steps_at(_T07_TIMESTEP))
    if abs(narrowed.cost.bytes_per_row - bound["blended"]) > 1e-9:
        problems.append(f"the narrowed option is priced at "
                        f"{narrowed.cost.bytes_per_row:.3f} bytes per row, not "
                        f"at its own intended-configuration bound "
                        f"{bound['blended']:.3f}; an independent review found "
                        f"it using the small timing fixture's coefficient")
    if narrowed.cost.bytes_per_row <= max(
            item.bytes_per_row for item in handoff.benchmarks):
        problems.append("the narrowed option's coefficient is no larger than "
                        "the small-fixture measurement it replaced")
    if narrowed.cost.rows != 29268 or narrowed.cost.runs != 18:
        problems.append(f"the narrowed option is {narrowed.cost.runs} runs and "
                        f"{narrowed.cost.rows:.0f} rows, not the declared "
                        f"18 primary runs and 29268 rows")
    if "machinery" not in narrowed.supports:
        problems.append("the narrowed alternative claims more than machinery")
    for forbidden in ("Born", "detector", "unique actuality",
                      "production_cleared"):
        for item in handoff.alternatives:
            if forbidden in item.supports or forbidden in item.summary:
                problems.append(f"{item.label} names {forbidden!r}")

    # Every direct construction below goes through the record's real field
    # set, which no longer has a ``feasibility``, ``alternatives`` or
    # ``pilot_line`` entry: those are derived properties now.
    handoff_fields = {name: getattr(handoff, name)
                      for name in xpr.Checkpoint1Handoff.__dataclass_fields__
                      if name != "seal"}

    def built(**changes):
        merged = dict(handoff_fields)
        merged.update(changes)
        return lambda: xpr.Checkpoint1Handoff(**merged,
                                              seal=xpr._CHECKPOINT_SEAL)

    refused("a handoff with no measured benchmark", ValueError,
            built(benchmarks=()))

    # ---- the record type itself is not a caller's to mint -----------------
    # A later independent review went around the parameter closure below by
    # constructing ``Checkpoint1Handoff`` **directly**: every component the
    # canonical helpers build, and Option B's own comparison ``CostLine`` where
    # the approved pilot's belonged.  ``summary()`` then reported the pilot at
    # Option B's hours, storage and rows.  An alignment review then pointed out
    # that sealing the record was not enough on its own -- a seal is ordinary
    # module state, and a caller who reaches it calls the public ``summary()``
    # without ever presenting the record to a door.
    #
    # So the three values a caller could choose are **not fields**.  There is
    # nothing to substitute: the substitution below is not refused, it is
    # *unexpressible*, and that is what these probes assert.
    for name in ("feasibility", "alternatives", "pilot_line"):
        if name in xpr.Checkpoint1Handoff.__dataclass_fields__:
            problems.append(f"{name!r} is still a field of Checkpoint1Handoff, "
                            f"so a caller who reaches the construction token "
                            f"can still choose what the record presents")
        if not isinstance(vars(xpr.Checkpoint1Handoff).get(name), property):
            problems.append(f"{name!r} is not a derived property of "
                            f"Checkpoint1Handoff")
        refused(f"a directly built checkpoint supplying {name!r}", TypeError,
                built(**{name: None}))
    # Every other cost line in this evidence, not only the review's: the
    # matrix's own lines and Option B's, each of which is a real, correctly
    # built ``CostLine`` describing something that is not the approved pilot.
    # None of them can be attached to a checkpoint at all now, so what is
    # asserted is that a sealed record built beside each of them still
    # presents the pilot's own numbers.
    other_lines = tuple(_t07_resources().lines) + \
        tuple(_t07_alternatives()[1].cost.lines)
    if not other_lines:
        problems.append("no alternative cost line was available, so the "
                        "substitution replay proves nothing")
    derived_line = xpr.pilot_cost_from_plan(
        _t07_plan(),
        sorted(handoff.benchmarks,
               key=lambda item: item.clock_steps_per_second)[0],
        _t07_resources().safety_factor)
    for index, line in enumerate(other_lines):
        if line.digest == derived_line.digest:
            continue                    # the pilot's own line is not a forgery
        refused(f"a directly built checkpoint carrying cost line {index} "
                f"where the approved pilot's belongs", TypeError,
                built(pilot_line=line))
        refused(f"a sealed checkpoint carrying cost line {index}", TypeError,
                lambda ln=line: xpr.Checkpoint1Handoff(
                    **handoff_fields, pilot_line=ln,
                    seal=xpr._CHECKPOINT_SEAL))
    # **The reachable seal buys nothing.**  This is the alignment review's
    # exact route: take the canonical fields, reach the token, build, and call
    # the public ``summary()`` immediately, presenting the record to no door.
    reachable = xpr.Checkpoint1Handoff(**handoff_fields,
                                       seal=xpr._CHECKPOINT_SEAL)
    if reachable.summary() != handoff.summary() or \
            reachable.digest != handoff.digest:
        problems.append("a record built through the reachable seal presents "
                        "something other than what its own components imply")
    if reachable.pilot_line.digest != derived_line.digest:
        problems.append("a record built through the reachable seal presents a "
                        "pilot line that is not the frozen plan's own")
    # ``dataclasses.replace`` preserves the dynamic class and re-runs
    # ``__post_init__``; there is no derived field for it to replace, and the
    # seal it cannot carry stops it anyway.
    refused("a dataclasses.replace of the checkpoint", TypeError,
            lambda: dataclasses.replace(handoff, label="relabelled"))

    class _ShadowHandoff(xpr.Checkpoint1Handoff):
        """A subclass, which could answer ``summary`` with whatever it liked."""

        def summary(self):
            merged = dict(super().summary())
            merged["pilot_wall_hours"] = 0.25
            return merged

    refused("a Checkpoint1Handoff subclass at the authority door", TypeError,
            lambda: xpr._require_authoritative_checkpoint(
                _ShadowHandoff(**handoff_fields, seal=xpr._CHECKPOINT_SEAL),
                **_t07_handoff_components()))
    # A component the canonical proposal did not freeze cannot be bound in,
    # so the derivation cannot be pointed at a different experiment.
    other_matrix = _t07_matrix_with(
        label=_t07_matrix().label + " (a different matrix)")
    for field, other in (("plan", _t07_fixture_plan()),
                         ("matrix", other_matrix),
                         ("resources", xpr.matrix_resource_estimate(
                             other_matrix, _t07_slowest(),
                             _t07_resources().safety_factor))):
        refused(f"a sealed checkpoint whose {field} is not the one the "
                f"proposal froze", ValueError, built(**{field: other}))
    refused("an authoritative rebuild of a checkpoint built from another "
            "label", ValueError,
            lambda: xpr._require_authoritative_checkpoint(
                xpr.Checkpoint1Handoff(**{**handoff_fields,
                                          "label": "a different checkpoint"},
                                       seal=xpr._CHECKPOINT_SEAL),
                **_t07_handoff_components()))
    # The derived verdict cannot be friendlier than the components allow.
    if handoff.feasibility == "feasible_matrix" and \
            _t07_disposition().is_blocking:
        problems.append("the derived feasibility is 'feasible_matrix' over a "
                        "blocking numerical disposition")
    if sorted(item.label for item in handoff.alternatives) != \
            sorted(xpr.ALTERNATIVE_LABELS):
        problems.append("the derived alternatives are not both declared "
                        "options")
    # ---- the derivation's *inputs* are bound too ---------------------------
    # A second alignment review found the outputs derived and two inputs still
    # a caller's.  The slowest benchmark prices the pilot line, Option B and
    # the presented rate, and nothing compared it with the benchmark the
    # proposal froze; and Option A was built from a caller-supplied campaign
    # the 86-field proposal does not freeze at all.
    frozen_benchmark = _t07_proposal().value("benchmark_digest")
    if handoff.summary()["authoritative_benchmark_digest"] != frozen_benchmark:
        problems.append("the presented authoritative benchmark is not the one "
                        "the proposal froze")

    def benchmark_at(seconds):
        """The slowest benchmark's own fixture, timed differently."""
        source = _t07_slowest()
        return xpr.BenchmarkResult(
            **{**{name: getattr(source, name)
                  for name in
                  inspect.signature(xpr.BenchmarkResult).parameters},
               "repeat_seconds": seconds})

    slower = benchmark_at(tuple(_t07_slowest().repeat_seconds)
                          if isinstance(_t07_slowest().repeat_seconds, tuple)
                          else _t07_slowest().repeat_seconds)
    # A measurement slower than the frozen one becomes ``_slowest`` and is
    # therefore refused: it would reprice the pilot and Option B.
    for label, seconds in (("slower", tuple(value * 4.0 for value in
                                            _t07_slowest().repeat_seconds)),):
        refused(f"a sealed checkpoint whose {label} benchmark is not the one "
                f"the proposal froze", ValueError,
                built(benchmarks=(benchmark_at(seconds),)))
        refused(f"a sealed checkpoint carrying a {label} benchmark beside the "
                f"frozen one", ValueError,
                built(benchmarks=handoff.benchmarks
                      + (benchmark_at(seconds),)))
    # A measurement *faster* than the frozen one does not become ``_slowest``,
    # so it cannot reprice anything; and the two aggregates it can move are
    # maxima, so it can only make the presented evidence more conservative.
    faster = benchmark_at(tuple(value / 4.0
                                for value in _t07_slowest().repeat_seconds))
    extended = xpr.Checkpoint1Handoff(
        **{**handoff_fields, "benchmarks": handoff.benchmarks + (faster,)},
        seal=xpr._CHECKPOINT_SEAL)
    if extended.pilot_line.digest != handoff.pilot_line.digest:
        problems.append("an added faster benchmark repriced the pilot line")
    if [item.digest for item in extended.alternatives] != \
            [item.digest for item in handoff.alternatives]:
        problems.append("an added faster benchmark changed an alternative")
    if extended.feasibility != handoff.feasibility:
        problems.append("an added faster benchmark changed the verdict")
    for key in ("pilot_wall_hours", "pilot_storage_bytes",
                "pilot_durable_rows", "walked_clock_steps_per_second",
                "authoritative_benchmark_digest"):
        if extended.summary()[key] != handoff.summary()[key]:
            problems.append(f"an added faster benchmark changed the presented "
                            f"{key}")
    if extended.summary()["projected_cube_margin"] > \
            handoff.summary()["projected_cube_margin"]:
        problems.append("an added benchmark widened the projected cube "
                        "margin; a supplied measurement may only make this "
                        "evidence more conservative")
    if faster.digest not in extended.summary()["supplied_benchmark_digests"]:
        problems.append("a supplied benchmark is not listed in the presented "
                        "provenance")
    # Order is not evidence: the record sorts, so a reordered tuple is the
    # same checkpoint.
    reordered = xpr.Checkpoint1Handoff(
        **{**handoff_fields,
           "benchmarks": tuple(reversed(handoff.benchmarks))},
        seal=xpr._CHECKPOINT_SEAL)
    if reordered.pilot_line.digest != handoff.pilot_line.digest:
        problems.append("reordering the benchmark tuple repriced the pilot")

    # ---- and Option A takes nothing at all --------------------------------
    if "campaign" in xpr.Checkpoint1Handoff.__dataclass_fields__:
        problems.append("the checkpoint still carries a campaign the "
                        "proposal does not freeze")
    for name, function in (("checkpoint_one_handoff", xpr.checkpoint_one_handoff),
                           ("checkpoint_alternatives",
                            xpr.checkpoint_alternatives),
                           ("intended_configuration_option",
                            xpr.intended_configuration_option)):
        if "campaign" in inspect.signature(function).parameters:
            problems.append(f"{name} must not take a campaign; a caller could "
                            f"otherwise reach Option A's presented text")
    option_a = xpr.intended_configuration_option()
    if option_a.digest != handoff.alternative(
            "intended_configuration_validation").digest:
        problems.append("the presented Option A is not the one "
                        "intended_configuration_option builds from nothing")
    if option_a.is_priced or option_a.cost is not None:
        problems.append("Option A is priced")

    # ---- no undeclared instance state, on the exact type ------------------
    # An alignment review poisoned a genuine handoff with an instance-attribute
    # ``summary`` -- a plain method is a non-data descriptor, so the instance
    # dictionary wins -- and the authority door, comparing fields and digests,
    # returned the poisoned object.  The record is slotted now, so there is no
    # dictionary to write into: every one of these raises at the assignment.
    if hasattr(handoff, "__dict__"):
        problems.append("Checkpoint1Handoff instances carry a dictionary "
                        "again, so any method on them can be shadowed")
    if not hasattr(xpr.Checkpoint1Handoff, "__slots__"):
        problems.append("Checkpoint1Handoff is not slotted")
    declared = set(xpr.Checkpoint1Handoff.__dataclass_fields__)
    if set(getattr(xpr.Checkpoint1Handoff, "__slots__", ())) != declared:
        problems.append("the checkpoint's slots are not exactly its declared "
                        "fields")
    # Every dynamically consumed member, one at a time, including the review's
    # exact case.
    for member in ("summary", "digest", "alternative", "feasibility",
                   "alternatives", "pilot_line", "_slowest", "__dict__",
                   "review_rogue_attribute"):
        refused(f"installing an instance attribute {member!r} on a genuine "
                f"handoff", AttributeError,
                lambda name=member: object.__setattr__(
                    handoff, name, lambda *a, **k: None))
    refused("the review's exact poisoned summary", AttributeError,
            lambda: object.__setattr__(
                handoff, "summary",
                lambda: {"pilot_wall_hours": 1 / 3600,
                         "ticket_08_authorization_status": "authorized"}))
    if xpr._require_no_undeclared_state(handoff) is not handoff:
        problems.append("the no-undeclared-state door did not return the "
                        "record it was given")

    class _DictHandoff(xpr.Checkpoint1Handoff):
        """A subclass reinstates the dictionary the exact type does not have."""

    poisoned = _DictHandoff(**handoff_fields, seal=xpr._CHECKPOINT_SEAL)
    object.__setattr__(poisoned, "summary",
                       lambda: {"pilot_wall_hours": 1 / 3600})
    if poisoned.summary()["pilot_wall_hours"] == \
            handoff.summary()["pilot_wall_hours"]:
        problems.append("the subclass shadow did not take effect, so this "
                        "replay does not exercise the finding")
    refused("a poisoned subclass at the authority door", TypeError,
            lambda: xpr._require_authoritative_checkpoint(
                poisoned, **_t07_handoff_components()))
    refused("a poisoned subclass at the unchanged-digest door", TypeError,
            lambda: xpr._require_unchanged_checkpoint(poisoned,
                                                      handoff.digest))
    refused("a poisoned subclass at the no-undeclared-state door", TypeError,
            lambda: xpr._require_no_undeclared_state(poisoned))

    # The positive controls: the factory's own record survives both doors, the
    # authority door returns its **own rebuild** rather than what it was given,
    # and the pilot line presented is exactly what the frozen plan implies.
    rebuilt = xpr._require_authoritative_checkpoint(
        handoff, **_t07_handoff_components())
    if rebuilt is handoff:
        problems.append("the authority door returned the object it was "
                        "handed; a boundary that authorizes something must "
                        "not forward the caller's record")
    if type(rebuilt) is not xpr.Checkpoint1Handoff or \
            rebuilt.digest != handoff.digest or \
            rebuilt.summary() != handoff.summary():
        problems.append("the factory's own handoff did not survive its "
                        "authoritative rebuild")
    if hasattr(rebuilt, "__dict__"):
        problems.append("the record the authority door returns carries a "
                        "dictionary")
    if xpr._require_unchanged_checkpoint(handoff,
                                         handoff.digest) is not handoff:
        problems.append("the factory's own handoff did not survive the "
                        "unchanged-digest door")
    refused("an unchanged-digest door given another record's digest",
            ValueError,
            lambda: xpr._require_unchanged_checkpoint(
                handoff, other_lines[0].digest))
    if handoff.pilot_line.digest != derived_line.digest:
        problems.append("the handoff's pilot line is not the one "
                        "pilot_cost_from_plan builds from the frozen plan and "
                        "the slowest measured benchmark")
    for key, value in (("pilot_wall_hours",
                        derived_line.wall_seconds / 3600.0),
                       ("pilot_storage_bytes", derived_line.storage_bytes),
                       ("pilot_durable_rows", derived_line.durable_rows)):
        if handoff.summary()[key] != value:
            problems.append(f"the presented {key} is not the derived pilot "
                            f"line's own value")

    # ---- the review's two forged decisions, and why neither can arrive -----
    # It handed this boundary genuine components and substituted a *costed*
    # Option A whose ``supports`` string was "a physical scaling claim", plus a
    # pilot cost line of one second, and the checkpoint accepted both.  The
    # closure is that there is nowhere to hand either in, and that neither
    # record can be built even in isolation.
    signature = inspect.signature(xpr.checkpoint_one_handoff).parameters
    for parameter in ("seal", "ticket_08_derivation_status",
                      "ticket_08_authorization_status"):
        if parameter in signature:
            problems.append(f"checkpoint_one_handoff takes a {parameter!r} "
                            f"parameter, so a caller can reach past the "
                            f"derivation")
    for parameter in ("alternatives", "pilot_line"):
        if parameter in signature:
            problems.append(f"checkpoint_one_handoff still takes a "
                            f"{parameter!r} parameter, so the decision it "
                            f"presents is still a caller's to give")
    for parameter in ("plan",):
        if parameter not in signature:
            problems.append(f"checkpoint_one_handoff does not take "
                            f"{parameter!r}, so it cannot rebuild the decision")
    refused("a costed intended-configuration option", ValueError,
            lambda: xpr.CheckpointAlternative(
                label="intended_configuration_validation", summary="s",
                supports="a physical scaling claim",
                supports_class="unpriced_no_claim",
                cost=_t07_alternatives()[1].cost, prerequisites=("p",)))
    refused("an intended-configuration option claiming a physical scaling "
            "claim", ValueError,
            lambda: xpr.CheckpointAlternative(
                label="intended_configuration_validation", summary="s",
                supports="a physical scaling claim",
                supports_class="a physical scaling claim", cost=None,
                prerequisites=("p",)))
    refused("an unpriced narrowed claim", ValueError,
            lambda: xpr.CheckpointAlternative(
                label="narrowed_claim", summary="s", supports="m",
                supports_class="machinery_and_diagnostic_only", cost=None,
                prerequisites=("p",)))
    refused("a narrowed claim borrowing the unpriced support class",
            ValueError,
            lambda: xpr.CheckpointAlternative(
                label="narrowed_claim", summary="s", supports="m",
                supports_class="unpriced_no_claim",
                cost=_t07_alternatives()[1].cost, prerequisites=("p",)))
    # ---- the Option framing criterion 118 claims, pinned mechanically ------
    # An independent review found criterion 118 still saying "both costed
    # alternatives" while the accepted contract is one **unpriced** outline
    # and one priced machinery-only diagnostic.  The text is corrected; so
    # that the correction cannot drift back, the contract itself is written
    # out here and compared, and each half is exercised by altering it.
    option_contract = {
        "intended_configuration_validation": ("unpriced_no_claim", False),
        "narrowed_claim": ("machinery_and_diagnostic_only", True),
    }

    def contract_problems(contract):
        """Every way ``contract`` departs from the accepted Option framing."""
        found = []
        if dict(contract) != option_contract:
            found.append(f"the alternative contract is {dict(contract)} and "
                         f"criterion 118 pins {option_contract}")
        return found

    problems.extend(contract_problems(xpr.ALTERNATIVE_CONTRACT))
    for label, altered in (
            ("Option A priced",
             {**option_contract,
              "intended_configuration_validation": ("unpriced_no_claim",
                                                    True)}),
            ("Option B unpriced",
             {**option_contract,
              "narrowed_claim": ("machinery_and_diagnostic_only", False)}),
            ("Option A relabelled as a diagnostic",
             {**option_contract,
              "intended_configuration_validation":
                  ("machinery_and_diagnostic_only", False)}),
            ("a third alternative",
             {**option_contract, "review_rogue_option": ("unpriced_no_claim",
                                                         False)})):
        if not contract_problems(altered):
            problems.append(f"{label} is not detected, so the one-unpriced / "
                            f"one-priced framing criterion 118 claims is not "
                            f"mechanically pinned")
    if "both costed alternatives" in ACCEPTANCE_CRITERIA[118]:
        problems.append("criterion 118 still says both alternatives are "
                        "costed; Option A is explicitly unpriced and Option B "
                        "is the one priced machinery-only diagnostic")
    for item in handoff.alternatives:
        expected, priced = xpr.ALTERNATIVE_CONTRACT[item.label]
        if item.supports_class != expected or item.is_priced != priced:
            problems.append(f"{item.label} is {item.supports_class!r} and "
                            f"{'priced' if item.is_priced else 'unpriced'}")
    # The one-second pilot line.  The handoff derives it from the frozen plan,
    # so it is the plan's own cost and not a number beside it.
    plan = _t07_plan()
    derived = xpr.pilot_cost_from_plan(
        plan,
        sorted(handoff.benchmarks,
               key=lambda item: item.clock_steps_per_second)[0],
        handoff.resources.safety_factor)
    if handoff.pilot_line.digest != derived.digest:
        problems.append("the handoff's pilot line is not the one the frozen "
                        "plan and the slowest measured benchmark imply")
    if handoff.pilot_line.runs != plan.cells or \
            handoff.pilot_line.physical_trials != \
            plan.cells * plan.trials_per_cell:
        problems.append(f"the pilot line prices "
                        f"{handoff.pilot_line.runs} runs and "
                        f"{handoff.pilot_line.physical_trials} trials against "
                        f"the plan's {plan.cells} cells at "
                        f"{plan.trials_per_cell} trials")
    if handoff.pilot_line.wall_seconds <= 1.0:
        problems.append(f"the derived pilot line costs "
                        f"{handoff.pilot_line.wall_seconds} s, which is the "
                        f"fictitiously cheap line the review injected")
    if handoff.summary()["pilot_wall_hours"] is None:
        problems.append("the checkpoint summary hides the pilot's cost")

    # ---- ticket 08's derivation is stated, not left to be inferred --------
    summary = handoff.summary()
    if handoff.ticket_08_derivation_status != "not_started":
        problems.append(f"the checkpoint reports ticket-08 derivation as "
                        f"{handoff.ticket_08_derivation_status!r}")
    if summary.get("ticket_08_derivation_status") != "not_started":
        problems.append("the checkpoint summary does not carry the ticket-08 "
                        "derivation status")
    if "post_range_production_proposal" not in summary or \
            summary["post_range_production_proposal"] is not None:
        problems.append("the summary does not state that no post-range "
                        "production proposal exists")
    if handoff.ticket_08_authorization_status != "not_authorized":
        problems.append(f"the checkpoint reports ticket-08 authorization as "
                        f"{handoff.ticket_08_authorization_status!r}")
    # All three observable facts, together, in the summary a reader reads.
    for key, expected in (("ticket_08_derivation_status", "not_started"),
                          ("ticket_08_authorization_status", "not_authorized"),
                          ("post_range_production_proposal", None)):
        if key not in summary:
            problems.append(f"the checkpoint summary omits {key!r}")
        elif summary[key] != expected:
            problems.append(f"the summary reports {key}={summary[key]!r} "
                            f"rather than {expected!r}")
    for vocabulary, name in (
            (xpr.TICKET_08_DERIVATION_STATUSES,
             "TICKET_08_DERIVATION_STATUSES"),
            (xpr.TICKET_08_AUTHORIZATION_STATUSES,
             "TICKET_08_AUTHORIZATION_STATUSES")):
        if len(vocabulary) != 1:
            problems.append(f"{name} has grown a value this ticket cannot "
                            f"produce")
    if "ticket_08_authorization_status" in inspect.signature(
            xpr.checkpoint_one_handoff).parameters:
        problems.append("the ticket-08 authorization status is a caller's to "
                        "supply rather than derived")
    # Every alternate spelling, including the one that matters.
    def authorized_as(value):
        return built(ticket_08_authorization_status=value)

    for bad in ("authorized", "AUTHORIZED", "not_started",
                "conditionally_authorized", ""):
        refused(f"a checkpoint whose ticket-08 authorization is {bad!r}",
                ValueError, authorized_as(bad))
    for bad in (None, True, 1):
        refused(f"a checkpoint whose ticket-08 authorization is {bad!r}",
                TypeError, authorized_as(bad))
    if "ticket_08_derivation_status" in inspect.signature(
            xpr.checkpoint_one_handoff).parameters:
        problems.append("the ticket-08 derivation status is a caller's to "
                        "supply rather than derived")
    # **The presented sentence, not only the fields.**  An independent review
    # handed the factory coherent authoritative components and the caller text
    # "approve the presented choice"; every derived field was right and the
    # sentence a reader is shown said none of it.  There is no parameter now,
    # and the text is compared exactly against the canonical constant.
    if "requested_decision" in inspect.signature(
            xpr.checkpoint_one_handoff).parameters:
        problems.append("checkpoint_one_handoff still takes a "
                        "requested_decision, so the sentence a reader is "
                        "shown is still a caller's to write")
    if handoff.requested_decision != xpr.CHECKPOINT_REQUESTED_DECISION:
        problems.append("the handoff presents a decision text that is not the "
                        "canonical one")
    for clause in xpr.CHECKPOINT_DECISION_CLAUSES:
        if clause not in handoff.requested_decision:
            problems.append(f"the presented decision omits {clause!r}")
    if len(xpr.CHECKPOINT_DECISION_CLAUSES) != 3:
        problems.append("the checkpoint clause set is no longer the three "
                        "invariants a reader must be shown")
    # The review's exact replacement, and the omission of each clause on its
    # own -- none of which the type can express.
    def presenting(text):
        return built(requested_decision=text)

    refused("the review's replacement decision text", ValueError,
            presenting("approve the presented choice"))
    for clause in xpr.CHECKPOINT_DECISION_CLAUSES:
        refused(f"a decision text omitting {clause!r}", ValueError,
                presenting(xpr.CHECKPOINT_REQUESTED_DECISION.replace(
                    clause + "  ", "", 1)))
    # And a text that merely drops the non-authorization sentence.
    refused("a decision text dropping the non-authorization statement",
            ValueError,
            presenting(xpr.CHECKPOINT_REQUESTED_DECISION.split(
                "  The last two")[0]))
    refused("a checkpoint claiming ticket-08 derivation has started",
            ValueError, built(ticket_08_derivation_status="in_progress"))

    if handoff.proposal.value("non_claims") != list(xpr.EXPERIMENT_NON_CLAIMS):
        problems.append("the proposal does not carry the non-claims")

    option_a = handoff.alternative("intended_configuration_validation")
    return Result("the checkpoint-1 handoff derives its own verdict and "
                  "carries one blocked unpriced option and one "
                  "machinery-only diagnostic, neither of which is running the "
                  "pilot", not problems, float(len(problems)), 0.0,
                  (f"feasibility {handoff.feasibility!r} derived from a "
                   f"{handoff.search.verdict!r} search over "
                   f"{handoff.search.searched} declared options and a "
                   f"{handoff.disposition.verdict!r} disposition; "
                   f"{len(handoff.benchmarks)} measured benchmarks carried, "
                   f"and a handoff with none is refused.  Provisional design: "
                   f"{summary['arm_trials']} trials per cell by arm, "
                   f"{summary['physical_trial_executions']} physical trial "
                   f"executions and {summary['shadow_rewalks']} shadow "
                   f"rewalks over {summary['durable_rows']:.0f} durable rows, "
                   f"{summary['matrix_wall_hours']:.0f} h and "
                   f"{summary['matrix_storage_bytes'] / 1e6:.0f} MB if it "
                   f"ran.  Probability window "
                   f"{summary['probability_admissible_trials']} against "
                   f"{summary['paired_trials_per_cell']} needed, and the time "
                   f"rows admissible: {summary['time_admissible']}.  Two "
                   f"alternatives, neither of them the pilot and neither of "
                   f"them two costed options: "
                   f"an unpriced intended-configuration validation outline "
                   f"and a narrowed claim at "
                   f"{narrowed.cost.wall_hours:.1f} h that supports a "
                   f"machinery statement only.  Proposal "
                   f"{summary['proposal_status']!r}, design digest "
                   f"{summary['proposal_design_digest'][:16]}...")
                  if not problems else "; ".join(problems[:6]), covers=(118,))


#: Ways a live source could name ticket 08 as an owner of the frozen budget.
#: Singular and plural, either order, hyphenated or spaced, with or without the
#: leading zero.  An independent review planted the **singular, reversed**
#: form -- "ticket 08 jointly owns the production numerical budget" -- in
#: ``__init__.py`` and both prose guards passed, because one pattern knew only
#: "belongs to tickets 07 and 08" and the other required the budget to come
#: first.
_T08_OWNER_SUBJECTS = (
    r"tickets?[-\s]*0?7\s*(?:and|&|/|,|\+)\s*0?8\b",
    r"tickets?[-\s]*0?8\s*(?:and|&|/|,|\+)\s*0?7\b",
    r"tickets?[-\s]*0?8\b",
)

#: Ways a source could assert that ownership, rather than one spelling of it.
_OWNERSHIP_VERBS = (
    r"(?:co[-\s]?|jointly\s+|joint\s+|part[-\s]?)?owns?\b",
    r"(?:co[-\s]?)?owned\b",
    r"(?:co[-\s]?|joint\s+|part[-\s]?)?owners?\b",
    r"ownership\b",
    r"shares?\b", r"shared\b", r"sharing\b",
    r"holds?\b", r"held\b",
    r"responsible\s+for\b", r"responsibility\s+for\b",
    r"belongs?\s+to\b", r"belonging\s+to\b",
)

#: What turns such a sentence into a true statement of absence.  Ticket 08 is
#: status 0 and owns nothing here, so a source *denying* the ownership is
#: correct and must not be flagged.
_OWNERSHIP_NEGATORS = (
    r"\bnot\b", r"\bno\b", r"\bnever\b", r"\bneither\b", r"\bnor\b",
    r"\bcannot\b", r"n't\b", r"\bwithout\b", r"\bnothing\b", r"\bnone\b",
    r"\bdenie[sd]\b", r"\bexcept\b", r"\bonly\s+ticket[-\s]*0?7\b",
)

#: Where one clause ends and the next begins.  An alignment review pointed out
#: that a negator *anywhere* in the window masked an affirmative relation:
#: "ticket 08 is not implemented but jointly owns the production numerical
#: budget" went unflagged because the sentence contained the word "not".
#: Negation has to scope to the ownership relation, so only the clause the
#: ownership verb actually sits in is searched for one.
_CLAUSE_BREAKERS = (
    r",", r";", r":", r"\band\b", r"\bbut\b", r"\byet\b", r"\bhowever\b",
    r"\balthough\b", r"\bthough\b", r"\bwhereas\b", r"\bwhile\b",
    r"\bwhilst\b", r"\bnonetheless\b", r"\bnevertheless\b",
)

#: The subject of the claim.  Written once so the three orders below cannot
#: drift apart.
_BUDGET_SUBJECT = r"production numerical budget"


def _budget_ownership_claims(prose):
    """Every **affirmative** claim that ticket 08 owns the frozen budget.

    Whitespace is folded first, so a line break inside the sentence changes
    nothing.  Three orders are searched -- subject before the budget, subject
    after it, and the passive "the budget is owned by ticket 08".

    **Negation scopes to the relation, not to the window.**  An alignment
    review pointed out that discarding a hit whenever a negator appeared
    anywhere in it let a sentence through whose first clause denied something
    else entirely and whose second clause asserted the ownership: the sentence
    contained "not", and that was enough.  So the text is cut at the last
    clause boundary before the ownership verb and only that clause is
    searched.  "ticket 08 does not own the production numerical budget" is
    still the true statement and still passes; a denial of implementation
    followed by "but jointly owns …" no longer does.  The exact sentences are
    pinned as controls in :func:`check_stale_stage_strings`, which is where
    they can be written out without the detector reading its own docstring.

    Returns the matched text of each surviving claim, folded.
    """
    folded = " ".join(prose.split())
    subject = "(?:" + "|".join(_T08_OWNER_SUBJECTS) + ")"
    verb = "(?:" + "|".join(_OWNERSHIP_VERBS) + ")"
    breakers = re.compile("(?:" + "|".join(_CLAUSE_BREAKERS) + ")",
                          re.IGNORECASE)
    orders = (
        rf"{subject}[^.|]{{0,60}}?({verb})[^.|]{{0,60}}?{_BUDGET_SUBJECT}",
        rf"{_BUDGET_SUBJECT}[^.|]{{0,80}}?{subject}[^.|]{{0,40}}?({verb})",
        rf"{_BUDGET_SUBJECT}[^.|]{{0,60}}?({verb})[^.|]{{0,40}}?{subject}",
    )
    claims = []
    for pattern in orders:
        for hit in re.finditer(pattern, folded, re.IGNORECASE):
            text = hit.group(0)
            # Everything from the start of the match up to the ownership verb,
            # then only the last clause of it.
            before = text[:hit.start(1) - hit.start()]
            splits = list(breakers.finditer(before))
            clause = before[splits[-1].end():] if splits else before
            if any(re.search(negator, clause, re.IGNORECASE)
                   for negator in _OWNERSHIP_NEGATORS):
                continue
            claims.append(text)
    return claims


def _campaign_claim_problems(sources):
    """Live sentences that tie a campaign to the checkpoint's derivation.

    After that route was removed, four docstrings and one error message in
    ``experiments.py`` still described it -- live API help, inside the
    discovered prose scope, describing a parameter and a field that no longer
    exist.  This is the guard that keeps them corrected.

    A sentence is reported when it names one of the subjects below, names the
    removed record, relates the two by one of the relations below, and carries
    no negator.  The separate planning machinery keeps its own truthful
    documentation: those sentences describe that record on its own terms, name
    no subject from this list, and are not in scope.

    Its patterns live inside this function and this function is skipped by the
    literal scan, for the same reason the fact table is: a detector whose own
    source text satisfies it is not a detector.
    """
    # What the sentence has to be *about* for a mention to be a claim about
    # the checkpoint rather than about the separate planning record.
    subjects = (r"checkpoint", r"handoff", r"alternatives?\b", r"option a\b",
                r"intended_configuration_option")
    # The relations that would make such a sentence false.
    relations = (r"derives?\s+from", r"derived\s+from", r"derives?\s+by",
                 r"derived\s+by", r"computed\s+from", r"computed\s+by",
                 r"built\s+from", r"built\s+by", r"builds?\b", r"rebuil[td]\b",
                 r"carr(?:y|ies|ied)\b", r"takes?\b", r"took\b",
                 r"holds?\b", r"uses?\b", r"reads?\b")
    subject = "(?:" + "|".join(subjects) + ")"
    relation = "(?:" + "|".join(relations) + ")"
    problems = []
    for name, prose in sources.items():
        folded = " ".join(prose.split())
        for sentence in re.split(r"(?<=[.!?])\s+|\|", folded):
            if "campaign" not in sentence.lower():
                continue
            if not re.search(subject, sentence, re.IGNORECASE):
                continue
            if not re.search(relation, sentence, re.IGNORECASE):
                continue
            if any(re.search(negator, sentence, re.IGNORECASE)
                   for negator in _OWNERSHIP_NEGATORS):
                continue
            problems.append(f"{name} ties a campaign to what the checkpoint "
                            f"derives: {sentence[:100]!r}.  The route was "
                            f"removed and the proposal freezes no such "
                            f"record")
    return problems


def _ownership_prose_problems(sources):
    """The same detector over the same discovered live-source set.

    Called by both prose checks, so a paraphrase planted in any live module is
    caught by whichever one a reader happens to run.
    """
    # The message deliberately avoids spelling the claim it looks for: this
    # function is itself inside the scanned literal set, and a detector that
    # trips on its own error message is not a detector.
    problems = []
    for name, prose in sources.items():
        for claim in _budget_ownership_claims(prose):
            problems.append(f"{name} names ticket 08 as an owner of the "
                            f"frozen numerical budget: {claim[:90]!r}.  "
                            f"Ticket 07 froze it and ticket 08 is status 0")
    return problems


def _live_prose_sources():
    """Every **live, user-facing** text this package presents, and only those.

    Four source files plus the verifier's own *printed* lines: the README a
    reader opens, the module docstrings and help text an API user reads, and
    the banner and per-check detail the verifier prints.  An independent review
    found the previous guard scanning ``README.md`` alone while the API
    docstrings and the verbose output still described a superseded lifecycle,
    a superseded count surface and a superseded pair of costed alternatives.

    **The historical execution notes are excluded by scope, not by pattern.**
    They live outside this package entirely and this function resolves nothing
    outside :data:`PACKAGE_DIR`; every round record is free to name its own
    superseded numbers, because a record of what round 2 reported is not a
    claim about what is true now.  :func:`check_current_facts` asserts that
    exclusion rather than assuming it.
    """
    # **Discovered, not enumerated.**  An independent review pointed out that
    # naming four modules would miss a stale claim moved into any of the other
    # sixteen.  The rule, stated rather than listed: *every* Python module in
    # the package directory, plus the README, is live user-facing text --
    # docstrings are the package's help and its prose is what a reader meets --
    # and the only exclusion is ``verify.py`` itself, which is scanned
    # separately below because two of its functions must spell superseded
    # values out.  Generated material never enters: ``results/`` and
    # ``__pycache__`` are directories, not modules, and the historical
    # execution notes live outside this directory entirely.
    modules = sorted(path.name for path in PACKAGE_DIR.glob("*.py"))
    if len(modules) < 15:
        raise AssertionError(f"only {len(modules)} package modules were "
                             f"discovered; the live-prose scan fails closed "
                             f"rather than scanning a truncated set")
    sources = {name: (PACKAGE_DIR / name).read_text(encoding="utf-8")
               for name in ["README.md"] + [name for name in modules
                                            if name != "verify.py"]}
    text = (PACKAGE_DIR / "verify.py").read_text(encoding="utf-8")
    # Only the *printed* lines of the verifier, so that the fact table below --
    # which necessarily spells every superseded value out -- does not flag
    # itself.  The banner is what a reader sees; the table is machinery.
    sources["verify.py (printed banner)"] = "\n".join(
        line for line in text.splitlines()
        if line.strip().startswith("print("))
    # The verbose output and the help text: **every string literal in the
    # verifier**, docstrings and check descriptions and the literal parts of
    # every ``Result`` detail f-string included, taken through ``ast`` rather
    # than by regular expression so that a detail line spread over six
    # implicitly concatenated pieces is scanned as the one sentence it prints
    # as.  This is the other thing a reader actually reads, and it was stale.
    #
    # Four functions are skipped, and only four: the fact table, the
    # current-fact guard, the stale-stage guard and the campaign-claim
    # detector, each of which must spell superseded values or its own match
    # patterns out in order to look for them.  Everything else in the file is
    # in scope.
    skip = {"_t07_current_facts", "check_current_facts",
            "check_stale_stage_strings", "_campaign_claim_problems"}
    pieces = []
    tree = ast.parse(text)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and \
                node.name in skip:
            node.body = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            pieces.append(node.value)
    sources["verify.py (check output and help)"] = "\n".join(pieces)
    return sources


